(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.6"]={"from":144,"a":[["\u0003רב פפא אמר:\u0004 משנה זו במסכת כתובות המונה את אחותו בין אלה שיש להן קנס מדברת \u0003במפותה, ו\u0004במפותה \u0003דברי הכל\u0004 אין מצילים אותה בנפשו, שהרי בא עליה ברצונה.","\u0003אביי אמר:\u0004 מדובר כאן באנוסה ו\u0003ביכול להציל\u0004 את הנערה \u0003באחד מאבריו\u0004 של האונס, שלא היה צריך להורגו לשם כך. \u0003ו\u0004כשיטת \u0003ר' יונתן בן שאול היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן בן שאול אומר: רודף שהיה רודף אחר חבירו להורגו, ויכול\u0004 הנרדף או שאר אדם \u0003להצילו באחד מאבריו\u0004 בלבד בלא להרגו \u0003ולא הציל\u0004 באופן זה אלא הרג את הרודף — \u0003נהרג עליו\u0004 כרוצח.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יונתן בן שאול?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי ינצו אנשים\u0004 ונגפו אשה הרה ויצאו ילדיה ולא יהיה אסון ענוש יענש כאשר ישית עליו בעל האשה ונתן בפלילים\u0003\"\u0004 (שמות כא, כב), \u0003ו\u0004על כך \u0003אמר ר' אלעזר: במצות\u0004 (קטטה) \u0003שבמיתה,\u0004 ששני האנשים רוצים להרוג זה את זה, \u0003הכתוב מדבר,\u0004 וראיה לכך — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואם אסון יהיה ונתתה נפש תחת נפש\"\u0004 (שם כג), ואם לא היה מתכוון כלל להרוג — מדוע יהרגוהו? \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003\"ולא יהיה אסון ענוש יענש\"\u0004 (שם כב), לומר שהוא משלם דמי ולדות לבעל האשה.","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי ה\u0003יכול להציל\u0004 את עצמו או את חבירו הנרדף \u0003באחד מאבריו\u0004 של הרודף \u0003לא ניתן להצילו בנפשו,\u0004 ואם הרג את תוקפו במקום לפוצעו חייב מיתה — \u0003היינו דמשכחת לה\u0004 \u0005[זהו שאתה מוצא אותה]\u0006 אפשרות ש\u0003יענש,כגון שיכול להציל\u0004 את הנרדף \u0003באחד מאבריו\u0004 של הרודף, נמצא שלא היה המכה נתון באיום של מיתה כלל, ולכן משלם קנס.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שגם אם \u0003יכול להציל באחד מאבריו נמי\u0004 \u0005[גם כן]\u0006 \u0003ניתן להצילו בנפשו, היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 אפשרות ש\u0003יענש?\u0004 והרי בשעה שרדף אחר חבירו להורגו סיכן עצמו למיתה (שהיה כל אדם רשאי להורגו אז), ולפי הכלל, מי שנסתכן בעונש מוות — שוב אין עליו חובת תשלומים!","ומנסים לדחות: \u0003דילמא שאני הכא\u0004 \u0005[שמא שונה כאן]\u0006 דבר זה משום שחובותיו אינם לאדם אחד, שכן \u0003מיתה לזה ותשלומין לזה,\u0004 שהרי עונש המוות מתחייב לאדם אחד (למי שנתכוון להורגו) ותשלומים לבעל האשה, ולפיכך מתחייב בשניהם.","ועונים: בכל זאת \u0003לא שנא\u0004 \u0005[אינו שונה],\u0006 שכן \u0003אמר רבא: רודף שהיה רודף אחר חבירו\u0004 להורגו \u0003ו\u0004תוך כדי רדיפה \u0003שיבר\u0004 הרודף \u0003את הכלים, בין של נרדף ובין של כל אדם\u0004 — \u0003פטור\u0004 מלשלם. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שכן \u0003מתחייב בנפשו הוא,\u0004 שהרי כל אדם רשאי להמיתו, והמתחייב בנפשו פטור מן התשלומים, אפילו תשלומים לאדם אחר, שלא היה מעורב בדבר.","\u0003ונרדף ששיבר את הכלים\u0004 תוך כדי מנוסתו, אם שיבר את כליו \u0003של רודף\u0004 — \u0003פטור,\u0004 ואם שיבר כלים \u0003של כל אדם\u0004 — \u0003חייב\u0004 אחר כך לשלם. ומסבירים: אם היו הכלים \u0003של רודף, פטור\u0004 — \u0003שלא יהא ממונו\u0004 של רודף \u0003חביב עליו מגופו,\u0004 שהרי אם היה הנרדף פוגע בגופו של הרודף היה פטור. ואם היו הכלים \u0003של כל אדם, חייב\u0004 — \u0003שמציל עצמו בממון חבירו,\u0004 ואין אותו אדם צריך להפסיד משום כך — ולכן חייב לשלם לו.","\u0003ורודף שהיה רודף אחר רודף להצילו,\u0004 כלומר, שניסה להציל את הנרדף על ידי הריגת הרודף, \u0003ושיבר\u0004 בתוך כך \u0003את הכלים, בין\u0004 אם הם היו \u0003של\u0004 ה\u0003רודף, בין של\u0004 ה\u0003נרדף, בין של כל אדם\u0004 — \u0003פטור.\u0004 ומעירים: ודבר זה \u0003לא מן הדין\u0004 הוא, שאין לכך בסיס בהלכה הכללית, אלא תקנת חכמים היא \u0003שאם אי\u0004 (אין) \u0003אתה אומר כן, נמצא אין לך כל אדם שמציל את חבירו מיד הרודף,\u0004 שיחשוש שמא יצטרך לשלם עבור נזקים שיזיק תוך כדי הצלה זו ויימנע איפוא מלהציל.","שנינו במשנה: \u0003אבל הרודף אחר בהמה\u0004 או עובד עבודה זרה אין מצילים אותו בנפשו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: העובד עבודה זרה ניתן להצילו בנפשו.\u0004 ודבר זה נלמד \u0003מקל וחומר\u0004 זה: \u0003ומה פגם הדיוט,\u0004 כגון אונס שהוא פוגם בכבודה של אשה \u0003ניתן להצילו בנפשו,\u0004 דבר שהוא \u0003פגם גבוה\u0004 שעובד עבודה זרה ומבזה את ה' בכך \u0003לא כל שכן?!\u0004 ומקשים: \u0003וכי עונשין מן הדין,\u0004 וכי מענישים אדם רק על פי קל וחומר? ומשיבים: \u0003קא סבר\u0004 \u0005[סבר]\u0006 ר' שמעון: \u0003עונשין מן הדין.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר בר' שמעון אומר: המחלל את השבת ניתן להצילו בנפשו,\u0004 ומסבירים את טעמו: \u0003סבר לה כאבוה\u0004 \u0005[סבר הוא כאביו\u0006 ר' שמעון\u0005]\u0006 ש\u0003אמר: עונשין מן הדין. ואתיא\u0004 \u0005[ובאה,\u0006 נלמדת\u0005]\u0006 \u0003שבת\u0004 בגזירה שווה מן המלים \u0003\"חילול\" \"חילול\" מעבודה זרה\u0004 שבשתיהן כתובה המלה חילול.","כיון שהוזכרו עבירות חמורות שהורגים את המנסה לעבור עליהן, דנים במצוות שמותר ושאסור לעבור עליהן בשעת סכנה. \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: נימנו\u0004 דעות החכמים שדנו בנושא \u0003וגמרו בעלית בית\u0004 משפחת \u0003נתזה בלוד: כל עבירות בתורה, אם אומרין לאדם: עבור, ואל תהרג\u0004 — \u0003יעבור\u0004 עליהן \u0003ואל יהרג,\u0004 מפני שסכנת נפש דוחה כל אלה. \u0003חוץ מעבודה זרה וגילוי עריות ושפיכות דמים,\u0004 שיהרג ואל יעבור.","ושואלים: \u0003ועבודה זרה לא\u0004 יעבור בשעת איום מיתה? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל: מנין שאם אמרו לו לאדם: עבוד עבודה זרה ואל תהרג, מנין שיעבוד ואל יהרג\u0004 — \u0003תלמוד לומר: \"\u0004ושמרתם את חוקתי ואת משפטי אשר יעשה אותם האדם \u0003וחי בהם\"\u0004 (ויקרא יח, ה), וכוונתו שלחיים נועדו המצוות \u0003ולא שימות בהם\u0004 ובגללן.","\u0003יכול אפילו\u0004 מותר לעשות כן \u0003בפרהסיא\u0004 בפני רבים? — \u0003תלמוד לומר: \"ולא תחללו את שם קדשי ונקדשתי\u0004 בתוך בני ישראל אני ה' מקדשכם\u0003\"\u0004 (שם כב, לב), משמע שאין נהרגים על עבודה זרה בשעה שאינה בפרהסיה!","ומשיבים: \u0003אינהו\u0004 \u0005[הם,\u0006 בעליית בית נתזה\u0005]\u0006 \u0003דאמור\u0004 \u0005[שאמרו]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר \u0003\"ואהבת את ה' אלהיך בכל לבבך ובכל נפשך ובכל מאדך\"\u0004 (דברים ו, ה), ומעתה, \u0003אם נאמר \"בכל נפשך\", למה נאמר \"בכל מאדך\",\u0004 שמשמעו בכל ממונך?! \u0003ואם נאמר \"בכל מאדך\", למה נאמר \"בכל נפשך\"?\u0004","והוא מסביר: \u0003אם יש לך אדם שגופו חביב עליו מממונו\u0004 — \u0003לכך נאמר \"בכל נפשך\", ואם יש לך אדם שממונו חביב עליו מגופו\u0004 — \u0003לכך נאמר \"בכל מאדך\",\u0004 משמע שעל אהבת ה' ועבודתו חייבים למסור את הנפש.","\u0003גילוי עריות ושפיכות דמים\u0004 מנין שמוסרים את הנפש עליהם — כדברי \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר \u0003\"\u0004ולנערה לא תעשה דבר אין לנערה חטא מות \u0003כי כאשר יקום איש על רעהו ורצחו נפש כן הדבר הזה\"\u0004 (שם כב, כו) \u0003וכי מה למדנו\u0004 בהלכה זו \u0003מרוצח,\u0004 והלא אין לומדים כל דבר חדש מדימוי זה שלא ידענו קודם מעצם הציווי \"ולנערה לא תעשה דבר\", אלא","\u0003מעתה הרי\u0004 דימוי \u0003זה בא\u0004 לכאורה \u0003ללמד\u0004 על הנערה המאורסה \u0003ונמצא למד\u0004 לענין רוצח, כי \u0003מקיש\u0004 \u0005[משוה]\u0006 כתוב זה \u0003רוצח לנערה המאורסה, מה נערה המאורסה ניתן להצילו בנפשו\u0004 של האונס, \u0003אף רוצח ניתן להצילו\u0004 לזה שרוצה לרוצחו \u0003בנפשו\u0004 של הרוצח.","\u0003ו\u0004עוד, \u0003מקיש\u0004 \u0005[משווה]\u0006 \u0003נערה המאורסה לרוצח\u0004 לענין אחר: \u0003מה רוצח יהרג ואל יעבור\u0004 ולא ירצח, \u0003אף נערה המאורסה\u0004 — \u0003תהרג ואל תעבור.\u0004","ושואלים: \u0003רוצח גופיה מנא לן\u0004 \u0005[עצמו מנין לנו]\u0006 שיהרג ואל יהרוג אחרים? ומשיבים: \u0003סברא הוא\u0004 בדבר, ואינו צריך מקרא מיוחד. \u0003דההוא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003רבה,\u0004 \u0003ואמר ליה\u0004 \u0005[לו],\u0006 \u0003אמר לי מרי דוראי\u0004 \u0005[אדון הכפר שלי]:\u0006 \u0003זיל קטליה לפלניא\u0004 \u0005[לך הרוג את פלוני],\u0006 \u0003ואי\u0004 (אם) \u0003לא\u0004 — \u0003קטלינא לך\u0004 \u0005[אהרוג אותך],\u0006 ומה אעשה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לקטלוך ולא תיקטול\u0004 \u0005[שיהרגוך ואל תהרוג],\u0006 \u0003מי יימר דדמא דידך סומק טפי\u0004 \u0005[מי אומר שדמך אדום יותר]?\u0006 \u0003דילמא דמא דהוא גברא סומק טפי\u0004 \u0005[שמא דמו של אותו אדם אדום יותר],\u0006 ואין דוחים נפש מפני נפש, ואין אדם רשאי להציל עצמו בהריגת חבירו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: לא שנו\u0004 שמותר לעבור על המצוות מפני סכנת מוות \u0003אלא שלא בשעת השמד,\u0004 שגזרה מלכות להעביר את ישראל על דתם, \u0003אבל בשעת השמד, אפילו\u0004 גזרו על \u0003מצוה קלה\u0004 — \u0003יהרג ואל יעבור.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: אפילו שלא בשעת השמד, לא אמרו\u0004 שרשאי לעבור \u0003אלא\u0004 כשהאנס אמר לו לעבור \u0003בצינעא, אבל\u0004 אם מצווהו לעבור \u0003בפרהסיא, אפילו\u0004 מאיימים עליו במוות לעבור על \u0003מצוה קלה\u0004 — \u0003יהרג ואל יעבור.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003מצוה קלה\u0004 זו שאמרו? \u0003אמר רבא בר רב יצחק אמר רב:\u0004"],["\u0003אפילו לשנויי ערקתא דמסאנא\u0004 \u0005[לשנות\u0006 את \u0005רצועת הסנדל]\u0006 אם יש צד של מנהג ישראל כשר בענין זה, וגוזרים עליו לשנותו ולהידמות לגוי — חייב למסור את נפשו על כך.","ושואלים: \u0003וכמה\u0004 אנשים היא \u0003פרהסיא? אמר ר' יעקב אמר ר' יוחנן: אין פרהסיא פחותה מעשרה בני אדם.\u0004 ומבארים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 לנו כי \u0003ישראלים בעינן\u0004 \u0005[צריכים אנו]\u0006 לענין זה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפסוק המלמד על כך: \u0003\"ונקדשתי בתוך בני ישראל\"\u0004 (ויקרא כב, לב). \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 היו במקום \u0003תשעה ישראל וגוי אחד מהו\u0004 הדין בכגון זה, האם פרהסיה היא, או לא?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב ינאי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' חייא בר אבא\u0004 ברייתא זו: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"תוך\" \"תוך\"; כתיב הכא\u0004 \u0005[כתוב כאן]:\u0006 \u0003\"ונקדשתי בתוך בני ישראל\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בחטא קרח: \u0003\"הבדלו מתוך העדה הזאת\"\u0004 (במדבר טז, כא), ולמדים גזירה שוה \"עדה\" האמורה כאן מ\"עדה\" שנאמרה במרגלים (שם יד, כז): \u0003מה להלן\u0004 עדה זו של מרגלים \u0003עשרה\u0004 היתה, \u0003וכולהו\u0004 \u0005[וכולם]\u0006 מ\u0003ישראל, אף כאן\u0004 לענין קידוש ה' צריך שיהיו \u0003עשרה וכולהו\u0004 \u0005[וכולם]\u0006 מ\u0003ישראל.\u0004","על ההלכות הללו מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אסתר\u0004 שנבעלה לאחשורוש עבירה ב\u0003פרהסיא הואי\u0004 \u0005[היתה],\u0006 ומדוע לא מסרה נפשה? ומשיבים, \u0003אמר אביי: אסתר קרקע עולם היתה,\u0004 שהמצוה למסור נפש ולא לעבור בעריות היא רק בגבר, משום שהוא עושה מעשה של עבירה אבל אשה שהיא אינה עושה מעשה בפועל והיא נבעלת בלבד, אינה חייבת למסור נפשה.","\u0003רבא אמר\u0004 טעם אחר: \u0003הנאת עצמן שאני\u0004 \u0005[שונה],\u0006 כלומר, דבר שהגויים עושים לא כדי להעביר על הדת אלא לצורך הנאה שלהם, אין בה חובת מסירות נפש אף בפרהסיה.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כן]\u0006 שיש הבדל בין הנאת עצמם למה שאינו הנאת עצמם, אם כן \u0003הני קוואקי ודימוניקי היכי יהבינן להו\u0004 \u0005[אותם כלים להחזיק בהם גחלים איך אנו נותנים להם]?\u0006 שהיו הכמרים הפרסים נוטלים מכל בית כלים ושמים בהם גחלי אש ומביאים לבית עבודה זרה שלהם בימים מסויימים. והרי יש בכך סיוע לעבודה זרה בפרהסיה, וישראל אינם מוסרים נפשם על כך. \u0003אלא\u0004 ודאי הטעם הוא שדבר שהוא \u0003הנאת עצמן\u0004 של הגויים \u0003שאני\u0004 \u0005[שונה],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אסתר \u0003הנאת עצמן שאני\u0004 \u0005[שונה]\u0006 ואין חובת מסירות נפש בכך.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: גוי\u0004 ש\u0003אמר ליה להאי\u0004 \u0005[לאותו]\u0006 \u0003ישראל: קטול אספסתא בשבתא ושדי לחיותא\u0004 \u0005[קצור אספסת בשבת והשלך ל\u0006פני ה\u0005בהמות],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תעשה כן, \u0003קטילנא לך\u0004 \u0005[אהרוג אותך]\u0006 — \u0003ליקטיל\u0004 \u0005[שיקצור]\u0006 \u0003ולא לקטליה\u0004 \u0005[יהרגוהו].\u0006 אם אמר לו הגוי: קצור את האספסת \u0003שדי לנהרא\u0004 \u0005[\u0006ו\u0005זרוק לנהר]\u0006 — \u0003ליקטליה\u0004 \u0005[שיהרגוהו]\u0006 \u0003ולא ליקטול\u0004 \u0005[יקצור],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 במקרה זה? — כי ברור \u0003לעבורי מילתא קא בעי\u0004 \u0005[שרוצה\u0006 הוא \u0005להעביר אותו,\u0006 על הדת\u0005]\u0006 ולא להנאת עצמו.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003ר' אמי:\u0004 האם \u0003בן נח\u0004 כיון שנצטוה על עבודה זרה \u0003מצווה על קדושת השם או אין מצווה על קדושת השם?\u0004","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003שבע מצות נצטוו בני נח. ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שיש גם מצוה זו של קידוש ה', הרי \u0003תמני הויין\u0004 \u0005[שמונה\u0006 מצוות \u0005הן]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 מכאן אין ראיה, שכן אותן שבע מצוות הכוונה \u0003אינהו\u0004 \u0005[הן]\u0006 \u0003וכל אבזרייהו\u0004 \u0005[פרטיהן],\u0006 ומצוות קידוש השם אפשר לראותה כפרט מאיסור עבודה זרה.","כיון שלא הוכרע הדבר שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 מה התשובה לבעיה זו? \u0003אמר רב אדא בר אהבה, אמרי בי\u0004 \u0005[אמרו\u0006 החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב:\u0004 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בנעמן הארמי: \u0003\"לדבר הזה יסלח ה' לעבדך בבוא אדני בית רמון להשתחות שמה והוא נשען על ידי והשתחויתי\"\u0004 (מלכים ב' ה, יח), כלומר, היה נאלץ להשתחוות לעבודה זרה מפני אימת אדוניו מלך ארם, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר לו לך לשלום\"\u0004 (שם, יט), משמע שהתיר לו לעשות כן."],["\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה שבן נח מצווה על קידוש ה' — ש\u0003לא לימא ליה\u0004 \u0005[יאמר לו]\u0006 \"לך בשלום\" שמשמע שמסכים לו! ומשיבים: \u0003הא\u0004 \u0005[זה]\u0006 שהתיר לו היה \u0003בצנעה, הא\u0004 \u0005[זה]\u0006 שאסור הוא \u0003בפרהסיא,\u0004 שהרי השתחויית נעמן היתה בצינעה, שלא בפני עשרה מישראל, ושמא בפרהסיה בפני ישראל היה חייב למסור נפשו. ואם כן לא נמצא פתרון לשאלתנו.","אגב הדברים שהסברנו בענין חובת \"יהרג ואל יעבור\" לגבי עריות, \u0003אמר רב יהודה אמר רב: מעשה באדם אחד שנתן עיניו\u0004 לאהבה \u0003באשה אחת והעלה לבו טינא\u0004 שנעשה חולה מאהבה, \u0003ובאו ושאלו לרופאים\u0004 מה לעשות בו. \u0003ואמרו: אין לו תקנה עד שתבעל\u0004 לו. \u0003אמרו חכמים: ימות ואל תבעל לו.\u0004 אמרו הרופאים: לפחות \u0003תעמוד לפניו ערומה.\u0004 אמרו חכמים: \u0003ימות ואל תעמוד לפניו ערומה.\u0004 הציעו הרופאים: \u0003תספר\u0004 (תשוחח) \u0003עמו מאחורי הגדר\u0004 במקום צינעה, שיהיה לו מעט נחת בדבר. אמרו חכמים: \u0003ימות ולא תספר עמו מאחורי הגדר.\u0004","ומעירים, \u0003פליגי בה\u0004 \u0005[נחלקו ב\u0006ענין \u0005זה]\u0006 \u0003רב יעקב בר אידי ור' שמואל בר נחמני. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אשת איש היתה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פנויה היתה.\u0004 ומבררים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח\u0006 לשיטת \u0005מי שאומר]\u0006 ש\u0003אשת איש היתה, שפיר\u0004 \u0005[יפה]\u0006 ומובן הדבר, שיש כאן משום גילוי עריות ושאר דברים השייכים לכך, ולפיכך לא הותר לו שום קירוב אליה. \u0003אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 ש\u0003פנויה היתה מאי כולי האי\u0004 \u0005[מה כל זה],\u0006 מדוע אמרו שימות ולא תעשה מה שביקש?","\u0003רב פפא אמר:\u0004 הטעם הוא \u0003משום פגם משפחה,\u0004 שאין רשות לבייש את משפחתה בשל כך. \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: כדי שלא יהו בנות ישראל פרוצות בעריות,\u0004 שאם ישמעו לטענה שכזו, יהיו בנות ישראל מופקרות לכל מי שמתאוה להן.","ושואלים: אם פנויה היתה, \u0003ולינסבה מינסב\u0004 \u0005[ושיישא אותה]!\u0006 ומשיבים: \u0003לא מייתבה דעתיה\u0004 \u0005[תתישב דעתו]\u0006 על ידי נישואין, מפני הטעם שאמר \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק: מיום שחרב בית המקדש ניטלה טעם ביאה\u0004 של היתר \u0003וניתנה לעוברי עבירה, שנאמר: \"מים גנובים ימתקו ולחם סתרים ינעם\"\u0004 (משלי ט, יז), ולכן לא תתיישב דעתו של זה על ידי נישואין.","","\u0003ואלו הן הנשרפין: הבא על אשה ובתה, ובת כהן שזנתה.\u0004","ומבארים: \u0003יש בכלל\u0004 איסור ועונש \u0003אשה ובתה\u0004 הכתובים בתורה גם מי שבא על \u0003בתו, ובת בתו ובת בנו\u0004 ועל \u0003בת אשתו\u0004 אפילו אינה בתו \u0003ובת בתה\u0004 של אשתו \u0003ובת בנה,\u0004 ובכלל איסור זה גם הבא על \u0003חמותו\u0004 וכן בכלל זה הבא על \u0003אם חמותו ואם חמיו,\u0004 והאיסור חל בין אם נשא קודם את האשה ואחר כך בא על בתה, ובין אם להיפך, שנשא תחילה הבת ואחר כך בא על האם.","מעירים: \u0003הבא על אשה שנשא\u0004 את \u0003בתה\u0004 תחילה \u0003לא קתני\u0004 \u0005[שנה],\u0006 \u0003אלא\u0004 שנה בסגנון זה: \u0003הבא על אשה ובתה\u0004 נידון בשריפה, \u0003מכלל\u0004 הדברים אתה למד \u0003דתרוייהו לאיסורא\u0004 \u0005[ששתיהן לאיסור],\u0006 כלומר, שכאשר בא גם על הראשונה עבר על איסור שחייב עליו שריפה. \u0003ומאן נינהו\u0004 \u0005[ומה הן]\u0006 אשה ובתה אלה — כגון \u0003חמותו ואם חמותו.\u0004 שאם נשא תחילה אשה, ואחר כך בא על אם חמותו ועל חמותו עובר משום אשה ובתה, גם על האם וגם על הבת.","\u0003וקתני\u0004 \u0005[ושנה]\u0006 כאן: \u0003יש בכלל אשה ובתה\u0004 עוד הלכות נוספות, \u0003מכלל\u0004 הדברים אתה למד \u0003דתרוייהו\u0004 \u0005[ששתיהן],\u0006 גם איסור ועונש חמותו ואם חמותו \u0003כתיבי בהדיא\u0004 \u0005[כתובים במפורש]\u0006 במקרא, \u0003והנך מדרשא אתיא\u0004 \u0005[ואלה,\u0006 השאר \u0005מדרשה באו].\u0006","\u0003הניחא\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת הלימוד של \u0003אביי\u0004 ש\u0003אמר\u0004 בביאור מחלוקת ר' ישמעאל ור' עקיבא להלן, כי רק \u0003משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 כלומר, אינם חולקים בגופן של הלכות אלא רק בלימוד ההלכה מן המקראות. ואם כן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא,\u0004 המפרש שאם חמותו נזכרת במקרא במפורש.","\u0003אלא לרבא\u0004 ש\u0003אמר\u0004 שיש הבדל ביניהם אף לגבי פסק ההלכה ונחלקו לגבי איסור \u0003חמותו לאחר\u0004 ה\u0003מיתה\u0004 של אשתו, ולדעתו אין הכתוב מדבר כלל באם חמותו, אם כן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 —אינה לא כשיטת ר' ישמעאל ולא כשיטת ר' עקיבא! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא, תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003\"הבא על אשה שנשא\u0004 את \u0003בתה\".\u0004","שנינו במשנה ש\u0003יש בכלל\u0004 איסור \u0003אשה ובתה\u0004 גם איסור ב\u0003חמותו ואם חמותו ואם חמיו.\u0004 ומעירים: \u0003ל\u0004שיטת \u0003אביי\u0004 שלדעת הכל אם חמותו אסורה מן הכתוב המפורש בתורה, והלא מן המשנה נראה שהיא נלמדת רק מדרשת הכתוב! יש לומר כי \u0003איידי דקא בעי למיתנא\u0004 \u0005[מתוך שרצה לשנות\u0006 הלאה\u0005]\u0006 \u0003אם חמיו, תני נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003חמותו ואם חמותו,\u0004 אף שמפורשת בתורה. ו\u0003ל\u0004שיטת \u0003רבא\u0004 שאשה ובתה שבמשנה זו היא חמותו, מה טעם לחזור ושנותה פעמיים, יש לומר כי \u0003איידי דקא בעי למיתנא\u0004 \u0005[מתוך שרצה לשנות]\u0006 \u0003אם חמיו ואם חמותו תני נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003חמותו,\u0004 שהרי לדעת הכל חמותו כתובה במפורש בתורה.","","לעצם ההלכה שבמשנה שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הנאמר \u0003\"ואיש אשר יקח את אשה ואת אמה\u0004 זימה היא באש ישרפו אותו ואתהן ולא תהיה זימה בתוככם\u0003\"\u0004 (ויקרא כ, יד) — \u0003אין לי אלא\u0004 שלוקח \u0003אשה ואמה,\u0004 אך אם לוקח \u0003בת אשה\u0004 הנשואה לו, או את \u0003בת בתה,\u0004 או את \u0003בת בנה, מנין\u0004 שחייב אותו עונש?","— \u0003נאמר כאן \"זמה\", ונאמר להלן\u0004 \u0003\"זמה\"\u0004 (\"ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה לא תקח לגלות ערותה שארה הנה זימה היא\". שם יח, יז), \u0003מה להלן\u0004 האיסור הוא ב\u0003בתה ובת בתה ובת בנה\u0004 כמפורש, \u0003אף כאן\u0004 לענין עונש שריפה \u0003בתה ובת בתה ובת בנה\u0004 בכלל.","\u0003מנין\u0004 \u0003לעשות זכרים כנקבות\u0004 לענין איסור קרבה זו? \u0003נאמר כאן \"זמה\" ונאמר להלן \"זמה\", מה להלן זכרים כנקבות אף כאן זכרים כנקבות.\u0004","\u0003מנין לעשות למטה כלמעלה\u0004 — \u0003נאמר כאן \"זמה\" ונאמר להלן \"זמה\", מה להלן למטה כלמעלה אף כאן למטה כלמעלה, ומה כאן למעלה כלמטה אף להלן למעלה כלמטה,\u0004 שעל ידי הגזירה השוה למדים שני הכתובים זה מזה לכל ענין. ומעתה מבררים את דברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"מנין לעשות זכרים כנקבות\",\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"לעשות \u0003זכרים כנקבות\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שבת הבן (הזכר) תיחשב כבת הבת (הנקבה), שיהא דין \u0003בת בנה כבת בתה\u0004 — אולם זה אינו צריך גזירה שווה שהרי \u0003בהדי הדדי קאתיאן\u0004 \u0005[\u0006הרי \u0005ביחד הן באות],\u0006 ששתיהן כתובות באותו המקרא!","\u0003אלא\u0004 נאמר שפירוש הדברים הוא לעשות שתהא \u0003אם חמיו\u0004 אסורה \u0003כאם חמותו.\u0004 ואולם, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 עדיין \u0003אם חמותו לא קמה לן\u0004 \u0005[עמדה לנו],\u0006 כלומר, לא הוכחנו בשלמות שאמנם כתובה היא במקרא, \u0003אם חמיו מיהדר עלה\u0004 \u0005[נחזר עליה]\u0006 ללמוד אותה? והרי עדיין היסוד מפוקפק!"],["\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003מנין לעשות שאר\u0004 (קרבה) \u0003הבא ממנו,\u0004 כלומר, בת בתו או בת בנו \u0003כשאר הבא ממנה,\u0004 כבתה ובת בתה — \u0003נאמר כאן \"זמה\" ונאמר להלן \"זמה\".\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ב\u0004ענין העובר על \u0003שאר דידיה\u0004 \u0005[שלו]\u0006 \u0003לא כתיבא ביה\u0004 \u0005[נאמרה בו]\u0006 לשון \u0003\"זמה\",\u0004 שהרי נאמר רק \"ערות בת בנך או בת בתך לא תגלה ערותן כי ערותך הנה\" (ויקרא יח, י).","\u0003אמר רבא: אמר לי רב יצחק בר אבודימי,\u0004 בתחילה \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה מהמילים \u0003\"הנה\" \"הנה\"\u0004 הכתובה גם בשאר שלו (\"כי ערותך הנה\") וגם בשאר שלה (\"שארה הנה זמה היא\". שם יז), ואחר כך \u0003אתיא\u0004 \u0005[בא]\u0006 הדבר ונלמד העונש באלה בגזירה שווה \u0003\"זמה\" \"זמה\"\u0004 האמורה כאן והאמורה בעונשין \"ואיש אשר יקח את אשה ואת אמה זימה היא באש ישרפו אותו ואתהן\" (שם כ, יד).","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003מנין לעשות למטה כלמעלה.\u0004 ושואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"למטה כלמעלה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהפירוש הוא: \u0003בת בנה ובת בתה\u0004 שהן למטה בסדר הדורות שייחשבו \u0003כבתה,\u0004 והלא \u0003בהדי הדדי קאתיין\u0004 \u0005[יחד הן באות\u0006 בלי להבדיל\u0005]\u0006 מאותם כתובים עצמם.","\u0003אלא\u0004 תאמר, שהכוונה לעשות את \u0003אם חמיו ואם חמותו כחמותו.\u0004 ואולם אם כן \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"למטה כלמעלה\"\u0004 אינו נכון כלל, והיה לו לומר \u0003\"\u0004לעשות \u0003למעלה\u0004 (כלומר, דורות האבות) \u0003כלמטה\"!\u0004 ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003\"למעלה כלמטה\".\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אומר אתה נראה מה הוא המשך הדברים — \u0003\"נאמר כאן 'זמה' ונאמר להלן 'זמה' \"\u0004וכיצד מסבירים את הדבר? \u0003ומה השתא אינהי לא כתיבא\u0004 \u0005[ומה עכשיו הן עצמן,\u0006 אם חמותו ואם חמיו, \u0005אינן כתובות]\u0006 כלל בתורה, ומדרשה בלבד נלמדו, \u0003זמה דידהו כתיבא\u0004 \u0005[\u0006שנאמרה \u0005לגביהן כתובה]?\u0006 וכיצד עושים גזירה שווה מדבר שאינו כתוב כלל?","\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא בברייתא: \u0003מנין לעשות שלשה דורות למעלה\u0004 מאשתו, כלומר, אשתו וחמותו (הרי דור שני) ואם חמותו (דור שלישי), \u0003כשלשה דורות למטה\u0004 (אשתו, בתו, ובת בתו)? — \u0003נאמר למטה\u0004 בענין בת אשתו \u0003\"זמה\" ונאמר למעלה \"זמה\", מה למטה\u0004 האיסור חל עד \u0003שלשה דורות, אף למעלה\u0004 חל האיסור עד \u0003שלשה דורות\u0004","\u0003ומה\u0004 לגבי \u0003עונש עשה למטה כלמעלה, אף באזהרה נמי\u0004 \u0005[גם כן]\u0006 \u0003עשה למעלה כלמטה,\u0004 ללמד שיש איסור \"לא תעשה\" בדבר.","\u0003רב אשי אמר: לעולם\u0004 עליך לשנות \u0003כדקתני\u0004 \u0005[כמו ששנוי\u0006 לפנינו\u0005]\u0006 בלא לתקן את הגרסה, \u0003ומאי\u0004 \u0005[ומה]\u0006 משמעות \u0003\"למטה\"\u0004 האמור כאן — כוונתו: \u0003למטה באיסור,\u0004 כלומר, אין להבין \"למעלה\" ו\"למטה\" בענין דורות קודמים ומאוחרים, אלא \"למעלה\" משמעו איסור חמור יותר, ו\"למטה\" איסור קל יותר.","ומקשים: לפי מסקנה זו שעושה קרוביו כקרובי אשתו ולמטה כלמעלה, נאמר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מה\u0004 \u0003היא\u0004 אשתו \u0003אם אמה אסורה, אף הוא אם אמו אסורה\u0004 ויהא הבא עליה חייב שריפה!","\u0003אמר אביי:\u0004 אי אפשר לומר כן, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ערות אביך וערות אמך לא תגלה \u0003אמך היא\u0004 לא תגלה ערותה\" (שם יח, ז), וההדגשה ללמד: \u0003משום אמו אתה מחייבו, ואי\u0004 (אין) \u0003אתה מחייבו משום אם אמו.\u0004","\u0003רבא אמר\u0004 טעם אחר: \u0003בין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שלגבי גזירה שווה נוקטים בשיטה של \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 כלומר, כאשר למדים מגזירה שווה אין למדים רק באותו פרט עצמו שיש בו השוואת המילים, אלא כל מה שנאמר בדבר אחד קיים גם בשני. \u0003ובין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 לגבי לימוד בגזירה שווה \u0003דון מינה ואוקי באתרה\u0004 \u0005[ממנה,\u0006 מהדבר שלומד, \u0005והעמד במקומה],\u0006 ולא תלמד נושאים נוספים לאלה הנלמדים במישרין מן הגזירה השווה, \u0003לא אתיא\u0004 \u0005[אינו בא],\u0006 אי אפשר לקבל את ההנחה שיהא חייב על אם אמו. כיצד?","— \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ומינה,\u0004 אפשר ללמוד כך: \u0003מה היא\u0004 (אשתו) \u0003אם אמה אסורה, אף הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003אם אמו אסורה, ומינה\u0004 \u0005[וממנה]\u0006 נלמד גם כן לעניינים נוספים: \u0003מה היא\u0004 אם בא על אם אמה הריהו נידון \u0003בשריפה, אף הוא נמי\u0004 \u0005[גם כן]\u0006 אם בא על אם אמו יהיה חייב \u0003בשריפה,\u0004 ומעתה נוכיח כי דעה כגון זה אינה יכולה להתקבל על הדעת.","\u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003שריפה חמורה\u0004 יותר מסקילה — \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 השוואה זו, ולומר: \u0003מה להיא\u0004 שחייב על אם אמה שריפה \u0003שכן\u0004 אם בא על \u0003אמה\u0004 חייב \u0003בשריפה, תאמר בהוא,\u0004 אם בא על \u0003אמו\u0004 יהיה חייב \u0003בסקילה\u0004 בלבד ואין חומרת הדברים שווה.","\u0003 ועוד\u0004 יש להקשות בדרך זו: אם בא על \u0003אמו\u0004 שהיא קרובה לו חייב \u0003סקילה,\u0004 על \u0003אם אמו\u0004 שהיא רחוקה יותר יהיה חייב \u0003בשריפה,\u0004 שלשיטה זו היא מיתה חמורה יותר?!","\u0003ועוד\u0004 יש להקשות: \u0003מה היא\u0004 (אשתו וקרובותיה) \u0003לא חלקת בה\u0004 בעונש \u0003בין אמה לאם אמה, אף הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תחלוק בו בין אמו לאם אמו.\u0004 ואם כן הרי זו הוכחה שההשוואה בין אם אמו ואם אמה אינה יכולה להתקיים.","\u0003ולמאן דאמר\u0004 \u0005[ו\u0006אפילו \u0005ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003סקילה חמורה\u0004 משריפה, על כל פנים \u0003מהאי קושיא\u0004 \u0005[מקושיה\u0006 אחרונה \u0005זו]\u0006 \u0003לא נידונה\u0004 \u0005[נדון אותה],\u0006 שאמנם אין קושי של חומרה וקולה אבל מכל מקום נפקעה ההשוואה שבכתוב בין האם ואם האם, וכל זה לשיטה אחת של לימוד הגזירה שווה.","\u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמידנה במקומה],\u0006 נלמד כך: \u0003מה היא\u0004 (אשתו) \u0003אם אמה אסורה\u0004 לו, \u0003אף הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003אם אמו אסורה, ואוקי באתרה\u0004 \u0005[והעמד\u0006 את ההלכה \u0005במקומה]\u0006 כיצד? — \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 בבא על אם אמה של אשתו שנידון \u0003בשריפה, אבל הכא\u0004 \u0005[כאן]\u0006 שבא על אם אמו שלו נידון \u0003בסקילה, כדאשכחן\u0004 \u0005[כפי שמצאנו]\u0006 שנענש \u0003באמו\u0004 שלו בסקילה, ומעתה נוכיח את הקושי שבדבר.","\u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003שריפה חמורה\u0004 מסקילה, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה ולהקשות:"],["\u0003מה להיא,\u0004 לכל קרובה של אשתו, \u0003שכן אמה\u0004 של אשתו \u0003בשרפה, תאמר בהוא,\u0004 קרובותיו שלו, שעל \u0003אמו\u0004 הוא נידון \u0003בסקילה\u0004 בלבד, ואין איפוא להשוות אם אמו לאם אמה.","\u0003ועוד:\u0004 יש לראות את ההשוואה \u0003הוא כהיא,\u0004 כך: \u0003מה היא לא חלקתה בה בין בתה לאם אמה,\u0004 שנענש על שתיהן בשריפה, \u0003אף הוא לא תחלוק בו בין בתו לאם אמו\u0004 וייענש על שתיהן אותו עונש, או בשריפה או בסקילה, ולא כדרך שאמרנו קודם, והרי זה מקלקל את שלימות ההשוואה בין שארו ושאר אשתו, וגם","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003סקילה חמורה\u0004 משריפה, \u0003מהאי קושיא\u0004 \u0005[מ\u0006תוך \u0005קושיה\u0006 \u0005זו]\u0006 עצמה \u0003לא נידונה\u0004 \u0005[נדון אותה],\u0006 שהרי השוואה זו שבכתוב סותרת את ההשוואה הקודמת.","ועוד מקשים, אם משוה אתה שאר שלו לשאר שלה, נאמר כך: \u0003אי מה הוא כלתו אסורה\u0004 כמפורש בתורה, \u0003אף היא,\u0004 אשתו, תהא \u0003כלתה אסורה,\u0004 ויהא חייב על אשת בן אשתו!","\u0003אמר אביי: אמר קרא\u0004 \u0005[הכתוב],\u0006 שחוזר ואומר בכלתו: \u0003\"אשת בנך היא\",\u0004 להדגיש: \u0003משום אשת בנך אתה מחייבו, ואי\u0004 (אין) \u0003אתה מחייבו משום אשת בנה\u0004 של אשתו.","ו\u0003רבא אמר:\u0004 אין צורך בדקדוק זה, כיון שאין לקושיה כל תוקף. כי \u0003בין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ומינה\u0004 \u0005[ממנה וממנה]\u0006 \u0003בין למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ואוקי באתרה\u0004 \u0005[ממנה והעמידנה במקומה]\u0006 \u0003לא אתיא\u0004 \u0005[אינה באה,\u0006 נלמדת\u0005].\u0006","שכן \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ומינה\u0004 \u0005[ממנה וממנה]\u0006 יהא השיקול המלא כך: \u0003מה הוא כלתו אסורה, אף היא נמי\u0004 \u0005[גם כן]\u0006 \u0003כלתה אסורה, ומינה\u0004 \u0005[וממנה]\u0006 תוסיף ותלמד: \u0003מה הוא\u0004 על כלתו שלו נידון עליה \u0003בסקילה, אף היא נמי\u0004 \u0005[גם כן]\u0006 אם בא על כלת אשתו יהא \u0003בסקילה.\u0004","ומעתה נתבונן בדבר, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003סקילה חמורה\u0004 משריפה, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה באופן זה: \u0003מה להוא\u0004 שהוא חמור \u0003שכן\u0004 חייב על \u0003אמו בסקילה, תאמר בהיא,\u0004 באשתו, שעל \u0003אמה\u0004 חייב \u0003בשרפה\u0004 בלבד, ולכן אין להשוות.","\u0003 ועוד\u0004 יש להקשות: אם בא על \u0003בתה\u0004 שהיא קרובה יותר יהיה חייב עונש קל של \u0003שרפה,\u0004 בא על \u0003כלתה\u0004 שהיא רחוקה יותר יהיה נידון \u0003בסקילה?!\u0004 את הקושיה האחרונה דוחים: אפשר לומר כי \u0003הוא בעצמו\u0004 (כלומר, קרובותיו שלו) \u0003יוכיח,\u0004 שעל \u0003בתו\u0004 חייב \u0003בשרפה,\u0004 ואם בא על \u0003כלתו\u0004 שהיא רחוקה יותר נידון \u0003בסקילה!\u0004","\u0003אלא\u0004 כך יש להקשות: \u0003מה הוא לא חלקת בו\u0004 בעונש \u0003בין אמו לכלתו\u0004 שבשתיהן הריהו נידון בסקילה, \u0003אף היא לא תחלוק בה בין אמה לכלתה,\u0004 ששתיהן צריכות להידון באותה מיתה, בשריפה, ושוב אין מקום להשוואה בין שאר מצדו ושאר מצדה. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003שרפה חמורה,\u0004 על כל פנים \u0003מהאי קושיא\u0004 \u0005[מ\u0006תוך \u0005קושיה זו]\u0006 \u0003לא נידונין\u0004 \u0005[\u0006נוכל \u0005לדון].\u0006","\u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמד במקומה],\u0006 תהא דרך ההשוואה כך: \u0003מה הוא כלתו אסורה, אף היא כלתה אסורה, ואוקי באתרה\u0004 \u0005[והעמד\u0006 את ההלכה \u0005במקומה]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 כשבא על כלתו, הריהו נידון \u0003בסקילה, אבל הכא\u0004 \u0005[כאן],\u0006 בכלת אשתו, תידון \u0003בשרפה, כדאשכחן\u0004 \u0005[כ\u0006פי \u0005שאנו מוצאים]\u0006 \u0003באמה\u0004 של אשתו, שאם בא עליה נידון בשריפה.","ומעתה נוכיח שהלכה כזו אינה יכולה להתקיים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003סקילה חמורה\u0004 משריפה, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]:\u0006 \u0003מה להוא שכן\u0004 על \u0003אמו\u0004 נענש במיתה חמורה של \u0003סקילה, תאמר בהיא שאמה בשרפה\u0004 בלבד.","\u0003 ועוד\u0004 קושיה: \u0003מה הוא חלקת בו\u0004 בעונש \u0003בין בתו לכלתו\u0004 שעל בתו נידון בשריפה ועל כלתו בסקילה, \u0003אף היא תחלוק בה\u0004 בעונש \u0003בין בתה לכלתה\u0004 והרי זה היפך ההשוואה וההלכה שהגענו אליה. וגם \u0003למאן דאמר\u0004 \u0003נמי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר גם כן]\u0006 ש\u0003שרפה חמורה\u0004 מסקילה, על כל פנים \u0003מהאי קושיא\u0004 \u0005[מ\u0006תוך \u0005קושיה זו]\u0006 \u0003לא נידונין,\u0004 שהרי גם אם שריפה חמורה, מוכח שאין מקום להשוואה בין שארו לשארה.","בכל הדיון ברור היה כי על בתו חייב שריפה, ושואלים: \u0003בתו מאנוסתו\u0004 שאינה בת אשתו, שהרי לא נשא את אמה, \u0003מנין\u0004 שהיא אסורה? שהרי נאמר איסור רק בבת אשתו ובבת בתו, אבל בתו עצמה לא נאסרה במפורש בתורה! ומשיבים: \u0003האמר\u0004 \u0005[הרי\u0006 כבר \u0005אמר]\u0006 \u0003אביי\u0004 ש\u0003קל וחומר\u0004 הוא: אם \u0003על בת בתו\u0004 הריהו \u0003ענוש, על בתו לא כל שכן\u0004 שייענש?!","ומקשים: \u0003וכי עונשין מן הדין\u0004 (בשל קל וחומר) בלא ציווי מפורש? ומשיבים: בעצם אין זה קל וחומר, אלא \u0003גלויי מילתא בעלמא\u0004 \u0005[גילוי דבר בלבד]\u0006 \u0003הוא,\u0004 שהרי ברור כי הבא על בת בתו נענש רק משום בתו שהיא היוצרת את הקרבה, ונאמר בהן \"כי ערותך הנה\", ולכן אין כאן קל וחומר אלא רק ביאור של דבר שכבר נאמר במקרא.","\u0003רבא אמר: אמר לי ר' יצחק בר אבדימי\u0004 כי \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"הנה\" \"הנה\",\u0004 שנאמר ביטוי זה גם בצאצאיו (\"כי ערותך הנה\". ויקרא יח, י) וגם בצאצאי אשתו (\"שארה הנה זמה היא\". שם יז), \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 העונש לחטא זה מגזירה שווה מהמילים \u0003\"זמה\" \"זמה\",\u0004 שנאמרו בצאצאי אשתו, וגם בבא על אשה ואמה (\"ואיש אשר יקח את אשה ואת אמה זימה היא באש ישרפו אותו ואתהן\" שם כ, יד).","הלכה אחרת \u0003תני אבוה\u0004 \u0005[שנה אביו]\u0006 של \u0003ר' אבין: לפי שלא למדנו\u0004 בתורה במפורש עונש \u0003בתו מאנוסתו, הוצרך הכתוב לומר \"ובת איש כהן\u0004 כי תחל לזנות את אביה היא מחללת באש תשרף\" (שם כא, ט), המתפרש גם שכאשר בת כהן זנתה עם (\"את\") אביה — דינה שריפה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כך אתה למד, אמור: \u0003מה בת כהן היא\u0004 נדונית \u0003בשרפה ואין בועלה\u0004 נידון \u0003בשרפה, אף בתו מאנוסתו היא\u0004 נידונית \u0003בשרפה ואין בועלה\u0004 (אביה) נידון \u0003בשרפה\u0004 אלא במיתה אחרת!","\u0003אמר אביי:\u0004 כנגד סברה זו \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"את אביה היא מחללת\"\u0004 שההדגשה של \"היא\" ליחד הלכה זו ל\u0003מי שמחללת את אביה\u0004 בזנותה, \u0003יצתה\u0004 (יצאה) \u0003זו שאביה\u0004 הוא ש\u0003מחללה.\u0004","\u0003רבא אמר\u0004 שיש לדחות קושיה זו מסברא: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 כאשר בא אדם על בת כהן נשואה, אפשר לומר כי בכך \u0003אפיקתיה מדינא\u0004 \u0005[הוצא אותו]\u0006 מדינה של \u0003בת כהן\u0004 שבשריפה, \u0003ואוקימתה אדינא\u0004 \u0005[והעמד אותה על דין]\u0006 של בא על \u0003בת ישראל\u0004 ונידונים בחנק, וכיון שיש אפשרות אחרת מבינים כך את הכתוב, אבל \u0003הכא אדינא דמאן מוקמת ליה\u0004 \u0005[כאן על דינו של מי תוכל להעמיד אותו]\u0006 שהלא עונשו לא נתפרש, ועל כורחך ידון באותה מיתה, וכי \u0003אדינא\u0004 \u0005[על הדין]\u0006 של \u0003פנוייה מוקמת ליה\u0004 \u0005[תעמיד אותו]\u0006 שאינו חייב כלל?!","שואלים: \u0003אזהרה\u0004 (מקור המפרש את האיסור) לבא על \u0003בתו מאנוסתו מניין?\u0004 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי ורבא, מהיכא דנפקא להו\u0004 \u0005[מהיכן שיוצאת להם,\u0006 שלמדו\u0005]\u0006 את ה\u0003עונש מהתם נפקא להו\u0004 \u0005[משם יוצאת להם,\u0006 למדים הם\u0005]\u0006 את ה\u0003אזהרה,\u0004 שבשני המקורות כתובים איסורי \"לא תעשה\".","\u0003אלא לדתני אבוה\u0004 \u0005[ל\u0006פי מה \u0005ששנה אביו]\u0006 של \u0003ר' אבין\u0004 מענין בת כהן \u0003מאי\u0004 \u0005[מה]\u0006 הכתוב האוסר לעשות כן? \u0003אמר ר' אילעא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אל תחלל את בתך להזנותה\"\u0004 (שם יט, כא), ופירושו: אל תזנה עם בתך.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003ר' יעקב אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב אחא בר יעקב: האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"אל תחלל את בתך להזנותה\" להכי\u0004 \u0005[ל\u0006ענין \u0005זה]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]?\u0006 והלא \u0003האי מיבעי ליה לכדתניא\u0004 \u0005[\u0006דבר \u0005זה נחוץ לו ל\u0006למדנו \u0005מה ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 נאמר \u0003\"אל תחלל את בתך להזנותה\", יכול בכהן המשיא את בתו\u0004 בכשרות \u0003ללוי וישראל הכתוב מדבר,\u0004 שהרי על ידי נישואין אלה היא מתחללת מדין כהונה לענין אכילת תרומה ויהא הדבר אסור. \u0003תלמוד לומר: \"להזנותה\",\u0004 לומר: \u0003בחילול שבזנות הכתוב מדבר,\u0004 וכוונתו: \u0003במוסר את בתו\u0004 לבעילה \u0003שלא לשם אישות\u0004 אלא לזנות בלבד. ואם כן, ללמדנו איסור זה בא הכתוב!","ומשיבים: \u0003אם כן\u0004 שהכתוב נאמר רק לענין זה בלבד \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"אל תחל\", מאי\u0004 \u0005[מה\u0006 הלשון\u0005]\u0006 הכבדה יותר \u0003\"אל תחלל\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שתים],\u0006 שתי הלכות. ושואלים: \u0003ו\u0004לדעת \u0003אביי ורבא האי\u0004 \u0005[זה]\u0006 המקרא של \u0003\"אל תחלל את בתך להזנותה\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 לדעתם לאיזה צורך בא, שהרי את ההלכה בבתו למדו ממקום אחר! \u0003אמר ר' מני:\u0004 ללמד \u0003זה המשיא את בתו לזקן,\u0004 שכיון שאינה מרוצה בו סופה שתבוא לזנות, ונמצא שאביה גרם לה לכך.","\u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005]:\u0006 על הנאמר \u0003\"אל תחלל את בתך להזנותה\", ר' אליעזר אומר: זה המשיא את בתו לזקן. ר' עקיבא אומר: זה המשהא\u0004 את \u0003בתו בוגרת,\u0004 ואינו משיא אותה בזמנה, שכיון שהיא בוגרת שמא תתאוה ותזנה.","\u0003אמר רב כהנא משום\u0004 (בשם) \u0003ר' עקיבא: אין לך עני בישראל אלא\u0004 זה שהוא \u0003רשע ערום,\u0004 שמנסה להערים ולהסתיר רשעותו, ו\u0003המשהא בתו בוגרת.\u0004 על סגנון הדברים תוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003המשהא בתו בוגרת לאו\u0004 \u0005[לא]\u0006 \u0003רשע ערום הוא?\u0004 שהרי הוא מנסה להערים ולחסוך לעצמו דמי משרתת בבית, ומשאיר את בתו שתשרתהו, ועל ידי כך גורם לה לחטוא!","\u0003אמר אביי,\u0004"],["\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003איזהו עני רשע ערום\u0004 שמפני עניותו נעשה רשע ערום — \u0003זה המשהא בתו בוגרת.\u0004 כיון שהוזכרה שמועה זו מזכירים את מה ש\u0003אמר רב כהנא משום\u0004 (בשם) \u0003ר' עקיבא: הוי זהיר מן היועצך לפי דרכו,\u0004 שאם יש לו נגיעה בענין זה, מן הסתם לטובת עצמו הוא מיעצך.","באותו נושא \u0003אמר רב יהודה אמר רב: המשיא את בתו לזקן,\u0004 או \u0003המשיא אשה לבנו קטן\u0004 שעדיין לא בגר \u0003והמחזיר אבידה לגוי\u0004 הריהו גורם לעבירה, שהמשיא אשה בוגרת לזקן או לקטן שאינו יכול לספקה גורם לה לזנות עם אחרים, והמחזיר אבידה לגוי מוסיף להם רכוש יתר על מה שגזלו כבר מישראל, ו\u0003עליו הכתוב אומר \"למען ספות הרוה את הצמאה. לא יאבה ה' סלח לו\"\u0004 (דברים כט, יח-יט).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003האוהב את אשתו כגופו, והמכבדה\u0004 במלבושים ותכשיטים \u0003יותר מגופו, והמדריך בניו ובנותיו בדרך ישרה, והמשיאן סמוך לפירקן, עליו הכתוב אומר: \"וידעת כי שלום אהלך ופקדת נוך ולא תחטא\"\u0004 (איוב ה, כד), ומשמע שיש מצוה בהשאת ילדים בגיל צעיר! ומשיבים: \u0003סמוך לפירקן שאני\u0004 \u0005[שונה],\u0006 שכיון שהם סמוכים לבגרותם, אין לחשוש ששהייה של זמן קצר תגרום לחטא, מה שאין כן בקטנים ממש.","באותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האוהב את שכיניו, והמקרב את קרוביו, והנושא את בת אחותו\u0004 ועל ידי כך נושא אשה שהוא קרוב לה ומחבבה גם מקודם, \u0003והמלוה סלע לעני בשעת דוחקו\u0004 שאין אחרים שילוו לו אז, על כל אלה \u0003הכתוב אומר: \"\u0004הלוא פרוס לרעב לחמך ועניים מרודים תביא בית כי תראה ערום וכסיתו ומבשרך לא תתעלם... \u0003אז תקרא וה' יענה\"\u0004 (ישעיה נח, ז. שם ט). והאוהב את שכיניו נכלל במקרב את קרוביו, שנאמר: \"טוב שכן קרוב מאח רחוק\" (משלי כז, י).","לעצם ההלכה בבא על אשה ובתה, מביאים מדרש חכמים על הכתוב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 מה שנאמר: \"ואיש אשר יקח את אשה ואת אמה זימה הוא באש ישרפו \u0003אתו ואתהן\u0004 ולא תהיה זימה בתוככם\" (ויקרא כ, יד), כוונתו: \u0003אותו ואת אחת מהן,\u0004 אותה שהיא אסורה עליו, שהרי את הראשונה נשא כדין, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אותו ואת שתיהן.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 כי וודאי אין ר' עקיבא סבור שיש להעניש גם את אשתו שנשא כדין משום שבא על קרובתה! \u0003אמר אביי: משמעות דורשים איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 הבדל\u0005],\u0006 שחלוקים התנאים בשאלה כיצד מבינים את הכתוב עצמו, ומה נוסף לכך על ידי דרשה.","\u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"אתו ואתהן\"\u0004 משמעו — \u0003אתו ואת אחת מהן, שכן בלשון יוני קורין לאחת \"הינא\",\u0004 ו\"אתהן\" פירושו: את האחת. \u0003ו\u0004אילו איסור הבא על \u0003אם חמותו\u0004 שאף היא בשריפה — \u0003מדרשא אתיא\u0004 \u0005[מ\u0006לימוד של \u0005דרשה\u0006 הוא \u0005בא],\u0006 ואינו כתוב במקרא זה. ואילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"אתו ואתהן\"\u0004 — \u0003אתו ואת שתיהן\u0004 יחד, ומתי צריך לשרוף את שתיהן — הרי זה רק כאשר בא על שתיהן בעבירה, והוא כאשר בא על חמותו ועל אם חמותו, שגם הראשונה אסורה עליו. ואם כן \u0003אם חמותו הכא כתיבא\u0004 \u0005[כאן\u0006 היא \u0005כתובה]\u0006 במקרא עצמו, ולא מדרשה חיצונית.","\u0003רבא אמר:\u0004 בענין אם חמותו הכל סבורים שאיסורה נלמד מדרשה, אבל כאן בדין הבא על \u0003חמותו לאחר מיתה\u0004 של אשתו \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 הבדל\u0005],\u0006 ש\u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 שהבא על \u0003חמותו לאחר מיתה\u0004 של אשתו — חייב \u0003בשרפה\u0004 שהתורה מחייבת מיתה על כל אחת מהן, גם אם האחרת אינה קיימת עוד. \u0003ור' עקיבא סבר\u0004 \u0005[סבור]\u0006 שכאן אין עוד חיוב שריפה אלא \u0003איסורא בעלמא\u0004 \u0005[איסור בלבד],\u0006 שדין שריפה הוא רק כאשר קיימות שתיהן יחד.","\u0003משנה\u0004 ועוד ממשיכים ברשימת חייבי מיתות בית דין. \u0003ואלו\u0004 הם \u0003הנהרגין\u0004 בסייף: \u0003הרוצח, ואנשי עיר הנדחת\u0004 שעבדו כולם עבודה זרה.","ופירוט דין הרוצח: \u0003רוצח שהכה את רעהו באבן או בברזל,\u0004 או ש\u0003כבש\u0004 (לחץ) \u0003עליו לתוך המים או לתוך האור\u0004 (האש) \u0003ואינו יכול לעלות משם, ומת\u0004 — הרי זה \u0003חייב\u0004 כרוצח על ידי מכה.","ואולם אם \u0003דחפו לתוך המים או לתוך האור ויכול\u0004 הנדחף \u0003לעלות משם,\u0004 אבל אירע שלא יצא, \u0003ומת\u0004 — \u0003פטור\u0004 הרוצח מדיני אדם, שהרי היה רק גורם למוות ולא עשה שום מעשה. \u0003שיסה\u0004 (גירה) \u0003בו את הכלב\u0004 שינשכהו והרגו, או ש\u0003שיסה בו את הנחש\u0004 — \u0003פטור,\u0004 שהמשסה היה רק גורם בלבד. \u0003השיך בו את הנחש,\u0004 כלומר, נעץ את שיני הנחש בבשרו, \u0003ר' יהודה מחייב\u0004 אותו כרוצח, \u0003וחכמים פוטרין,\u0004 שלדעתם אינו אלא גורם.","\u0003גמרא\u0004 \u0003אמר שמואל,\u0004 נאמר בדיני רוצח: \"ואם באבן יד... או בכלי עץ יד אשר ימות בו הכהו וימות רוצח הוא\" (במדבר לה, יז-יח), שמשמע שצריך להיות שיעור מסויים לאבן ולעץ, ו\u0003מפני מה לא נאמרה יד בברזל\u0004 שנאמר סתם \"ואם בכלי ברזל הכהו וימות רוצח הוא\" (שם טז) — ללמד \u0003שהברזל ממית בכל שהוא,\u0004 בדרך דקירה ונעיצה, ואין לקבוע בו שיעור גודל מסויים.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003רבי אומר: גלוי וידוע לפני מי שאמר \"והיה העולם\" שהברזל ממית בכל שהוא, לפיכך לא נתנה תורה בו שיעור.\u0004 ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא באופן \u0003דברזיה מיברז\u0004 \u0005[שדקרו],\u0006 שאז הברזל ממית בכל שהוא, אבל אם מכה אותו בברזל ודאי יש גם לברזל שיעור שאין חייבים בפחות ממנו.","שנינו במשנה שאם \u0003כבש עליו\u0004 את חבירו \u0003לתוך המים\u0004 ומת — חייב. ומעירים: \u0003רישא רבותא קא משמע לן וסיפא רבותא קא משמע לן\u0004 \u0005[בראש,\u0006 בתחילת המשנה דבר \u0005חידוש השמיע לנו, ו\u0006ב\u0005סופה\u0006 דבר \u0005חידוש השמיע לנו]\u0006 ומסבירים: \u0003רישא רבותא קא משמע לן\u0004 \u0005[בראשה\u0006 דבר \u0005חידוש\u0006 \u0005השמיע לנו]\u0006 \u0003אף על גב דלאו איהו\u0004 \u0005[אף על פי שלא הוא\u0006 עצמו\u0005]\u0006 \u0003דחפו\u0004 למים אלא נפל מעצמו, \u0003כיון\u0004 שהוא מחזיקו (כובשו) שם עד ש\u0003אין יכול לעלות משם ומת\u0004 — \u0003חייב.\u0004 וכן \u0003סיפא רבותא קא משמע לן\u0004 \u0005[בסוף\u0006 דבר \u0005חידוש השמיע לנו]\u0006 ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003דחפו\u0004 הוא בעצמו, \u0003כיון\u0004 ש\u0003יכול\u0004 הנדחף \u0003לעלות משם\u0004 הרי גם אם \u0003מת\u0004 — \u0003פטור.\u0004","ושואלים: \u0003כבש מנלן\u0004 \u0005[מניין לנו]\u0006 שהוא בכלל אלו שהורגים עליהם את הרוצח. \u0003אמר שמואל,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"או באיבה הכהו בידו וימת מות יומת המכה רצח הוא\" (שם, כא) \u0003\"או באיבה\" לרבות את המצמצם,\u0004 כלומר, הדוחק (\"מצמצם\") את חבירו למקום שאינו יכול להיות בו.","מסופר: \u0003ההוא גברא דמצמצמא לחיותא דחבריה בשימשא\u0004 \u0005[אדם אחד שדחף\u0006 וסגר \u0005את חית,\u0006 בהמת \u0005חבירו בשמש],\u0006 \u0003ומתה\u0004 מחמת השמש, \u0003רבינא מחייב\u0004 כאילו הזיקה הוא עצמו, ו\u0003רב אחא בר רב פטר,\u0004 כיון שלא עשה מעשה נזק בידיו.","ומסבירים את נימוקיהם: \u0003רבינא מחייב,\u0004 כי לדעתו דבר זה \u0003קל וחומר\u0004 הוא: \u0003ומה רוצח שלא עשה בו\u0004 (בעונשו) דין \u0003שוגג כמזיד,\u0004 ולא עשה בו \u0003אונס כרצון,\u0004 שאין הרוצח באונס חייב על רצח, ובכל זאת \u0003חייב בו את המצמצם,\u0004 שחייב מיתה אף שלא עשה מעשה,"],["דיני \u0003נזקין שעשה בהן שוגג כמזיד ואונס כרצון\u0004 שחייב אדם לשלם על כל נזק שעשה בכל מקרה (\"אדם מועד לעולם\" וכו'. בבא קמא כו, א), \u0003אינו דין שחייב בהן את המצמצם?\u0004","ואילו \u0003רב אחא בר רב פוטר. אמר רב משרשיא, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003אבוה דאבא\u0004 \u0005[אבי אבי]\u0006 רב אחא בר רב, ש\u0003פוטר?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004או באיבה הכהו בידו וימות \u0003מות יומת המכה רצח הוא\"\u0004 (במדבר לה, כא) וההדגשה \"הוא\" באה למעט: \u0003ברוצח הוא\u0004 ש\u0003חייב לן\u0004 \u0005[אותנו]\u0006 התורה \u0003מצמצם,\u0004 ואילו \u0003בנזקין לא חייב לן\u0004 \u0005[אותנו]\u0006 \u0003מצמצם\u0004 ואינו אלא גורם בלבד, ופטור.","\u0003אמר רבא: כפתו\u0004 את חבירו \u0003ומת ברעב\u0004 — \u0003פטור\u0004 מדיני אדם כרוצח, אף שחייב בדיני שמים, מפני שהוא לא עשה מעשה בהריגתו, שאף שהוא כבר רעב, מכל מקום אינו יכול למות כבר עכשיו ברעב זה, אלא לאחר שיתגבר רעבונו. \u0003ואמר רבא: כפתו\u0004 לחבירו \u0003בחמה ומת\u0004 מפני החום, כפתו \u0003בצינה ומת\u0004 מפני הקור — \u0003חייב,\u0004 שבאותה שעה הריהו כמתחיל להמיתו. ואולם אם בשעה שכפתו אין שם חמה אלא \u0003סוף חמה לבא\u0004 לשם, \u0003סוף צינה לבא\u0004 לשם — \u0003פטור,\u0004 שהרי בשעה שכפתו לא היה כאן צד מיתה, אלא בא לאחר מכן.","\u0003אמר רבא: כפתו\u0004 לחבירו \u0003לפני ארי\u0004 — \u0003פטור,\u0004 כי אין ודאות שהארי יטרפהו ואינו אלא כגורם למוות, ואולם אם כפתו \u0003לפני יתושין\u0004 — \u0003חייב,\u0004 משום שברור שיתושים אלה יעקצוהו עד מוות (רמ\"ה). \u0003רב אשי אמר: אפילו\u0004 כפתו \u0003לפני יתושין נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור,\u0004 כי לא אותם יתושים שהיו שם בשעה שכפתו הם שהרגוהו אלא מטבע העולם ש\u0003הני\u0004 \u0005[אלה]\u0006 היתושים שהיו בשעה שכפתו \u0003אזלי\u0004 \u0005[הלכו],\u0006 \u0003והני\u0004 \u0005[ואלה],\u0006 יתושים אחרים, \u0003אתו\u0004 \u0005[באו],\u0006 והיתושים שבאו אחר כך לא היו שם מתחילה, ולכן הרי זה כמקרה של \"סוף חמה לבוא\".","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה דומה: \u0003כפה עליו,\u0004 על חבירו, \u0003גיגית\u0004 ומת בחנק, או ש\u0003פרע\u0004 (פרץ) \u0003עליו\u0004 \u0003מעזיבה\u0004 (כיסוי התקרה) ומת מן הצינה, \u0003רבא ור' זירא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חייב\u0004 על כך, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פטור.\u0004","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 המחלוקת, ש\u0003רבא הוא\u0004 ש\u0003אמר פטור,\u0004 שהרי \u0003אמר רבא\u0004 בכיוצא בזה: \u0003כפתו\u0004 לחבירו \u0003ומת ברעב\u0004 — \u0003פטור,\u0004 שכיון שיש כאן תהליך מתמשך שאין הוא אחראי לכולו — אינו חייב עליו.","ודוחים: \u0003אדרבה\u0004 (להיפך), \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' זירא הוא\u0004 ש\u0003אמר פטור,\u0004 ש\u0003אמר ר' זירא: האי מאן דעייליה לחבריה בביתא דשישא\u0004 \u0005[מי שהכניס את חבירו לבית של שייש]\u0006 שהוא אטום לגמרי, \u0003ואדליק ליה שרגא\u0004 \u0005[הדליק לו\u0006 שם את \u0005הנר],\u0006 \u0003ומת\u0004 חבירו בחנק — \u0003חייב.\u0004 ונדקדק: \u0003טעמא דאדליק ליה שרגא\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שהדליק לו נר]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אדליק ליה שרגא\u0004 \u0005[הדליק לו נר]\u0006 — \u0003לא\u0004 מתחייב הכולא, אף על פי שסופו של הכלוא להיחנק לאט לאט מעצמו. הרי שאף ר' זירא סבור כי אם אין האיש עושה את מעשה ההמתה (או על כל פנים, התחלת החנק) כעת — פטור עליו, והרי זה בדיוק כמי שכפה עליו גיגית!","את ההשוואה הזו דוחים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במכניס חבירו לבית של שיש \u0003בלא שרגא\u0004 \u0005[הנר]\u0006 \u0003לא מתחיל הבלא\u0004 \u0005[ההבל,\u0006 המחנק\u0005]\u0006"],["\u0003בשעתיה\u0004 \u0005[בשעתו,\u0006 מיד\u0005],\u0006 באותה שעה כי הבית גדול למדי. ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 בגיגית\u0005]\u0006 \u0003בלא שרגא נמי\u0004 \u0005[נר גם כן]\u0006 \u0003מתחיל הבלא בשעתיה\u0004 \u0005[מתחיל ההבל,\u0006 המחנק \u0005בשעתו]\u0006 ואם כן אין להשוות את ההלכה הזאת לדברי ר' זירא, וכנראה רבא הוא שפטר.","ועוד הלכות אחדות בענין גרימת רצח. ו\u0003סימן\u0004 להם: \u0003סולם תריס סמנין, בכותל.\u0004","\u0003אמר רבא:\u0004 \u0003דחפו\u0004 לחבירו \u0003לבור ו\u0004היה \u0003סולם בבור,\u0004 שהיה יכול לצאת מן הבור על ידו, \u0003ובא אחר וסילקו\u0004 את הסולם ומת בבור מפני הרעב. \u0003ואפילו הוא\u0004 עצמו, הדוחף, \u0003קדם וסילקו\u0004 את הסולם — \u0003פטור,\u0004 וטעם הדבר: \u0003דבעידנא דשדייה\u0004 \u0005[שבזמן שהשליכו]\u0006 שם \u0003יכול\u0004 \u0003לעלות הוא\u0004 משם. ואם כן פעולת ההשלכה לבור לא היתה בשעתה התחלת הריגה, ונטילת הסולם אחר כך היתה רק מניעת סיוע מאדם להינצל, אך לא הריגה בידים.","ודוגמה נוספת, שיש בה חידוש, \u0003אמר רבא: זרק חץ\u0004 בחבירו \u0003ותריס\u0004 (מגן) \u0003בידו\u0004 של חבירו, \u0003ובא אחר ונטלו\u0004 למגן ממנו, \u0003ואפילו הוא\u0004 עצמו, יורה החץ, \u0003קדם ונטלו\u0004 לאחר זריקת החץ, ונהרג על ידי החץ משום שלא היה מגן בידו — \u0003פטור.\u0004 והטעם: \u0003דבעידנא דשדייה ביה מיפסק פיסקיה גיריה\u0004 \u0005[שבזמן שירה\u0006 בו את החץ \u0005מופסקים,\u0006 מופרדים, היו \u0005חיציו]\u0006 ואינו יכול להזיק, והנזק נעשה על ידי הסרת המגן ממנו, והיא פעולה מיוחדת לעצמה.","וכן \u0003אמר רבא: זרק בו חץ\u0004 בחבירו \u0003ו\u0004היו \u0003סמנין\u0004 (סמי רפואה) \u0003בידו\u0004 של הנורה שאם היה משתמש בהם לא היה מת על ידי הפגיעה, \u0003ובא אחר ופיזרן,\u0004 את הסמנים הללו, ואינו יכול להתרפא ומת, \u0003ואפילו הוא\u0004 עצמו, היורה, \u0003קדם ופיזרן\u0004 — \u0003פטור.\u0004 והטעם, \u0003דבעידנא דשדא ביה\u0004 \u0005[שבזמן שזרק בו]\u0006 \u0003יכול להתרפאות הוה\u0004 \u0005[היה],\u0006 והיריה עצמה לא היתה תחילת הריגה אלא חבלה בלבד, ומותו נגרם בשל מחסור בתרופות.","\u0003אמר רב אשי:\u0004 כיון שאם יש רפואות בידו אין זו נחשבת הריגה, \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003אפילו\u0004 היו \u0003סמנין\u0004 המרפאים פצע זה מצויים \u0003בשוק\u0004 והיה יכול לקנותם ולהתרפא, אם לא עשה כן, ומת, אין היורה בחץ נידון כרוצח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 ואם לא היו סמנין בשוק בשעת היריה, אלא \u0003נזדמנו לו סמנין\u0004 שיוכל להשתמש בהם ולהינצל, והוא לא עשה כן, ומת, \u0003מהו\u0004 הדין בכגון זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי יצא\u0004 היורה \u0003מבית דין\u0004 כשהוא \u0003זכאי.\u0004 שאם היתה אפשרות מציאותית במשך זמן כלשהו שינצל הנפגע — שוב אין זה רוצח, אלא רק גורם למוות.","\u0003ואמר רבא: זרק\u0004 אדם \u0003צרור\u0004 אבן בכוונה להרוג ופגעה האבן \u0003בכותל וחזרה לאחוריה והרגה\u0004 אדם — \u0003חייב\u0004 על כך. \u0003ותנא תונא\u0004 \u0005[והתנא שנה אותה]\u0006 הלכה כגון זו, ששנינו בברייתא: \u0003כגון אלו המשחקין בכדור שהרגו,\u0004 שפגעו באדם והרגוהו, אם הרגו \u0003במזיד\u0004 — \u0003נהרגין,\u0004 אם הרגו \u0003בשוגג\u0004 — \u0003גולין.\u0004","ותוהים: \u0003\"בשוגג גולין\"? פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומדוע לא יגלו כשאר הרוצחים בשגגה? ומשיבים: בעצם, החידוש העיקרי אינו הגלות המוזכרת כאן, אלא ש\u0003במזיד נהרגין איצטריך ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005]\u0006 כי, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שאי אפשר להמיתם כי לפני כן צריך להתרות בהם, והתראה זו \u0003התראת ספק היא,\u0004 והתראה ספק אינה קרויה התראה. ומה הספק שבדבר — \u0003מי יימר דהדרה\u0004 \u0005[מי יאמר ש\u0006הכדור \u0005יחזור\u0006 ויפגע\u0005]?\u0006 ואפשר היה לחשוב שמי שהזהירוהו שלא יזרוק כדור בכותל שמא יפגע בחבירו הרי זו רק התראת ספק, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהמשחקים בכדור מאומנים בזריקתו, וודאי יחזור הכדור אחורנית, ואין זה ספק.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא קמיה\u0004 \u0005[בן המערב,\u0006 מארץ ישראל \u0005לפני]\u0006 \u0003ר' אבהו\u0004 ברייתא זו: \u0003כגון אלו המשחקין בכדור שהרגו,\u0004 שדינם הוא שאם פגע הכדור באותו אדם \u0003תוך ארבע אמות\u0004 מן הזורק — \u0003פטור,\u0004 שוודאי לא נתכוון לזריקה לטווח כה קצר (רמ\"ה), \u0003חוץ לארבע אמות\u0004 — \u0003חייב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 בתהיה על הלכה זו: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר]?\u0006 \u0003אי דקא ניחא ליה\u0004 \u0005[אם שנוח לו]\u0006 שיזרק הכדור למרחק קטן, כגון פחות מארבע אמות — הרי \u0003אפילו פורתא נמי\u0004 \u0005[במעט גם כן]\u0006 יתחייב ואפילו היה זה בתוך ארבע. \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 במרחק שזרק ורצה שהכדור ייזרק למרחק גדול יותר, ולא הצליח ונפל קודם לכן, \u0003אפילו טובא נמי\u0004 \u0005[\u0006ב\u0005יותר\u0006 מארבע אמות \u0005גם כן]\u0006 \u0003לא\u0004 יתחייב, שהרי לא נתכוון לזרוק לכאן, ומה מקום לשיעור ארבע אמות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סתם משחקין בכדור כמה דעיילי\u0004 \u0003טפי\u0004 \u0005[ככל ש\u0006הם \u0005נכנסים יותר]\u0006 וזורקים הרחק בתוך מקום המשחק — \u0003מינח ניחא ליה\u0004 \u0005[נוח להם],\u0006 ומן הסתם כוונתם לזריקה רחוקה יותר מארבע אמות.","על עצם העיקרון שואלים: \u0003למימרא דכהאי גוונא\u0004 \u0005[האם נאמר שבכגון זה]\u0006 שזרק חפץ בכותל וחזר החפץ ונפל למקום אחר נחשב ש\u0003כחו\u0004 של הזורק \u0003הוא? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר, ששנינו במשנה: מי שהיה \u0003מקדש,\u0004 כלומר, מכניס אפר פרה אדומה למים כדי לעשות מי חטאת לטהרת הטמאים, \u0003ונפל קידוש\u0004 (האפר המקודש) תחילה \u0003על ידו או על הצד\u0004 הכלי, \u0003ואחר כך\u0004 חזר ו\u0003נפל לשוקת\u0004 שבה מצויים המים — \u0003פסול,\u0004 שיש צורך שיכניס שם את האפר בכוח עצמו. משמע שדבר שחזר מן הכותל אין קרוי מכוחו!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בשותת,\u0004 שלא זרק את האפר מרצונו, אלא נשמט האפר מידו בלא מעשה ואחר כך פגע בדופני הכלי ונפל פנימה, ולא היה כאן כוחו כלל, מה שאין כן במשחק בכדור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, שפגיעה שאינה ישירה אינה קרויה \"כוחו\", ששנינו במשנה: \u0003מחט\u0004 הטמאה בטומאת מת, \u0003שהיה נתונה על החרס והזה עליה\u0004 מי חטאת לטהרה, \u0003ספק על המחט\u0004 במישרין\u0003 היזה\u0004 את המים, \u0003ספק על החרס הזה ומיצה עליה,\u0004 שהמים שפגעו בחרס נזלו וירדו למחט — \u0003הזאתו פסול.\u0004 הרי שדבר שלא פגע פגיעה ישירה אינו קרוי \"כוחו\"!","\u0003אמר רב חיננא בר יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 יש לשנות את הגרסה, לא \"מיצה\" בה\"א אלא \u0003\"מצא\"\u0004 באל\"ף \u0003איתמר\u0004 \u0005[נאמר],\u0006 והכוונה היא שמצא לאחר זמן שהמחט רטובה, ואין ברור לו אם רטובה היא ממים שהתיז עליה במישרין, או שמא ממים ששתתו וירדו לאחר זמן מן החרס אל המחט, ואין להשוות מקרה זה למשחקים בכדור.","\u0003אמר רב פפא: האי מאן דכפתיה לחבריה, ואשקיל עליה בידקא דמיא\u0004 \u0005[מי שכפת,\u0006 קשר, \u0005אותו, את חבירו, והפנה אליו\u0006 את \u0005פרץ המים\u0006 של נהר\u0005]\u0006 וטבע שם — \u0003גירי דידיה הוא, ומיחייב\u0004 \u0005[כחיציו שלו הם\u0006 המים, \u0005וחייב]\u0006 מיתה, כאילו היה יורה בו בחיצים. שהמים הבאים מכוחו — כמוהם כשאר כלים שיורה מידו. ומסייגים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003בכח ראשון\u0004 ששטף המים פרץ מיד והוא מת מיד מכוחו של אותו פרץ, \u0003אבל בכח שני\u0004 כגון שזרמו המים ממקום למקום — \u0003גרמא בעלמא הוא\u0004 \u0005[גרימה בלבד היא],\u0006 ואינו חייב מיתה עליה.","\u0003ואמר רב פפא: זרק צרור\u0004 אבן \u0003למעלה והלכה\u0004 האבן לא ישר למעלה, אלא \u0003לצדדין, והרגה\u0004 — \u0003חייב. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מר בר רב אשי לרב פפא: מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומר אתה כן? — \u0003משום\u0004 ש\u0003כחו הוא\u0004 באבן, ומכוחו עפה לשם, והרי \u0003אי\u0004 \u0005[אם]\u0006 מ\u0003כחו\u0004 הוא אם כן \u0003תיזיל לעיל\u0004 \u0005[תלך\u0006 האבן \u0005למעלה],\u0006 שהרי הוא זרק כלפי מעלה ולא לצדדים!"],["ענה לו רב פפא: \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 מ\u0003כחו הוא תיזיל לתחת\u0004 \u0005[\u0006ש\u0005תלך,\u0006 תפול, האבן \u0005למטה]\u0006 ולא לצדדים כלל! \u0003אלא, כח כחוש\u0004 \u0005[חלש]\u0006 \u0003הוא,\u0004 שהפניה לצדדים נגרמת על ידי חלק מכוחו של הזורק, ומשום כך חייב.","ובענין דומה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכוהו עשרה בני אדם בעשרה מקלות, ומת\u0004 מחמת המכות, \u0003בין\u0004 שהכוהו כולם \u0003בבת אחת, בין\u0004 שהכוהו \u0003בזה אחר זה\u0004 — \u0003פטורין\u0004 מהריגה, שאף אחד מהם לא עשה מעשה לבדו, ואין שנים מתחייבים על מעשה שעשו כאחד. \u0003ר' יהודה בן בתירא אומר:\u0004 אם הכוהו \u0003בזה אחר זה\u0004 — \u0003האחרון חייב, מפני\u0004 \u0003ש\u0004הוא \u0003קירב את מיתתו.\u0004","\u0003אמר ר' יוחנן: ושניהם,\u0004 חכמים ור' יהודה בן בתירא \u0003מקרא אחד דרשו,\u0004 שנאמר: \u0003\"ואיש כי יכה כל נפש אדם\u0004 מות יומת\u0003\"\u0004 (ויקרא כד, יז), \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003\"כל נפש\"\u0004 משמעו: \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כל נפש,\u0004 שהרוצח הוא לבדו הגורם להוציא כל נפשו של הנרצח. \u0003ור' יהודה בן בתירא סבר\u0004 \u0005[סבור]\u0006 כי \u0003\"כל נפש\"\u0004 משמעו: \u0003כל\u0004 ש\u0003הוא נפש,\u0004 שאפילו על הריגת מקצת נפש, יש לחייב את הרוצח.","\u0003אמר רבא: הכל מודים בהורג את הטריפה\u0004 (אדם שהיה בו מום חמור שברור שימות בגללו) \u0003שהוא פטור,\u0004 שהרי ההרוג הוא במובן מסויים כמת. ומודים גם שאם הרג את ה\u0003גוסס\u0004 שמחלתו נגרמה \u0003בידי שמים שהוא חייב,\u0004 שכיון שלא נעשה בו מעשה הריגה בידי אדם, הרי רוצחו נטל ממנו את כל נפשו עד כמה שהיתה בו. ו\u0003לא נחלקו\u0004 חכמים ור' יהודה בן בתירא \u0003אלא ב\u0004הורג את מי שהיה \u0003גוסס\u0004 משום שנפצע קודם לכן \u0003בידי אדם. מר מדמי ליה\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005מדמים אותו]\u0006 \u0003לטריפה,\u0004 ומשום כך פטור, \u0003ומר מדמי ליה\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005מדמה אותו]\u0006 \u0003לגוסס בידי שמים,\u0004 שחייב עליו.","ושואלים: \u0003מאן דמדמי ליה\u0004 \u0005[מי שמדמה אותו]\u0006 \u0003לטריפה,\u0004 חכמים, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא \u0003לא מדמי ליה\u0004 \u0005[מדמה אותו]\u0006 \u0003לגוסס בידי שמים?\u0004 ומשיבים: \u0003גוסס בידי שמים\u0004 — \u0003לא איתעביד ביה\u0004 \u0005[נעשה בו]\u0006 \u0003מעשה\u0004 בידי אחר להמיתו, \u0003האי איתעביד ביה\u0004 \u0005[זה\u0006 נעשה בו] \u0003מעשה\u0004 בידי אדם, והרי זה כשנים שרצחו שפטורים.","ושואלים לצד אחר: \u0003ומאן דמדמי ליה\u0004 \u0005[ומי שמדמה אותו]\u0006 \u0003לגוסס בידי שמים,\u0004 ר' יהודה, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא \u0003לא מדמי ליה\u0004 \u0005[מדמה אותו]\u0006 \u0003לטריפה?\u0004 ומשיבים: \u0003טריפה\u0004 — \u0003מחתכי סימנים\u0004 \u0005[חתוכים הסימנים],\u0006 שעל ידי מומו הרי הוא כשחוט (שחותכים בו את הסימנים — הקנה והושט) \u0003הא\u0004 \u0005[זה\u0006 הגוסס\u0005]\u0006 — \u0003לא מחתכי\u0004 \u0005[חתוכים]\u0006 בו ה\u0003סימנים,\u0004 ואין בו מום מסויים, אלא חולשה כללית, והוא כשאר אדם חלש או זקן.","\u0003תני תנא\u0004 \u0005[שנה חוזר המשניות]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב ששת:\u0004 מה שנאמר \u0003\"ואיש כי יכה כל נפש אדם\"\u0004 (שם) הרי זה \u0003להביא,\u0004 ללמוד את דין \u0003המכה את חבירו ואין בו\u0004 (בכוח מכה זו) \u0003כדי להמית, ובא אחר והמיתו, שהוא חייב.\u0004","ותוהים: אם הכהו הראשון באופן ש\u0003אין בו כדי להמית\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי הראשון לא עשה בו מעשה רציחה כלל, ורק השני הרגו! \u0003אלא\u0004 כך יש לגרוס: הכהו הראשון בכוח ש\u0003יש בו כדי להמית, ובא אחר והמיתו\u0004 — \u0003שהוא חייב, וסתמא\u0004 \u0005[וסתם]\u0006 אותה ברייתא כשיטת \u0003ר' יהודה בן בתירא\u0004 היא, שלדעתו הגומר מיתתו של אדם נידון כרוצח.","\u0003אמר רבא: ההורג את הטריפה\u0004 — \u0003פטור,\u0004 שהרי הוא כבר כמת. \u0003ו\u0004אדם שהוא עצמו \u0003טריפה שהרג\u0004 אדם אחר, אם הרגו \u0003בפני בית דין\u0004 שראו את מעשה הרצח — \u0003חייב\u0004 מיתה ונהרג על ידם. ואם היה זה \u0003שלא בפני בית דין\u0004 — \u0003פטור.\u0004","ומסבירים: \u0003בפני בית דין מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003חייב?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ובערת הרע מקרבך\"\u0004 (דברים יג, ו), והרי ראו בית דין שהוא רע, ומצווים הם לקיים בו מצוה זו ולבערו. וכאשר היה זה \u0003שלא בפני בית דין\u0004 הריהו \u0003פטור\u0004 — שהרי יש להביא עדים להעיד על המעשה בפני בית דין, ועדות זו \u0003הויא לה\u0004 \u0005[הרי היא]\u0006 \u0003עדות שאי\u0004 (אין) \u0003אתה יכול להזימה,\u0004 כי גם אם מוצאים שהעדים היו עדים זוממים אי אפשר להורגם, שהרי העדים זממו להרוג את הטריפה וההורג את הטריפה — פטור, ואם כן אי אפשר להזים (עד כדי ענישה) עדות זו, וכלל הוא ש\u0003כל עדות שאי אתה יכול להזימה\u0004 — \u0003לא שמה עדות,\u0004 ואינה מתקבלת בבית הדין.","\u0003ואמר רבא: הרובע את\u0004 האדם שהוא \u0003טריפה\u0004 — \u0003חייב\u0004 משום משכב זכר. ואדם \u0003טריפה שרבע,\u0004 אם עשה זאת \u0003בפני בית דין\u0004 — \u0003חייב, שלא בפני בית דין\u0004 — \u0003פטור.\u0004 ומסבירים: \u0003בפני בית דין\u0004 — \u0003חייב, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ובערת הרע מקרבך\"\u0004 (דברים יג, ו), \u0003שלא בפני בית דין פטור\u0004 — \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003עדות שאי אתה יכול להזימה.\u0004","ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי?\u0004 הלא \u0003היינו הך\u0004 \u0005[זה כמו זה]\u0006 הוא, ומדוע מביא רבא דוגמה שניה ברובע שהיא זהה לדוגמה שנתן ברוצח! ומשיבים: \u0003הרובע את הטריפה איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005],\u0006 לפי שיש בכך חידוש: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי כיון שהנרבע הטריפה הריהו נחשב כמת \u0003ליהוי כמאן\u0004 \u0005[\u0006ו\u0005ייחשב כמי]\u0006 ש\u0003משמש\u0004 (שוכב עם) \u0003מת, וליפטר\u0004 \u0005[ויפטר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003משום הנאה\u0004 שיש לו בדבר \u0003הוא\u0004 נענש, \u0003והא אית ליה\u0004 \u0005[וזה יש לו]\u0006 \u0003הנאה\u0004 בשכיבתו, שעדיין הנשכב חי.","\u0003ואמר רבא: עדים שהעידו ב\u0004אדם \u0003טריפה\u0004 שעבר עבירה שחייבים מיתה עליה, \u0003והוזמו\u0004 — \u0003אין נהרגין,\u0004 שהרי זממו להרוג אדם שהוא כמת. ואילו \u0003עדי טריפה,\u0004 עדים שהם עצמם טריפה, \u0003שהוזמו\u0004 — \u0003נהרגין. רב אשי אמר: אפילו עדי טריפה שהוזמו אין נהרגין\u0004 והטעם: \u0003לפי שאינן בזוממי זוממין.\u0004 שהרי אם יבואו עדים ויזימו את עדי הטריפה ויבואו עדים נוספים ויוכיחו שעדים אלה (המזימים) הם הם שהיו זוממים (והם לכן \"זוממי זוממים\") — אי אפשר להרוג את המזימים הראשונים, שהרי נתכוונו להרוג טריפה, על כן גם עדי טריפה שהוזמו — אין נהרגים, שכן זוממיהם אינם ניתנים להזמה.","\u0003ואמר רבא: שור טריפה שהרג\u0004 אדם — \u0003חייב\u0004 מיתה, כשאר בהמה ההורגת אדם. \u0003ושור של אדם טריפה שהרג\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003—\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"השור יסקל וגם בעליו יומת\"\u0004 (שמות כא, כט), ומהשוואת הדברים יחד בפסוק נלמד ש\u0003כל היכא דקרינא ביה\u0004 \u0005[מקום ש\u0006יכולים \u0005אנו לקרוא בו]\u0006 ולקיים \u0003\"וגם בעליו יומת\" קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 ומקיימים \u0003\"השור יסקל\", וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003לא קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"וגם בעליו יומת\", לא קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"השור יסקל\",\u0004 וכיון שאת בעל השור אי אפשר להמית — שהרי טריפה הוא, אף שורו פטור ממיתה.","\u0003רב אשי אמר: אפילו שור טריפה נמי\u0004 \u0005[גם כן]\u0006 \u0003שהרג\u0004 — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון\u0004 ש\u0003אילו\u0004 היו ה\u0003בעלים\u0004 טריפה, \u0003הוו פטירי\u0004 \u0005[היו פטורים],\u0006 \u0003שור\u0004 שהרג \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004 שהרי השווה הכתוב את השור לבעליו לכל דבר.","שנינו במשנה שאם \u0003שיסה\u0004 (גירה) \u0003בו\u0004 בחבירו \u0003את הכלב\u0004 שינשכהו והרגו, או ששיסה בו את הנחש — פטור, שהמשסה היה רק גורם בלבד. ונחלקו חכמים במי שנעץ שיניו של נחש ארסי בחבירו, שר' יהודה מחייב את האיש, וחכמים פוטרים. \u0003אמר רב אחא בר יעקב: כשתמצא לומר,\u0004 כלומר, כשתדקדק ותמצה את השיטות, תוכל לסכם כך: \u0003לדברי ר' יהודה\u0004 — \u0003ארס נחש בין שיניו הוא עומד,\u0004 כלומר, הארס מצוי בתוך שיני הנחש, ואין הנחש עושה מעשה נוסף. \u0003לפיכך\u0004 ה\u0003מכיש\u0004 את הנחש בחבירו, חייב מיתה \u0003בסייף\u0004 כרוצח, וה\u0003נחש\u0004 עצמו לא עשה מעשה, ו\u0003פטור.\u0004","\u0003לדברי חכמים\u0004 — \u0003ארס נחש,\u0004 הנחש \u0003מעצמו הוא מקיא\u0004 אותו מרצונו שלו, ואם כן המוות נגרם על ידי הנחש ואף שאותו אדם גרם לכך — הרי הוא רק כגורם למיתה, ו\u0003לפיכך נחש בסקילה\u0004 כשאר בהמה וחיה שהרגו אדם, \u0003והמכיש פטור\u0004 מדיני אדם.","\u0003המכה את חבירו, בין באבן בין באגרוף ואמדוהו\u0004 הרופאים \u0003למיתה,\u0004 שלדעתם מכה זו מכת מוות היא, \u0003והיקל\u0004 חוליו \u0003ממה שהיה,\u0004 עד שהרופאים החליטו שבכל זאת יחיה, \u0003ולאחר מכאן\u0004 (מכן) \u0003הכביד\u0004 החולי \u0003ומת\u0004 — המכה \u0003חייב\u0004 מיתה, שהוא שגרם לו. \u0003ר' נחמיה אומר: פטור\u0004 הוא במקרה זה, \u0003שרגלים לדבר\u0004 שכיון שהקל החולי בינתיים, ודאי סיבה אחרת היתה שגרמה לבסוף את מותו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003את זו דרש ר' נחמיה:\u0004 נאמר \u0003\"אם יקום והתהלך בחוץ\u0004"],["\u0003על משענתו ונקה המכה\u0004 רק שבתו יתן ורפא ירפא\u0003\"\u0004 (שמות כא, יט), והמילים \"ונקה המכה\" מיותרות לכאורה, \u0003וכי תעלה על דעתך שזה\u0004 המוכה \u0003מהלך בשוק, וזה\u0004 המכה \u0003נהרג\u0004 כרוצח? \u0003אלא\u0004 הכוונה ל\u0003זה שאמדוהו למיתה, והקל ממה שהיה\u0004 והתהלך בשוק, \u0003ולאחר כך הכביד ומת\u0004 — \u0003שהוא פטור,\u0004 וכשיטת ר' נחמיה במשנה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים ואשר לדעתם אף באופן כזה חייב, \u0003האי\u0004 \u0005[זה\u0006 הכתוב\u0005]\u0006 \u0003\"ונקה המכה\" מאי דרשי ביה\u0004 \u0005[מה דורשים\u0006 הם \u0005בו]?\u0006 ומסבירים לדעתם, כי פסוק זה \u0003מלמד\u0004 בדרך אגב \u0003שחובשין\u0004 (כולאים) \u0003אותו\u0004 לפי שעה עד שיתברר מה אירע למוכה, ופירוש \"ונקה\" — שמשחררים אותו מבית המעצר.","ושואלים: \u0003ור' נחמיה, חבישה מנא ליה\u0004 \u0005[מנין לו]\u0006 שעושים כן? ומשיבים: \u0003יליף\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 \u0003מ\u0004דין \u0003מקושש\u0004 העצים בימי משה שנאמר בו \"ויניחו אותו במשמר\" (במדבר טו, לד), ושואלים:","\u0003ורבנן נמי לילפי\u0004 \u0005[וחכמים גם כן שילמדו]\u0006 \u0003מ\u0004דין ה\u0003מקושש!\u0004 ומשיבים: \u0003מקושש בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא\u0004 מתחילה, \u0003ו\u0004אולם \u0003משה לא הוה ידע קטליה במאי\u0004 \u0005[היה יודע מיתתו במה],\u0006 אם בסקילה אם במיתה אחרת, ולכן נחבש. \u0003לאפוקי האי\u0004 \u0005[להוציא\u0006 את \u0005זה]\u0006 שהכה אדם \u0003דלא ידעינן אי בר קטלא\u0004 \u0005[שאין אנו יודעים אם בן מוות]\u0006 \u0003הוא, אי לאו בר קטלא\u0004 \u0005[אם לא בן מוות]\u0006 \u0003הוא,\u0004 ולכן אין ללמוד ממקושש על מכה אדם.","ושואלים: אם כן הרי זה באמת הבדל, ובוודאי אף ר' נחמיה אינו יכול ללמוד מכאן! \u0003ו\u0004אולם \u0003ר' נחמיה יליף\u0004 \u0005[לומד]\u0006 דבר זה ממעשה שהיה ב\u0003מגדף,\u0004 ש\u0003לא הוה ידע אי בר קטלא\u0004 \u0005[היה יודע\u0006 משה \u0005אם בן מוות]\u0006 \u0003הוא, וחבשוהו.\u0004","\u0003ורבנן\u0004 — חכמים מה הם אומרים? — לדעתם כל דינו של \u0003מגדף\u0004 זה \u0003הוראת שעה היתה.\u0004","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003יודע היה משה רבינו שהמקושש\u0004 חייב \u0003מיתה\u0004 \u0003ש\u0004הרי \u0003נאמר: \"\u0004ושמרתם את השבת כי קודש היא לכם \u0003מחלליה מות יומת\"\u0004 (שמות לא, יד), \u0003אלא לא היה יודע באיזו מיתה\u0004 מן המיתות הוא \u0003נהרג, שנאמר:\u0004 \"ויניחו אותו במשמר \u0003כי לא פרש\u0004 מה יעשה לו\" (במדבר טו, לד), \u0003אבל מגדף לא נאמר בו אלא \"\u0004ויניחוהו במשמר \u0003לפרש להם על פי ה' \"\u0004(ויקרא כד, יב) \u0003שלא היה משה יודע אם הוא בן מיתה כל עיקר אם לאו\u0004 \u0005[לא].\u0006","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' נחמיה היינו דכתיבי\u0004 \u0005[זהו שנאמרו]\u0006 במקרא \u0003תרי אומדני\u0004 \u0005[שני אומדנים],\u0006 שנאמר בכתובים אלה: \"וכי יריבון אנשים והכה איש את רעהו באבן או באגרוף ולא ימות ונפל למשכב\" (שמות כא, יח), והרי זה בא ללמד שלאחר ההכאה אומדים את המוכה אם ימות אם לאו, ובפסוק הבא נאמר \"אם יקום והתהלך בחוץ על משענתו ונקה המכה\" (שם יט), הרי אומדן שני שמחליטים בו שהבריא לגמרי. \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 לענין ש\u0003אמדוהו\u0004 מתחילה \u0003למיתה וחיה\u0004 (הבריא) לגמרי, \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 אם \u0003אמדוהו למיתה, והקל ממה שהיה\u0004 ולאחר מכן מת, \u0003אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003תרי אומדני\u0004 \u0005[שני אומדנים]\u0006 \u0003למה לי?\u0004","ומשיבים לשיטתם: \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 למקרה כזה ש\u0003אמדוהו למיתה וחיה,\u0004 שוודאי אינו נהרג עליו אלא משלם פיצויים, \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 — למקרה ש\u0003אמדוהו לחיים ומת,\u0004 שגם אז חייב בתשלומים.","ושואלים: \u0003ור' נחמיה\u0004 כיצד לומד הוא שתי הלכות אלה? ומשיבים: סבור הוא כי מקרה ש\u0003אמדוהו לחיים ומת\u0004 \u0003לא צריך קרא\u0004 \u0005[כתוב]\u0006 מפורש כדי לפטור את המכה ממוות, \u0003שהרי יצא מבית דין זכאי\u0004 בדיון הראשון, שהחליטו שלא הרג את המוכה, שהרי אמדוהו לחיים, ובוודאי אין חוזרים ומחייבים אותו לאחר זמן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המכה את חבירו, ואמדוהו למיתה, וחיה\u0004 — \u0003פוטרין אותו,\u0004 את המכה. \u0003אמדוהו למיתה והקל ממה שהיה\u0004 — \u0003אומדין אותו אומד שני לממון,\u0004 כלומר, כמה יצטרך לשלם לו דמי נזקיו. \u0003ואם לאחר\u0004 מ\u0003כן הכביד\u0004 חוליו \u0003ומת,\u0004 הדין הוא: \u0003הלך\u0004 (לך) \u0003אחר אומד האמצעי\u0004 שהיה לחיים ואין הורגים אותו, אלו \u0003דברי ר' נחמיה. וחכמים אומרים: אין אומד אחר אומד,\u0004 כלומר, על ידי מותו הוכח שהאומד השני היה מוטעה ולא היה אומד אמיתי.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אמדוהו למיתה\u0004 והקל חוליו — \u0003אומדין אותו לחיים.\u0004 אמדוהו מתחילה \u0003לחיים\u0004 ומת — \u0003אין אומדין אותו למיתה\u0004 אחר כך אם הכביד חוליו, אלא הוא פטור כפי שיצא בדין הראשון. \u0003אמדוהו למיתה והקל ממה שהיה\u0004 — \u0003אומדין אותו אומד שני לממון,\u0004 שהרי בוודאי חייב לשלם פיצויים על חבלות שחבל בו, \u0003ואם לאחר\u0004 מ\u0003כן הכביד ומת\u0004 — \u0003משלם נזק וצער ליורשים.\u0004","\u0003מאימתי משלם\u0004 — \u0003משעה שהכהו,\u0004 את שווי הנזק שנגרם אז. ומעירים: \u0003וסתמא\u0004 \u0005[וסתם]\u0006 אותה ברייתא \u0003כ\u0004שיטת \u0003ר' נחמיה\u0004 היא, שהרי לדעת חכמים חייב מיתה גם אם היקל קודם מיתתו.","מי ש\u0003נתכוין להרוג את הבהמה, והרג את האדם\u0004 שעמד סמוך לה, או התכוין \u0003לגוי\u0004 שאינו חייב עליו בבית דין, \u0003והרג את ישראל,\u0004 או התכוון להרוג \u0003נפלים\u0004 שאינו חייב על הריגתם, \u0003והרג את בן קיימא\u0004 — \u0003פטור.\u0004 שכן לא נתכוון להרוג את מי שחייב עליו מיתה (רמ\"ה).","\u0003נתכוין להכותו על מתניו, ו\u0004מכה כזו \u0003לא היה בה כדי להמיתו,\u0004 אילו אכן היתה \u0003על מתניו, והלכה לה\u0004 המכה \u0003על לבו, והיה בה כדי להמיתו\u0004 אילו הכהו \u0003על לבו, ומת\u0004 בה — \u0003פטור,\u0004 שהרי לא נתכוין להכותו מכת מוות. \u0003נתכוין להכותו על לבו,\u0004"],["\u0003והיה בה כדי להמית\u0004 אילו הכהו \u0003על לבו, והלכה לה\u0004 המכה \u0003על מתניו ולא היה בה כדי להמית\u0004 אילו הכהו \u0003על מתניו, ו\u0004בכל זאת \u0003מת\u0004 — \u0003פטור,\u0004 שאמנם נתכוון להמיתו, אבל המעשה כשלעצמו לא היה בו כדי להמית, ומה שגרם מוות לבסוף — מקרה היה.","\u0003נתכוון להכות את הגדול, ולא היה בה\u0004 במכה זו \u0003כדי להמית\u0004 את \u0003הגדול, והלכה לה\u0004 המכה \u0003על הקטן, והיה בה כדי להמית את הקטן, ומת\u0004 — \u0003פטור. נתכון להכות את הקטן, והיה בה כדי להמית את הקטן, והלכה לה\u0004 המכה \u0003על הגדול, ולא היה בה כדי להמית את הגדול, ומת\u0004 — \u0003פטור.\u0004","\u0003אבל\u0004 מי ש\u0003נתכוון להכות\u0004 את חבירו \u0003על מתניו, והיה בה\u0004 במכה זו \u0003כדי להמית על מתניו, והלכה לה על לבו, ומת\u0004 — \u0003חייב,\u0004 שהרי מכל מקום התכוון להמיתו, והיתה המכה ראויה להמיתו בכל מקום שיפגע בו. וכן אם \u0003נתכוון להכות את הגדול, והיה בה\u0004 במכה זו \u0003כדי להמית את הגדול, והלכה לה\u0004 המכה \u0003על הקטן, ומת\u0004 — \u0003חייב. ר' שמעון אומר: אפילו\u0004 אם \u0003נתכוון להרוג את זה והרג את זה,\u0004 אף שעל כל אחד משניהם היה חייב — \u0003פטור\u0004. שאין ממיתים אותו אלא אם עשה בדיוק כפי שנתכוון.","שואלים: דברי \u0003ר' שמעון אהייא\u0004 \u0005[על מה],\u0006 על איזה קטע מן המשנה הוא חולק? \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על סופה]\u0006 של המשנה לענין נתכוון להמית גדול והמית קטן, אם כן אין הסגנון מתאים כלל, כי בלשון \u0003\"ר' שמעון פוטר\" מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005],\u0006 ואין מקום ללשון \"אפילו\" שבדבריו כלל.","\u0003אלא ארישא\u0004 \u0005[על ראשה,\u0006 תחילתה\u0005]\u0006 של המשנה הוא חולק, ששנינו בה: \u0003נתכוון להרוג את הבהמה והרג את האדם,\u0004 או שנתכוון \u0003לגוי והרג את ישראל, לנפלים והרג את בן קיימא\u0004 — \u0003פטור. הא\u0004 \u0005[הרי]\u0006 מובן מכאן שאם \u0003נתכוון להרוג את זה\u0004 שחייב על הריגתו, \u0003והרג את זה\u0004 — \u0003חייב. ר' שמעון\u0004 חולק ו\u0003אומר: אפילו נתכוין להרוג את זה והרג את זה\u0004 — \u0003פטור.\u0004","ומוסיפים להבהיר את החילוק בין השיטות, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי אם \u0003קאי\u0004 \u0005[עומדים]\u0006 \u0003ראובן ושמעון, ואמר\u0004 הרוצח לפני שזרק אבן או ירה: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לראובן קא מיכוונא\u0004 \u0005[אני מתכוון]\u0006 להורגו, \u0003לשמעון לא קא מיכוונא\u0004 \u0005[אין אני מתכוון]\u0006 — \u0003היינו פלוגתייהו\u0004 \u0005[\u0006הרי \u0005זוהי מחלוקתם]\u0006 של חכמים ור' שמעון בצורתה היסודית. ואולם אם \u0003אמר: לחד מינייהו\u0004 \u0005[לאחד מהם],\u0006 שרצונו להרוג אחד מהם, ולא איכפת לו איזה מהם, \u0003מאי\u0004 \u0005[מה הדין]\u0006 בכגון זה? \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה ש\u0003סבור\u0004 הוא ש\u0003ראובן\u0004 הוא זה, והרגו, \u0003ונמצא\u0004 שהוא \u0003שמעון. מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 בכגון זה? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 אינו חייב \u0003עד שיאמר \"לפלוני אני מתכוון\",\u0004 והורגו לאחר הכרזה זו.","לעיקר השיטות ובירור מקורותיהן שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון?\u0004 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וכי יהיה איש שונא לרעהו \u0003וארב לו וקם עליו\u0004 והכהו נפש ומת\" (דברים יט, יא), ומהדגשת הלשון \"לו\" ו\"עליו\" למד ר' שמעון \u0003עד שיתכוון לו\u0004 לנרצח בלבד. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה למדים הם מהדגשה זו? ומשיבים: \u0003אמרי דבי\u0004 \u0005[אמרי\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי\u0004 שמכאן למדים: \u0003פרט לזורק אבן לגו\u0004 \u0005[לתוך]\u0006 חבורת אנשים, ונהרג אחד מהם, שכיון שלא התכוון לאדם מסויים — אינו נהרג.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק\u0006 הדבר\u0005]?\u0006 \u0003אילימא דאיכא\u0004 \u0005[אם תאמר שיש]\u0006 \u0003תשעה גוים ואחד ישראל ביניהן,\u0004 אם כן אין צורך בפסוק מיוחד ללמדנו הלכה זה, שכן \u0003תיפוק ליה דרובא\u0004 \u0005[תצא לו\u0006 ההלכה שפטור מטעם \u0005שרובם]\u0006 \u0003גוים נינהו\u0004 \u0005[הם],\u0006 והסיכוי היה מתחילה שיפגע בגוי ולא בישראל. \u0003אי נמי פלגא ופלגא\u0004 \u0005[או גם כן\u0006 שהיו שם \u0005מחצה ומחצה]\u0006 של גוים ויהודים, הלא \u0003ספק נפשות להקל\u0004 וייפטר מחמת הספק!","אלא \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר כתוב זה אלא למקרה \u0003דאיכא\u0004 \u0005[שיש\u0006 שם\u0005]\u0006 \u0003תשעה ישראל וגוי אחד ביניהן, דהוה ליה\u0004 \u0005[שהרי נעשה]\u0006 במקרה זה ה\u0003גוי\u0004 כ\u0003קבוע,\u0004 והלכה היא: \u0003כל קבוע כמחצה על מחצה דמי\u0004 \u0005[נחשב].\u0006 ופסוק זה הוא מקור לקביעה שמיעוט קבוע שוב אינו נידון כמיעוט אלא כמחצה, ולכן פטור.","ושואלים: \u0003בשלמא לרבנן דאמרי\u0004 \u0005[נניח ל\u0006שיטת \u0005חכמים האומרים],\u0006 כי כש\u0003נתכוון להרוג את זה והרג את זה חייב\u0004 — יש ראייה לדבריהם ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי ינצו אנשים ונגפו אשה הרה\u0004 ויצאו ילדיה ולא יהיה אסון ענוש יענש כאשר ישית עליו בעל האשה ונתן בפלילים\u0003\"\u0004 (שמות כא, כב), \u0003ואמר ר' אלעזר: במצות\u0004 (מריבה) \u0003ש\u0004יש בה כוונת \u0003מיתה\u0004 והריגה \u0003הכתוב מדבר,\u0004 שאותם אנשים שרבו התכוונו להרוג זה את זה. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003אם אסון יהיה ונתתה נפש תחת נפש\"\u0004 (שם כג), והרי זו ראיה שאם התכוין אדם להרוג את חבירו והרג את האשה ההרה — חייב עליה מיתה!","\u0003אלא ל\u0004שיטת \u0003ר' שמעון האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"ונתתה נפש תחת נפש\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 והלא לשיטתו הוא פטור במקרה זה ממיתה! ומשיבים: לשיטת ר' שמעון אין הכוונה שם להריגת נפש ממש, אלא לקנס של \u0003ממון.\u0004 \u0003וכ\u0004דברי \u0003רבי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 במקרה זה \u0003רבי אומר:\u0004 מה שנאמר \u0003\"ונתתה נפש תחת נפש\"\u0004 אין פירושו נפש ממש, אלא כופר נפש, כלומר, \u0003ממון. אתה אומר\u0004 כי כוונתו עונש \u0003ממון, או אינו אלא נפש ממש?\u0004 — על כן נוכיח משימוש הלשון שהכוונה לממון. \u0003נאמרה נתינה למטה\u0004 (\"ונתתה נפש תחת נפש\") \u0003ונאמרה\u0004"],["\u0003נתינה למעלה\u0004 (\"ענוש יענש כאשר ישית עליו בעל האשה ונתן בפלילים\") \u0003מה להלן\u0004 בפלילים הריהו נתינת \u0003ממון, אף כאן\u0004 נתינת נפש משמעה כופר נפש על ידי \u0003ממון.\u0004","\u0003אמר רבא: האי דתנא דבי\u0004 \u0005[\u0006ברייתא \u0005זו ששנויה בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 \u0003מפקא\u0004 \u0005[מוציאה]\u0006 \u0003מ\u0004דברי \u0003רבי, ומפקא מדרבנן\u0004 \u0005[ומוציאה מ\u0006דברי \u0005חכמים],\u0006 ושיטתו שונה בענין זה. \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה:\u0004 נאמרו בסמיכות \u0003מכה אדם ומכה בהמה\u0004 ככתוב \"ומכה בהמה ישלמנה ומכה אדם יומת\" (ויקרא כד, כא),","\u0003מה מכה בהמה לא חלקת בה\u0004 לגבי חובת תשלומים \u0003בין שוגג למזיד, בין מתכוין לשאינו מתכוין, בין\u0004 היתה המכה \u0003דרך ירידה\u0004 או \u0003דרך עלייה\u0004 לגבי חובת תשלומים, שאין \u0003לפוטרו ממון\u0004 באחד מאלה \u0003אלא לחייבו ממון\u0004 בכולם. \u0003אף מכה אדם לא תחלוק בו בין שוגג למזיד, בין מתכוין לשאין מתכוין, בין דרך ירידה לדרך עלייה\u0004 (אף שמחלקים בין דרך עלייה ודרך ירידה לענין חובת גלות) שלא \u0003לחייבו ממון\u0004 על נזקים או קנסות \u0003אלא לפוטרו ממון.\u0004 שבכל מקום שיש רק צד של דיני נפשות — פטור הנאשם מכל תשלומים, גם אם יצא זכאי בדינו לענין ההריגה.","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"שאין מתכוין\"\u0004 שנאמר כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שאין מתכוין כלל\u0004 להריגה ואירע לו שהרג — אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 דין ההורג ב\u0003שוגג\u0004 שנשנה קודם לכן, ואין טעם לחזור שנית על כך. \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמשמעו למקרה \u0003שאין מתכוין\u0004 להרוג \u0003לזה אלא לזה, וקתני\u0004 \u0005[ושנה]\u0006 שאין \u0003לחייבו ממון אלא לפוטרו ממון.\u0004 ונוסיף ונברר: \u0003ו\u0004לשיטת חזקיה, \u0003אי בר קטלא\u0004 \u0005[אם בן מוות]\u0006 \u0003הוא מאי איצטריך למיפטריה\u0004 \u0005[מה הוצרך לפוטרו]\u0006 מ\u0003ממון,\u0004 שהרי בהלכה ברור שאין אדם נהרג וגם משלם ממון,","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003לאו בר קטלא\u0004 \u0005[לא בן מוות]\u0006 \u0003הוא, ולאו בר ממונא\u0004 \u0005[ולא בן\u0006 תשלום \u0005ממון]\u0006 \u0003הוא,\u0004 שלענין חיובו בדיני נפשות סבור הוא כר' שמעון, אבל לדעתו הוא פטור אפילו מתשלום ממון.","\u0003רוצח שנתערב באחרים,\u0004 ואין יודעים מי מהם הוא הרוצח — \u0003כולן פטורין,\u0004 שהרי אי אפשר למצוא את האיש שחטא. \u0003ר' יהודה אומר: כונסין אותן לכיפה\u0004 (לצינוק) ושם ימותו כולם מאליהם.","ועוד בעיה דומה לזו: \u0003כל חייבי מיתות\u0004 שונות \u0003שנתערבו זה בזה\u0004 ואי אפשר לברר מי מהם נתחייב להידון במיתה מסויימת — \u0003נידונין\u0004 כולם \u0003בקלה\u0004 שבמיתות שנתחייב אחד מהם, \u0003הנסקלין\u0004 שנתערבו \u0003בנשרפין, ר' שמעון אומר: נידונין\u0004 כולם \u0003בסקילה,\u0004 לפי \u0003שהשריפה\u0004 לדעתו \u0003חמורה\u0004 מן הסקילה, ולכן ידונו כדין בקלה. \u0003וחכמים אומרים: נידונין\u0004 כולם \u0003בשריפה,\u0004 לפי \u0003שהסקילה\u0004 לדעתם \u0003חמורה\u0004 משריפה.","\u0003אמר להן ר' שמעון\u0004 לחכמים: \u0003אילו לא היתה שריפה חמורה\u0004 מסקילה, כדברי, \u0003לא נתנה לבת כהן שזנתה!\u0004 שהרי בת ישראל מאורסת שזנתה דינה סקילה, ומחמיר הכתוב בבת כהן לדונה בשריפה! \u0003אמרו לו\u0004 חכמים לר' שמעון: \u0003אילו לא היתה סקילה חמורה\u0004 משריפה \u0003לא נתנה למגדף ולעובד עבודה זרה\u0004 הפוגעים ביסוד האמונה.","וכן חלקו אם נתערבו אלה שנגמר דינם להיות \u0003נהרגין\u0004 בסייף בין ה\u0003נחנקין, ר' שמעון אומר:\u0004 יהרגו כולם \u0003בסייף\u0004 שהיא לדעתו המיתה הקלה ביניהן. \u0003וחכמים אומרים:\u0004 יהרגו כולם \u0003בחנק,\u0004 כשיטתם שמיתת חנק היא הקלה.","שנינו במשנה את דינו של רוצח שנתערב באחרים. ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003אחרים\u0004 אלה שנתערב בהם? \u0003אילימא אחרים כשרים,\u0004 סתם בני אדם, חפים מפשע, הרי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 וכי בשל אשמתו של אחד שנתערב בהם יענישו את אלה?! ודאי שפטורים הם! \u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003בהא לימא\u0004 \u0005[בזו שיאמר]\u0006 \u0003ר' יהודה: כונסין אותן לכיפה?\u0004 כיצד יתכן לומר שיכניסו את כל הכשרים למאסר חמור כזה משום רוצח אחד שביניהם?!","(\u0003סימן\u0004 לשמות החכמים שדעתם מובאת להלן ר' א\u0003ב\u0004הו בשם \u0003ש\u0004מואל, ריש ל\u0003ק\u0004יש, \u0003ר\u0004בא).","\u0003אמר ר' אבהו אמר שמואל: הכא\u0004 \u0005[כאן]\u0006 \u0003ברוצח\u0004 שהעידו עדים כשרים על כי הרג את הנפש, ונשאו ונתנו הדיינים בדינו אף \u0003שלא נגמר דינו\u0004 עדיין, והכניסוהו לבית הכלא להמתין עד שיגמר דינו, \u0003שנתערב ברוצחים אחרים שנגמר דינן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולא ברור לנו מי הוא רוצח זה שלא נגמר דינו שנדוננו ונחייבנו. וטעם המחלוקת: \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003אין גומרין דינו של אדם אלא בפניו,\u0004 וכיון שאין יודעים מי הוא הרוצח אי אפשר לגמור את דינו, וכיון שאחד מהם אינו יכול להידון למוות \u0003הלכך\u0004 \u0005[לכן]\u0006 \u0003כולן פטורין,\u0004 משום יחיד זה שאין אפשרות לגמור דינו. \u0003ור' יהודה\u0004 סבור: \u0003מיפטרינהו\u0004 \u0005[לפטור אותם]\u0006 \u0003לגמרי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יתכן, \u0003כיון\u0004 ש\u0003רוצחין נינהו\u0004 \u0005[הם],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003כונסין אותן\u0004 כולם \u0003לכיפה.\u0004","\u0003ריש לקיש אמר:\u0004 אם אירע כעין זה \u0003ב\u0004דין \u0003אדם\u0004 שנטען כי רצח אדם אחר, ונתערב בין בני אדם אחרים — \u0003דכולי עלמא לא פליגי דפטירי\u0004 \u0005[לדעת הכל אין חולקים שפטורים]\u0006 כולם, שלא יעלה על הדעת להעניש אפילו אדם אחד משום חטא של חבירו, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 המשנה עוסקת \u0003בשור\u0004 שנגח והרג אדם \u0003שלא נגמר דינו\u0004 עדיין, \u0003שנתערב בשורים אחרים שנגמר דינן\u0004 למיתה \u0003קמיפלגי\u0004 \u0005[נחלקו].\u0006 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003כמיתת\u0004 ה\u0003בעלים כך מיתת השור, ואין גומרין דינו של שור אלא בפניו,\u0004 כשם שאין גומרים דינו של אדם אלא בפניו. \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003כולן פטורין,\u0004 שהרי אי אפשר לגמור את דינו. \u0003ור' יהודה סבר\u0004 \u0005[סבור]\u0006 ש\u0003כונסין אותן לכיפה,\u0004 שהרי הוא שור המזיק, ושאר השוורים נדונים לסקילה בין כה וכה, ולכך כולאים אותם עד שימותו.","\u0003אמר רבא\u0004"],["\u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, כשמואל או כריש לקיש, וכי \u0003היינו דקתני עלה\u0004 \u0005[זהו ששנינו עליה]\u0006 בברייתא על משנה זו בדבר רוצחים שנתערבו, \u0003אמר ר' יוסי: אפילו\u0004 היה \u0003אבא חלפתא\u0004 (אבי ר' יוסי, שהיה חכם וצדיק) \u0003ביניהן!\u0004 וקשה לשמואל, שוודאי לא ימנה ר' יוסי את אביו בין הרוצחים, ואינו שייך כלל לדברי ריש לקיש בענין תערובת שוורים!","\u0003אלא אמר רבא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את המשנה: \u0003שנים שהיו עומדין\u0004 במקום אחד \u0003ויצא חץ מביניהם והרג\u0004 אדם, ואין יודעים מי הוא שירה את החץ — \u0003שניהם פטורין. ואמר ר' יוסי: אפילו אבא חלפתא ביניהן.\u0004 שאפילו היה אחד מהם איש צדיק כאבא חלפתא שאין מסתבר שהוא הרוצח, כיון שאין עדות גמורה בדבר הרי זה ספק, ושניהם פטורים מספק. וכדי לתרץ את הקושי השני במשנתנו, יש לומר כי היא ממשיכה לדון בנושא אחר, בשוורים.","\u0003ושור שנגמר דינו שנתערב בשוורין אחרים מעלייא\u0004 \u0005[מעולים],\u0006 כלומר, כשרים שלא נגחו — \u0003סוקלין אותן\u0004 כולם. \u0003ר' יהודה אומר: כונסין אותן לכיפה.\u0004","ומעירים \u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פרה שהמיתה\u0004 אדם \u0003ואחר כך ילדה, אם עד שלא נגמר דינה\u0004 למות \u0003ילדה\u0004 — \u0003וולדה מותר,\u0004 ו\u0003אם משנגמר דינה ילדה\u0004 — \u0003וולדה אסור\u0004 שנאסר עמה יחד. \u0003נתערב\u0004 פרה זו \u0003באחרים\u0004 ולא ברור איזוהי הפרה הנוגחת, \u0003ואחרים\u0004 אלה נתערבו בעוד \u0003אחרים\u0004 — \u0003כונסין אותן\u0004 כולם \u0003לכיפה. ר' אלעזר בר' שמעון אומר: מביאין אותן לבית דין וסוקלין אותן,\u0004 הרי סתם ברייתא כדעת ר' יהודה במשנתנו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אם עד שלא נגמר דינה ילדה\u0004 — \u0003וולדה מותרת.\u0004 ושואלים: \u0003ואף על גב דכי\u0004 \u0005[ואף על פי שכאשר]\u0006 \u0003נגחה הות מיעברה\u0004 \u0005[היתה מעוברת]\u0006 כבר?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: ולד הנוגחת אסור\u0004 להקריבו לקרבן, ככל בהמה הורגת אדם, כי אומרים אנו ש\u0003היא\u0004 הפרה הנוגחת \u0003וולדה\u0004 עמה \u0003נגחו,\u0004 שהרי היה עמה בשעת נגיחה. וכן \u0003ולד\u0004 הבהמה \u0003הנרבעת\u0004 שנרבעה על ידי אדם כשהיתה מעוברת ואף היא אסורה לקרבן, גם הוולד \u0003אסור\u0004 כאמו, כי אומרים אנו ש\u0003היא וולדה נרבעו.\u0004 ואם כן קשה לרבא מן הברייתא!","ומשיבים: לשיטתו \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: אין מדובר בפרה מעוברת שנגחה, אלא שנתעברה לאחר המעשה, וכך יש לחלק: \u0003אם עד שלא נגמר דינה עיברה וילדה\u0004 — \u0003וולדה מותר, אם משנגמר דינה\u0004 \u0003עיברה וילדה\u0004 — \u0003וולדה אסור.\u0004","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שכאשר \u0003זה וזה גורם\u0004 — \u0003אסור,\u0004 שאם יש שני גורמים מרכיבים בדבר, ואחד מהם אסור והאחר מותר, הרי הדבר הנגרם על ידם — גם הוא אסור. אם כן מובן הדבר, שהרי הפרה עצמה אסורה בהנאה, וולדה נוצר בחלקו ממנה, וכיון שיש גורם של איסור בוולד — אסור אף הוא."],["\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שכאשר \u0003זה וזה גורם\u0004 — \u0003מותר, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי הוולד לא נוצר מן הפרה לבדה אלא גם מן הפר, והיה בו גם גורם של היתר!","\u0003אלא אמר רבינא: אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003אם עד שלא נגמר דינה עיברה וילדה\u0004 — \u0003ולדה מותר, ואם עד שלא נגמר דינה עיברה, ומשנגמר דינה ילדה\u0004 — \u0003ולדה אסור,\u0004 והטעם הוא כי \u0003עובר ירך אמו הוא\u0004 ונחשב כחלק ממנה וכאשר נגמר דין אמו למיתה — ממילא אף הוולד נאסר יחד עמה.","שנינו במשנה ש\u0003כל חייבי מיתות\u0004 שנתערבו זה בזה נידונים במיתה קלה. ומעירים: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי אדם ש\u0003מותרה לדבר\u0004 \u0003חמור הוי\u0004 \u0005[הריהו]\u0006 \u0003מותרה\u0004 גם \u0003לדבר קל,\u0004 וכגון שמתרים באדם שעל עבירה מסויימת הוא מתחייב בסקילה, ובאמת אינו חייב עליה אלא מיתה קלה — תתפוס ההתראה הזו ויידון במיתה הקלה אף שלא הותרה במפורש שאם יעבור יידון בה, כי ההתראה על החמור נחשבת ככוללת בתוכה גם התראה לדבר הקל. ועל פי טעם זה מובן מדוע חייבי מיתות שנתערבו אלו באלו, נחשבים כולם כמותרים למיתה קלה.","את נסיון ההוכחה הזה דוחים, \u0003אמר ר' ירמיה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהתרו בו סתם\u0004 שחייב מיתה, ולא פירשו באיזה מיתה, \u0003והאי תנא\u0004 \u0005[ו\u0006כשיטת \u0005תנא זה]\u0006 \u0003הוא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ושאר חייבי מיתות שבתורה\u0004 חוץ ממסית שאינו צריך התראה, \u0003אין ממיתין אותן אלא בעדה,\u0004 כלומר, בבית דין של עשרים ושלושה דיינים, \u0003ועדים ו\u0004אחרי \u0003התראה, ועד שיודיעוהו שהוא חייב מיתת בית דין. ר' יהודה אומר: עד שיודיעוהו באיזה מיתה הוא נהרג,\u0004 ומדברי ר' יהודה משמע שלדעת תנא קמא אף שצריך להודיעו שעונשו יהא במיתה, מכל מקום אין צורך בפירוט מיתתו המסויימת, בעת ההתראה.","ומעירים על יסוד המחלוקת בין תנא קמא לר' יהודה, \u0003תנא קמא יליף\u0004 \u0005[הראשון למד]\u0006 \u0003מ\u0004דין ה\u0003מקושש\u0004 עצים שהיה בימי משה, שאף שלא ידעו במה מיתתו (שהרי אף משה לא ידע עד שנאמר לו מפי הגבורה), ולא יכלו להתרות בו, מכל מקום לא עיכב הדבר שיוציאוהו להורג, וכן הדבר בכל התראה לדורות. \u0003ו\u0004אילו \u0003ר' יהודה אומר: מקושש הוראת שעה היתה\u0004 על פי דבר ה', ואין למדים ממנה.","שנינו במשנה שאם נתערבו \u0003הנסקלין\u0004 (חייבי סקילה) \u0003בנשרפין\u0004 (בחייבי שריפה), נחלקו חכמים ור' שמעון אם דין כולם בשריפה או בסקילה. \u0003מתני ליה\u0004 \u0005[\u0006היה \u0005שונה,\u0006 מלמד \u0005לו]\u0006 \u0003ר' יחזקאל\u0004 את \u0003רמי בריה\u0004 \u0005[בנו]\u0006 בנוסח אחר: נתערבו \u0003הנשרפין בנסקלין, ר' שמעון אומר: ידונו\u0004 כולם \u0003בסקילה\u0004 לפי \u0003שהשריפה חמורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של רב יחזקאל: \u0003אבא, לא תיתנייה הכי\u0004 \u0005[אל תשנה,\u0006 תלמד, \u0005אותו כך],\u0006 כי לפי גרסה זו \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 שייפטרו אלה לדעת ר' שמעון מפני הטעם ש\u0003שריפה חמורה\u0004 מסקילה? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 ההלכה שהם פטורים מטעם אחר: \u0003דרובה\u0004 \u0005[שרובם]\u0006 \u0003נסקלין נינהו\u0004 \u0005[הם],\u0006 וכמו בכל תערובת הולכים אחר הרוב. שאל אותו אביו רב יחזקאל: אם כן, \u0003היכי אתנייה\u0004 \u0005[כיצד אלמד אותו]?\u0006","אמר לו ר' יהודה לאביו, שנה לו: \u0003\"\u0004אם נתערבו \u0003הנסקלין בנשרפין\",\u0004 כלומר, שהיו רובם נשרפים, ועל זה \u0003ר' שמעון אומר: ידונו בסקילה,\u0004 לפי \u0003שהשריפה חמורה\u0004 יותר, ולכן מקילים בכולם. הקשה לו אביו רב יחזקאל: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 \u0003וחכמים אומרים: ידונו בשריפה\u0004 — \u0003שהסקילה חמורה.\u0004 ולשיטתך שאנו הולכים אחר הרוב, \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 אותה הלכה מטעם אחר: שהרי \u0003רובה נשרפין נינהו\u0004 \u0005[הם]!\u0006 ולא משום שסקילה חמורה.","והשיב לו בנו ר' יהודה: \u0003התם רבנן הוא דקאמרו ליה\u0004 \u0005[שם חכמים הם שאמרו לו]\u0006 \u0003לר' שמעון: לדידך דאמרת\u0004 \u0005[לשיטתך שאומר אתה]\u0006 ש\u0003שריפה חמורה\u0004 מסקילה ולכאורה אין לחייב בה את הנידונין שנתערבו מפני שיש מעטים שנידונו בסקילה הקלה לדעתך, \u0003לא\u0004 כן הוא, אלא בעיקרם של דברים \u0003סקילה חמורה\u0004 משריפה, אבל במקרה זה אינם צריכים לנימוק זה, כי יש ללכת לפי הרוב.","כאשר נשמע מעשה זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים]\u0006 (גאונים):"],["\u0003לא תימא ליה לאבוך הכי\u0004 \u0005[אל תאמר לו לאביך כך]\u0006 במפורש שהוא טועה, אלא רמוז לו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה אביו עובר על דברי תורה, לא יאמר לו: \"אבא, עברת על דברי תורה\". אלא אומר לו: \"אבא, כך כתיב\u0004 \u0005[נאמר]\u0006 \u0003בתורה\"?\u0004 ומקשים: \u0003סוף סוף היינו הך\u0004 \u0005[זהו זה]\u0006 שמביישו בשאלה זו! \u0003אלא אומר לו\u0004 סתם: \u0003\"אבא, מקרא כתוב בתורה כך הוא\",\u0004 ואומר לו את הדין או המקרא כאילו אינו מתייחס למה שעשה אביו.","\u0003מי שנתחייב בשתי מיתות בית דין,\u0004 שעבר שתי עבירות שונות זו אחר זו, ועל כל אחת מהן הריהו צריך להידון במיתה אחרת — \u0003נידון בחמורה\u0004 שבהן. \u0003עבר עבירה\u0004 אחת \u0003שנתחייב\u0004 בה \u0003שתי מיתות,\u0004 שיש בעבירה שני פרטי איסור, וכגון שבא על חמותו כשהיא אשת איש — הריהו \u0003נידון בחמורה, ר' יוסי אומר: נידון בזיקה הראשונה שבאה עליו,\u0004 שהאיסור הראשון שחלה עליו החובה לפרוש ממנו הוא הקובע, ולפיו נענש.","על האמור במשנה שמי שנתחייב בשתי מיתות נידון בחמורה, שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ו\u0003אלא\u0004 תאמר כי \u0003איתגורי איתגור\u0004 \u0005[הרויח\u0006 בכך\u0005]\u0006 שעבר תחילה עבירה שיוכל לעבור עוד עבירה בעונש קל?","\u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שעבר\u0004 על \u0003עבירה קלה\u0004 שאין מיתתה חמורה כל כך, \u0003ונגמר דינו\u0004 במיתה \u0003על עבירה קלה, ו\u0004בינתיים \u0003חזר ועבר\u0004 על \u0003עבירה חמורה. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003כיון\u0004 ש\u0003נגמר דינו\u0004 למיתה על \u0003עבירה קלה, האי גברא קטילא\u0004 \u0005[זה\u0006 נחשב כאילו \u0005אדם הרוג]\u0006 \u0003הוא\u0004 בפועל, ומה שעושה אחר כך אינו נחשב, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שנענש גם על העבירה האחרת, ואם נתחייב בעטיה מיתה חמורה יותר, הריהו נידון בה.","\u0003בעא מניה אבוה\u0004 \u0005[שאל אותו אביו]\u0006 של \u0003רב יוסף בר חמא מרבה בר נתן: מנא הא מילתא\u0004 \u0005[מנין דבר זה]\u0006 \u0003דאמור רבנן\u0004 \u0005[שאמרו חכמים]\u0006 כי \u0003מי שנתחייב שתי מיתות בית דין\u0004 הריהו \u0003נידון בחמורה\u0004 שביניהן? השיב לו: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והוליד בן פריץ שפך דם\u0004 ועשה אח מאחד מאלה. והוא את כל אלה לא עשה כי גם \u0003אל ההרים אכל ואת אשת רעהו טמא.\u0004 עני ואביון הונה גזלות גזל חבול לא ישיב \u0003ואל הגלולים נשא עיניו\u0004 תועבה עשה\u0003\"\u0004 (יחזקאל יח, י-יב).","וכך יש לפרש: \u0003\"והוליד בן פריץ שפך דם\",\u0004 כלומר, רוצח, ודינו \u0003בסייף; \"\u0004ו\u0003את אשת רעהו טמא\"\u0004 — \u0003זו אשת איש,\u0004 שעל עבירה זו נידון \u0003בחנק; \"ואל הגלולים נשא עיניו\"\u0004 — \u0003זו עבודה זרה,\u0004 שענשה \u0003בסקילה. וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר מכן: \u0003\"מות יומת דמיו בו יהיה\"\u0004 (שם יג), וכבר למדנו כי הביטוי \"דמיו בו\", משמעו \u0003בסקילה,\u0004 ואם כן למדנו מכאן שמי שעבר כמה עבירות נידון בחמורה שבהן.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על הוכחה זו, \u0003רב נחמן בר יצחק: אימא כולהו\u0004 \u0005[אמור שכולן],\u0006 כל העבירות המנויות כאן, הן כאלה שעונשן \u0003בסקילה.\u0004 כיצד? \u0003\"והוליד בן פריץ שפך דם\"\u0004 — \u0003זה בן סורר ומורה\u0004 שעונשו \u0003בסקילה; \"אשת רעהו טמא\"\u0004 — \u0003זו נערה המאורסה\u0004 שהבא עליה נדון \u0003בסקילה; \"ואל הגלולים נשא עיניו\"\u0004 — \u0003זו עבודה זרה\u0004 שהעובד אותה נידון \u0003בסקילה?!\u0004","על כך משיבים: \u0003אם כן,\u0004 לפי ביאור זה \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 \u0003יחזקאל\u0004 בכך? שלפי ההסבר הראשון למדנו מכאן חידוש הלכה, ואולם כדברי רב נחמן בר יצחק אין בכך כל חידוש! ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 על דברי \u0003תורה קא מהדר\u0004 \u0005[הוא חוזר],\u0006 שלא רצה ללמדנו חידושי הלכה, אלא לחזור ולהזהיר על קיום דברי התורה! ומשיבים: \u0003אם כן, איבעי ליה לאהדורה כי היכי דאהדרה\u0004 \u0005[צריך היה לחזור עליה כפי שחזר עליה]\u0006 \u0003משה רבינו\u0004 כלשונו, ומאחר ושינה לשון וסדר, הרי זו הוכחה שרצה ללמד הלכה חדשה.","כיון שנזכר כתוב זה מביאים את מה ש\u0003דרש רב אחא בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 קודם לכן \"אל ההרים לא אכל ועיניו לא נשא אל גלולי בית ישראל ואת אשת רעהו לא טמא ואל אשה נדה לא יקרב\" (שם ו) — אין להבינו כפשוטו ממש, שעל איש הנזהר רק מעבירות אלה לא ייאמר שצדיק הוא, אלא יש לדורשו כך: \u0003\"אל ההרים לא אכל\"\u0004 — לרמז \u0003שלא אכל בזכות אבותיו,\u0004 שאינו נזקק לזכות האבות (הקרויים במדרש \"הרים\"), אלא זכות וצדקת עצמו יש לו. \u0003\"ועיניו לא נשא אל גלולי בית ישראל\"\u0004 — שמתרחק מכל הדומה לה, עד כדי \u0003שלא הלך בקומה זקופה,\u0004 כי ההולך כך נראה כמתגאה, והוא כעובד עבודה זרה.","\u0003\"ואת אשת רעהו לא טמא\"\u0004 — \u0003שלא ירד לאומנות חבירו,\u0004 שאינו מתחיל לעסוק במלאכה שחבירו עוסק בה ומזיק לו. \u0003\"ואל אשה נדה לא יקרב\"\u0004 — \u0003שלא נהנה מקופה של צדקה\u0004 גם בשעת צורכו. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"צדיק הוא חיה יחיה\"\u0004 (שם ט), על איש כזה אפשר לומר דברים אלה. ומסופר ש\u0003כשהיה רבן גמליאל מגיע למקרא הזה\u0004 \"את כל חקותי שמר ויעשה אותם חיה יחיה\" (שם יט) (רש\"ש) \u0003היה בוכה, ואמר: מאן דעביד לכולהו\u0004 \u0005[מי שעושה את כולן]\u0006 \u0003הוא דחיי\u0004 \u0005[שיחיה],\u0006 ואילו המסתפק \u0003בחדא מינייהו\u0004 \u0005[באחת מהן]\u0006 — \u0003לא?!\u0004 ומה יהיה על אלה שאין יכולים להזהר בכולן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא\u0004 לנחמו: \u0003אלא מעתה\u0004 שאתה מבין \"כל\" בצורה זו, וכי תבין גם את האמור לאחר רשימת איסורי העריות: \u0003\"אל תטמאו בכל אלה\"\u0004 (ויקרא יח, כד) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר כי דווקא העובר \u0003בכולהו\u0004 \u0005[בכולן]\u0006 יחד — \u0003אין\u0004 \u0005[כן]\u0006 ייענש, ואילו העובר רק \u0003בחדא מינייהו\u0004 \u0005[באחת מהן]\u0006 — \u0003לא\u0004 ייענש? \u0003אלא\u0004 ודאי הכוונה היא: \u0003באחת מכל אלה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 במקרא שלנו הכוונה שאם נזהר \u0003באחת מכל אלה\u0004 — זוכה לחיי עולם.","שנינו במשנה שאם \u0003עבר עבירה\u0004 אחת שיש בה שתי מיתות הריהו נידון בחמורה שביניהן, ולדעת ר' יוסי הריהו נידון בזיקה ראשונה שבאה עליו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003כיצד,\u0004 כלומר, באיזה מקרה \u0003אמר ר' יוסי\u0004 שהריהו \u0003נידון בזיקה ראשונה הבאה עליו?\u0004 — אם היתה אשה זו מקודם \u0003חמותו,\u0004 והיתה אלמנה או גרושה כשנשא את בתה, \u0003ונעשית\u0004 אחר כך \u0003אשת איש\u0004 ובא עליה — \u0003נידון\u0004 משום \u0003חמותו,\u0004 שזו היתה לגביו זיקה ראשונה של איסור. ואם היתה אשה זו \u0003אשת איש ונעשית\u0004 אחר כך \u0003חמותו\u0004 כשנשא את בתה — אם בא עליה \u0003נידון באשת איש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא:\u0004 אם היתה מתחילה \u0003חמותו ונעשית אשת איש\u0004 מדוע אומר אתה ש\u0003נידון\u0004 רק \u0003בחמותו?\u0004","\u0003לידון נמי\u0004 \u0005[שידון גם כן]\u0006 על \u0003איסור אשת איש! דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' אבהו: מודה ר' יוסי ב\"איסור מוסיף\"!\u0004 שאף שר' יוסי סבור שאין איסור חל על איסור, מכל מקום כאשר העבירה השניה היא בבחינת \"איסור מוסיף\", שאיסורה כללי יותר — מודה ר' יוסי שכיון שחל האיסור על אחרים, חל גם עליו איסור נוסף. ואף כאן, הלא איסור אשת איש כללי הוא, שחל על הכל ומקיף יותר מאיסור חמותו (החל רק על חתניה), ולפיכך צריך היה לשיטת ר' יוסי להעניש אותו אף משום איסור אשת איש!"],["\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אדא ברי\u0004 \u0005[בני]\u0006 \u0003בתרי קטלי קטלת ליה\u0004 \u0005[בשתי\u0006 מיתות \u0005אתה הורג אותו]?!\u0006 כלומר, באמת מודה ר' יוסי שאיסור אשת איש חל על איסור חמותו, ואם היה הדבר בשוגג חייב להביא שני קרבנות חטאת, אבל כשנידון למיתה הרי אי אפשר לחנקו אחר שריפתו.","\u0003מי שלקה\u0004 פעם אחת על עבירה שעבר, \u0003ושנה\u0004 בעבירה, והלקוהו פעם שניה, שרואים בו שהוא עבריין מועד — \u0003בית דין מכניסין אותו לכיפה\u0004 (צינוק) \u0003ומאכילין אותו\u0004 פת \u0003שעורין\u0004 (רמב\"ם) \u0003עד שכריסו מתבקעת\u0004 מפני רוע המזון, ומת.","על עצם ההלכה תוהים: וכי \u0003משום\u0004 ש\u0003לקה ושנה\u0004 ועבר עבירות שאינן כה חמורות \u0003בית דין כונסין אותו לכיפה\u0004 למאסר לעולם, ומקרבים את מותו?! \u0003אמר ר' ירמיה אמר ר' שמעון בן לקיש: הכא\u0004 \u0005[כאן]\u0006 \u0003במלקיות של כריתות עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שעבר עבירות שחייבים עליהן כרת, ואם התרו בו — נדון למלקות. \u0003דגברא בר קטלא\u0004 \u0005[שאדם\u0006 זה בעצם \u0005בן מוות]\u0006 \u0003הוא,\u0004 שהרי עונש הכרת הוא מיתתו בידי שמים, \u0003ו\u0004אולם \u0003קרובי\u0004 \u0005[להתקרב]\u0006 \u0003הוא\u0004 ש\u0003לא מיקרב קטליה\u0004 \u0005[נתקרבה מיתתו]\u0006 משום שאינה מסורה בידי אדם אלא בידי שמים, \u0003וכיון דקא\u0004 \u0005[שהוא]\u0006 \u0003מוותר,\u0004 מפקיר \u0003לה נפשיה\u0004 \u0005[\u0006את \u0005עצמו]\u0006 בעבירותיו \u0003מקרבינן ליה לקטליה עילויה\u0004 \u0005[אנו מקרבים את מיתתו עליו]\u0006 על ידי הכיפה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא, תא אסברא\u0004 \u0005[בוא\u0006 ו\u0005אסביר]\u0006 \u0003לך\u0004 פרטי הלכה זו: מדובר כאן באופן שלקה \u0003במלקיות של כרת אחת,\u0004 שעבר ושנה אותה עבירה, \u0003אבל\u0004 מי שלקה מלקות \u0003של שתים ושל שלש כריתות\u0004 מעבירות שונות — אינו נענש כך, כי \u0003איסורי\u0004 \u0005[איסורים]\u0006 \u0003הוא דקא טעים\u0004 \u0005[שהוא,\u0006 שרצונו, \u0005לטעום]\u0006 שרוצה ליהנות מדברים שונים. \u0003ולא מוותר,\u0004 מפקיר את עצמו \u0003כולי האי\u0004 \u0005[כל כך]\u0006 למיתה, אלא מפני תאוותו עשה.","שנינו במשנה שכונסים לכיפה \u0003מי שלקה ושנה\u0004 ונדייק: \u0003שנה\u0004 משמע \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא שילש\u0004 בעבירה, \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 היא? \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כשיטת \u0003רבן שמעון בן גמליאל\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר\u0004 ש\u0003עד תלת זימני\u0004 \u0005[שלוש פעמים]\u0006 \u0003לא הויא\u0004 \u0005[אין זו]\u0006 \u0003חזקה,\u0004 ואם כן, העובר פעמיים עדיין לא יוחזק כבעל עבירה קבוע, ולא יענשוהו עד כדי כך!","\u0003אמר רבינא\u0004 לדחות קושי זה: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבן שמעון בן גמליאל, קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003עבירות מחזיקות\u0004 בחזקת רשע, כלומר, אין חזקת עבריין לענין זה באה משום שלקה שלש פעמים, אלא משום העבירות שעובר, ואם כן משנתנו האומרת \"לקה ושנה\" עולה יפה גם לדעת רבן שמעון בן גמליאל, שכן אדם זה לקה ושנה בעבירה, ושוב לקה, וכיון ששילש בעבירה מכניסים אותו לכיפה בלא להלקות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003עבר עבירה שיש בה מלקות פעם ראשונה ושניה\u0004 — \u0003מלקין אותו, ושלישית\u0004 — \u0003כונסין אותו לכיפה! אבא שאול אומר: אף בשלישית מלקין אותו,\u0004 ורק \u0003ברביעית כונסין אותו לכיפה. מאי לאו\u0004 \u0005[האם לא]\u0006 נבין את המחלוקת הזו כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מלקיות מחזיקות,\u0004 הן שעושות את החזקה שהוא עבריין מועד, ואם כן חכמים ואבא שאול \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רבי ורבן שמעון בן גמליאל קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 האם חזקה היא בפעמיים או בשלש!","ודוחים: \u0003לא,\u0004 אפשר לפרש \u0003דכולי עלמא אית להו\u0004 \u0005[הכל יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003רבן שמעון בן גמליאל\u0004 שחזקה בשלוש פעמים, \u0003והכא בהא קא מיפלגי\u0004 \u0005[וכאן ב\u0006דבר \u0005זה הם חלוקים]\u0006 \u0003דמר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]\u0006 כי בשלישית כונסים אותו לכיפה כי ה\u0003עבירות\u0004 עצמן הן ש\u0003מחזיקות,\u0004 והרי אדם זה שילש בעבירה, \u0003ומר סבר\u0004 \u0005[והחכם,\u0006 אבא שאול, \u0005סבור]\u0006 שה\u0003מלקיות\u0004 הן ש\u0003מחזיקות,\u0004 וזה אמנם עבר בשלישית אך טרם לקה ולא הוחזק עד שילקה, וכיון שלקה בפעם השלישית ושב עבר ברביעית — ידון לכיפה.","על הסבר זה של המחלוקת מקשים \u0003והדתניא\u0004 \u0005[ומה ששנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003התרו בו\u0004 בעבירה שחייבים עליה מלקות, \u0003ושתק\u0004 ולא אמר שהוא מקבל על עצמו את ההתראה, וכן אם \u0003התרו בו והרכין ראשו\u0004 ולא אמר במפורש, שמקבל עליו, הרי \u0003פעם ראשונה ושניה\u0004 שאירע דבר כגון זה \u0003מתרין בו\u0004 אבל אין בית הדין עונשו, כיון שלא אמר במפורש שהוא מקבל את ההתראה. ואולם אם עשה כן פעם \u0003שלישית\u0004 — \u0003כונסין אותו לכיפה. אבא שאול אומר: אף בשלישית מתרין בו,\u0004 ורק \u0003ברביעית כונסין אותו לכיפה,\u0004","\u0003והתם\u0004 \u0005[ושם]\u0006 בברייתא זו הלא \u0003מלקות ליכא\u0004 \u0005[אין],\u0006 שהרי לא קבל עליו התראה ואינו לוקה ומדובר באדם שרק עבר כמה עבירות, ואם תפרש שאינם חולקים בשאלה בכמה פעמים היא חזקה, אם כן \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 \u0003אמר רבינא: ב\u0004שאלה אם הכנסתו ל\u0003כיפה צריכה התראה קמיפלגי\u0004 \u0005[נחלקו],\u0006 שחכמים סבורים שכיון שעבר ושנה ושילש את אי ציותו להתראה, מכניסין אותו לכיפה, ואבא שאול אומר שלפני שעובר פעם שלישית יש להודיעו שאם לא יימנע מכך — יוכנס לכיפה, וכיון שלא הודיעוהו — לא יוכנס, אלא לאחר עבירה רביעית, שלפניה יתרוהו שאם ישוב ויעבור — יוכנס לכיפה.","לגוף ההלכה שואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 טיבה של \u0003כיפה\u0004 זו? \u0003אמר רב יהודה:\u0004 חדר קטן שהוא רק \u0003מלא קומתו\u0004 של הנידון ואינו יכול לנוע בו. ושואלים: \u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז]\u0006 עונש זה? \u0003אמר ריש לקיש: \"תמותת רשע רעה\"\u0004 (תהלים לד, כב), כלומר, סופו של הרשע שהוא מת ברעתו — ונעשה הדבר במיתה קשה זו.","ואגב הזכרת רעה זו מביאים מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי גם לא ידע האדם את עתו כדגים שנאחזים במצודה רעה\"\u0004 (קהלת ט, יב), \u0003מאי\u0004 \u0005[מה]\u0006 טיבה של \u0003\"מצודה רעה\"\u0004 זו? \u0003אמר ריש לקיש: חכה,\u0004 שאף שהיא קטנה, הדג שהוא גדול ממנה בהרבה נתפס בה, ואינו יכול להיחלץ ממנה.","\u0003ההורג נפש\u0004 אדם \u0003שלא בעדים\u0004 ואי אפשר לדונו בדין סנהדרין — \u0003מכניסין אותו לכיפה, ומאכילין אותו לחם צר ומים לחץ,\u0004 כלשון הכתוב (\"ונתן לכם ה' לחם צר ומים לחץ\". ישעיה ל, כ).","ושואלים: אם לא היו עדים, \u0003מנא ידעינן\u0004 \u0005[מנין יודעים אנו]\u0006 שהרג, שיענישוהו על כך? \u0003אמר רב: בעדות מיוחדת,\u0004 כלומר, שראו אותו העדים כשהם עומדים בשני מקומות, ועדות כזו אין בית הדין יכול לחייב עליה, אף כי ברור שהעדים מספרים אמת. \u0003ושמואל אמר:\u0004 מדובר באופן שהעידו בו \u0003ש\u0004הרג אדם אבל \u0003לא\u0004 היתה \u0003התראה\u0004 לפני המעשה, שאי אפשר לחייבו.","\u0003ורב חסדא אמר אבימי: כגון דאיתכחוש\u0004 \u0005[שהוכחשו]\u0006 העדים \u0003בבדיקות ולא איתכחוש\u0004 \u0005[הוכחשו]\u0006 \u0003בחקירות,\u0004 שנמצאה סתירה חיצונית בעדותם. \u0003כדתנן\u0004 \u0005[\u0006כפי \u0005ששנוי]\u0006 \u0003מעשה ובדק בן זכאי בעוקצי תאנים\u0004 שתחת עץ התאנה אירע לדברי העדים הרצח, ובחן רבן יוחנן בן זכאי את העדים בעובי עוקצי תאנה זו, לראות אם יכחישו העדים זה את זה בפרט קטן וטפל כזה, כדי להציל את הנאשם (ראה לעיל סנהדרין מא, א). אבל ברור לבית הדין שעצם המעשה שהעידו עליו העדים — אמת הוא, ומשום כך מכניסין אותו לכיפה.","שנינו במשנה ש\u0003מאכילין אותו לחם צר ומים לחץ.\u0004 ומעירים: \u0003מאי שנא הכא דקתני\u0004 \u0005[במה שונה כאן\u0006 במשנתנו \u0005ששנינו]\u0006 ש\u0003נותנין לו לחם צר ומים לחץ, ומאי שנא התם דקתני\u0004 \u0005[ובמה שונה שם\u0006 במשנה הקודמת \u0005ששנינו]\u0006 ש\u0003מאכילין אותו שעורין עד שכריסו מתבקעת,\u0004 האם שני מיני עונש הם? \u0003אמר רב ששת:\u0004 ענין אחד הוא, \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003נותנין לו\u0004 תחילה \u0003לחם צר ומים לחץ עד שיוקטן מעיינו,\u0004 כלומר, עד שתתכווץ בטנו ויתרגל למזון מועט, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מאכילין אותו שעורין\u0004 שנפחן מרובה \u0003עד שכריסו מתבקעת.\u0004","\u0003הגונב את הקסוה, והמקלל בקוסם, והבועל ארמית\u0004 (גויה) — \u0003קנאין פוגעין בו\u0004 (הורגים אותו). שאמנם לא נאמר בתורה שחייב על כל אלו מיתה בידי אדם, ואולם כל המקנא את קנאת ה' ופוגע בו — מותר לו. \u0003כהן ששמש\u0004 במקדש \u0003בטומאה\u0004 — \u0003אין אחיו הכהנים מביאין אותו לבית דין, אלא פרחי כהונה\u0004 (צעירי הכהנים) \u0003מוציאין אותו חוץ לעזרה ומפציעין\u0004 (שוברים) \u0003את מוחו בגזירין\u0004 (חתיכות של עץ). \u0003זר\u0004 (שאינו כהן), \u0003ששמש במקדש, ר' עקיבא אומר:\u0004 דינו \u0003בחנק, וחכמים אומרים:\u0004 אינו נענש בידי אדם, אלא \u0003בידי שמים.\u0004","שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"קסוה\"\u0004 זו שהוזכרה במשנה? \u0003אמר רב יהודה: כלי שרת,\u0004 כלומר, הרי זה כינוי לכל אחד מכלי השרת שבמקדש. \u0003וכן הוא אומר \"ואת קשות הנסך\"\u0004 (במדבר ד, ז), הרי ש\"קסוה\" הוא שם של כלי שרת. ושואלים: \u0003והיכא רמיזא\u0004 \u0005[והיכן נרמז]\u0006 דין זה שהגונב כלי מכלי הקודש דינו מיתה? ומשיבים, שנאמר: \u0003\"ולא יבאו לראות כבלע את הקדש ומתו\"\u0004 (שם כ), ומפרשים: הבולע, הלוקח לעצמו, חפץ של קודש דינו מיתה.","שנינו במשנה ביטוי סתום: \u0003\"והמקלל בקוסם\". תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 פירושו הוא, שאומר \u0003יכה קוסם את קוסמו,\u0004 כלומר, מקלל כלפי שמים, בשמה של עבודה זרה, אלא שאינו מפרש את שם ה', וחושב שקוסם אחר יוכל לקלל את קוסמו, שאף כלפי השכינה הוא מתבטא בכינוי של קוסם. \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה בר מרי, אמרי\u0004 \u0005[אמרו]:\u0006 \u0003יכהו קוסם לו\u0004 — לאיש שעמו הוא רב, \u0003ולקונו ולמקנו\u0004 (רבונו, אדונו, הנותן לו כל טוב) וכיון שכך הריהו מקלל כלפי מעלה ולכן מותר להורגו.","בין אלו שקנאים פוגעים בהם שנינו במשנה גם את \u0003הבועל ארמית. בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב כהנא מרב:\u0004"],["אם \u0003לא פגעו בו קנאין, מהו\u0004 עונשו? \u0003אינשייה\u0004 \u0005[שכח]\u0006 \u0003רב לגמריה\u0004 \u0005[את תלמודו]\u0006 בנושא זה. \u0003אקריוהו\u0004 \u0005[הקריאו לו]\u0006 \u0003לרב כהנא בחלמיה\u0004 \u0005[בחלומו]\u0006 פסוק זה: \u0003\"בגדה יהודה ותועבה נעשתה בישראל ובירושל ם כי חלל יהודה קדש ה' אשר אהב ובעל בת אל נכר\"\u0004 (מלאכי ב, יא). \u0003אתא\u0004 \u0005[בא]\u0006 רב כהנא \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב: \u0003הכי אקריון\u0004 \u0005[כך הקריאו לי\u0006 בחלומי\u0005].\u0006","\u0003אדכריה\u0004 \u0005[נזכר]\u0006 \u0003רב לגמריה\u0004 \u0005[בתלמודו],\u0006 ואמר: באמת על פסוק זה למדתי דברים בנושא זה; \u0003\"בגדה יהודה\"\u0004 — \u0003זו\u0004 חטא \u0003עבודה זרה, וכן הוא אומר\u0004 לשון \"בגדה\" בענין עבודה זרה: \"אכן בגדה אשה מרעה \u0003כן בגדתם בי בית ישראל נאם ה' \"\u0004(ירמיה ג, כ). \u0003\"ותועבה נעשתה בישראל ובירושל ם\"\u0004 — \u0003זה\u0004 עבירה של \u0003משכב זכור, וכן הוא אומר\u0004 לשון \"תועבה\" בענין משכב זכר: \u0003\"ואת זכר לא תשכב משכבי אשה תועבה היא\"\u0004 (ויקרא יח, כב). \u0003\"כי חלל יהודה קדש ה' \"\u0004— \u0003זו זונה, וכן הוא אומר\u0004 לשון \"קדש\" בענין זנות: \"לא תהיה קדשה מבנות ישראל ו\u0003לא יהיה קדש\u0004 מבני ישראל\" (דברים כג, יח). \u0003\"ובעל בת אל נכר\"\u0004 — \u0003זה הבא על הגויה,\u0004","\u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו],\u0006 לגבי כל הנזכר לעיל: \u0003\"יכרת ה' לאיש אשר יעשנה ער וענה מאהלי יעקב ומגיש מנחה לה' צבאות\"\u0004 (מלאכי ב, יב), וכוונתו: \u0003אם תלמיד חכם הוא\u0004 — \u0003לא יהיה לו ער,\u0004 כלומר, אדם שיוכל להיות אומר ודורש \u0003בחכמים\u0004 שיתייחסו אליו, \u0003ועונה בתלמידים\u0004 שיוכל ללמוד ולענות תשובה לשואלים. \u0003אם כהן הוא\u0004 — \u0003לא יהיה לו בן מגיש מנחה לה' צבאות.\u0004","\u0003אמר ר' חייא בר אבויה: כל הבא על הגויה\u0004 הריהו \u0003כאילו מתחתן בעבודה זרה\u0004 עצמה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובעל בת אל נכר\"\u0004 (שם יא), ויש לתמוה על לשון הכתוב: \u0003וכי בת יש לו לאל נכר?\u0004 — \u0003אלא זה הבא על הגויה\u0004 שהיא קשורה ודבוקה באל זר.","כיון שהוזכר שמו של ר' חייא בר אבויה מביאים עוד מאמר משמו. \u0003אמר ר' חייא בר אבויה: כתוב\u0004 היה \u0003על גלגלתו של יהויקים\u0004 מלך יהודה \u0003\"זאת ועוד אחרת\",\u0004 כלומר, עונש זה שקיבל ועוד עונש נוסף שיביא עליו. ומסופר: \u0003זקינו\u0004 (סבו) של \u0003ר' פרידא\u0004 והוא ר' חייא בר אבויה \u0003אשכח ההוא גולגלתא דהות שדיא\u0004 \u0005[מצא גולגולת אחת שהיתה מושלכת]\u0006 \u0003בשערי ירושלים, והוה\u0004 \u0005[והיה]\u0006 \u0003כתוב עילויה\u0004 \u0005[עליה]\u0006 \u0003\"זאת ועוד אחרת\".\u0004 \u0003קברה והדר נבוג\u0004 \u0005[וחזרה ובצבצה],\u0006 \u0003קברה\u0004 שוב \u0003והדר נבוג\u0004 \u0005[וחזרה ובצבצה].\u0006 \u0003אמר: האי גולגלתא\u0004 \u0005[זאת הגולגולת]\u0006 \u0003של יהויקים\u0004 היא \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"קבורת חמור יקבר סחוב והשלך מהלאה לשערי ירושל ם\"\u0004 (ירמיה כב, יט), שלא ישכון וינוח בקברו.","\u0003אמר:\u0004 בכל זאת \u0003מלכא\u0004 \u0005[מלך]\u0006 \u0003הוא, ולאו אורח ארעא לבזויי\u0004 \u0005[ואין דרך ארץ לבזותו].\u0006 \u0003שקלה\u0004 \u0005[לקחה]\u0006 לגולגולת זו, \u0003כרכה בשיראי\u0004 \u0005[במשי]\u0006 \u0003ואותביה בסיפטא\u0004 \u0005[והניחה ב\u0006תוך \u0005תיבה].\u0006 \u0003אתאי דביתהו, חזיתה\u0004 \u0005[באה אשתו, ראתה אותה\u0006 את הגולגולת\u0005].\u0006 \u0003נפקת\u0004 \u0005[יצאה]\u0006 ו\u0003אמרה\u0004 \u0003להו לשיבבתהא\u0004 \u0005[להן לשכנותיה]\u0006 את הדבר, ושאלה אותן מה הוא. \u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003לה\u0004 שכינותיה: \u0003האי דאיתתא קמייתא\u0004 \u0005[\u0006גולגולת \u0005זו של האשה הראשונה]\u0006 \u0003היא,\u0004 \u0003דלא קא מנשי לה\u0004 \u0005[שאינו שוכח אותה],\u0006 ושומר את גולגלתה לזכרון. כעסה האשה, \u0003שגרתא לתנורא וקלתה\u0004 \u0005[הסיקה את התנור ושרפה אותה],\u0006 את הגולגולת. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 ר' חייא בר אבויה, ונודע לו הדבר, \u0003אמר: היינו דכתיב עילויה\u0004 \u0005[זהו שנאמר עליה]\u0006 \u0003\"זאת ועוד אחרת\",\u0004 שלא נגמר עונשו בבזיון ההשלכה מחוץ לקבר, אלא אף בשריפה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: בית דינו של חשמונאי גזרו\u0004 כל \u0003הבא על הגויה חייב עליה משום נשג\"א:\u0004 \u0003נ\u0004 דה — שלא טהרה מנדתה, (ואף שאין בה טומאה מן התורה, הריהי מכל מקום מאוסה כנדה). \u0003ש\u0004פחה, שלעומת בת ישראל הריהי כשפחה, \u0003ג\u0004 ויה, ו\u0003א\u0004 שת איש.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר:\u0004 חייב \u0003משום נשג\"ז\u0004 — \u0003נדה, שפחה, גויה, זונה. אבל משום אישות\u0004 אינו עובר, כי \u0003לית להו\u0004 \u0005[אין להם]\u0006 לגויים אישות ממש, שכל קשרים שביניהם הם ארעיים מעיקרם וכקשר זנות נחשבים. \u0003ואידך\u0004 \u0005[והאחר]\u0006 סבור כי \u0003נשייהו\u0004 \u0005[נשותיהם]\u0006 \u0003ודאי לא מיפקרי\u0004 \u0005[מפקירים],\u0006 ואשתו של גוי נחשבת משום כך כאשת איש.","\u0003אמר רב חסדא: הבא לימלך\u0004 בבית דין מה לעשות אם רואה הוא ישראל הבא על הגויה — \u0003אין מורין לו\u0004 שמותר לו להרגו. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן\u0006\u0005]\u0006 בשם אמורא אחר, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: הבא לימלך\u0004 בענין זה — \u0003אין מורין לו\u0004 היתר להורגו.","\u0003ולא עוד אלא שאם פירש זמרי\u0004 בן סלוא מן האשה \u0003ו\u0004בכל זאת \u0003הרגו פנחס\u0004 — היה \u0003נהרג עליו,\u0004 שאין קנאים רשאים לפגוע בו אלא בשעת מעשה. ועוד, אילו \u0003נהפך זמרי והרגו לפנחס\u0004 מתוך התגוננות — \u0003אין\u0004 הוא \u0003נהרג עליו.\u0004 וטעמו — \u0003שהרי\u0004 פנחס \u0003רודף הוא\u0004 להורגו ורשאי אדם להתגונן, כשאינו חייב מיתה על פי דין.","נאמר: \u0003\"ויאמר משה אל שפטי ישראל\u0004 הרגו איש אנשיו הנצמדים לבעל פעור\u0003\"\u0004 (במדבר כה, ה). \u0003הלך שבטו של שמעון אצל זמרי בן סלוא\u0004 נשיאם, \u0003אמרו לו: הן דנין דיני נפשות\u0004 והורגין מאתנו, \u0003ואתה יושב ושותק? מה עשה, עמד וקיבץ עשרים וארבעה אלף מישראל, והלך אצל כזבי\u0004 בת צור נסיכת מדין, \u0003אמר לה: השמיעי לי\u0004 (שכבי עמי). \u0003אמרה לו: בת מלך אני, וכן צוה לי אבי: לא תשמעי אלא לגדול שבהם. אמר לה: אף הוא,\u0004 זמרי עצמו, \u0003נשיא שבט הוא. ולא עוד, אלא שהוא,\u0004 זמרי, \u0003גדול ממנו\u0004 ממשה, \u0003שהוא\u0004 זמרי \u0003שני לבטן,\u0004 שהוא שייך לשבט שמעון שהוא בן שני ליעקב לפי סדר הולדת הבנים, \u0003והוא\u0004 משה \u0003שלישי לבטן\u0004, שהוא משבט לוי שנולד שלישי ליעקב.","\u0003תפשה בבלוריתה\u0004 (ציצת שערותיה) \u0003והביאה אצל משה. אמר לו: בן עמרם, זו אסורה או מותרת? ואם תאמר\u0004 שהיא \u0003אסורה,\u0004 אם כן \u0003בת יתרו\u0004 שאתה נשוי לה \u0003מי התירה לך?\u0004 אף שכמובן כשנשא משה את בת יתרו היו שניהם בני נח — ומותרים זה לזה. \u0003נתעלמה ממנו\u0004 ממשה \u0003הלכה\u0004 מה לעשות בבא על הגויה. \u0003געו כולם,\u0004 כל אנשי הסנהדרין, \u0003בבכיה, והיינו דכתיב\u0004 \u0005[וזהו שנאמר\u0006\u0005]:\u0006 \u0003\"והמה בכים פתח אהל מועד\"\u0004 (שם ו). \u0003וכתיב\u0004 \u0005[ונאמר\u0006\u0005]\u0006 אחר כך: \u0003\"וירא פנחס בן אלעזר\u0004 בן אהרן הכהן ויקם מתוך העדה ויקח רומח בידו","\u0003\"\u0004(שם ז). ושואלים: \u0003מה ראה\u0004 פינחס שקם ועשה מעשה? \u0003אמר רב: ראה מעשה ונזכר הלכה, אמר לו\u0004 למשה: \u0003אחי אבי אבא\u0004 (שהרי משה אחי אהרן סבו), וכי \u0003לא כך לימדתני ברדתך מהר סיני: הבועל את הגויה קנאין פוגעין בו?! אמר לו\u0004 משה: \u0003קריינא דאיגרתא איהו ליהוי פרוונקא\u0004 \u0005[\u0006זה ש\u0005קורא את האגרת, הוא שיהיה השליח\u0006 לביצוע\u0005],\u0006 לך ועשה כן.","\u0003ושמואל אמר: ראה\u0004 פנחס וחשב על הרעיון האמור בכתוב \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה'\"\u0004 (משלי כא, ל), שדרשוהו חכמים: \u0003כל מקום שיש חילול השם אין חולקין כבוד לרב,\u0004 ואין חייבים להמלך בדעתו, אלא הולכים ומתקנים המעוות מיד, ואשר על כן \"ויקח רומח\", שעשה מיד מעשה. \u0003ר' יצחק אמר\u0004 בשם \u0003ר' אליעזר: ראה שבא מלאך והשחית בעם\u0004 כעונש על חטא זמרי, והבין שיש לתקן הדבר שלא יגבר הנגף.","נאמר בפנחס: \u0003\"ויקם מתוך העדה ויקח רמח בידו\"\u0004 (במדבר כה, ז) — \u0003מיכן,\u0004 ממה שנאמר שאת הרומח לקח אחר שיצא מתוך העדה, למדנו \u0003שאין נכנסין בכלי זיין לבית המדרש\u0004 (העדה — מושב הסנהדרין). \u0003שלף\u0004 פנחס \u0003שננה\u0004 (הוציא את חוד הרומח), \u0003והניחה באונקלו\u0004 (בבגדו) ונראה הרומח כמקל בלבד, \u0003והיה\u0004"],["\u0003נשען והולך על מקלו\u0004 על עץ הרומח. \u0003וכיון שהגיע אצל שבטו של שמעון, אמר: היכן מצינו\u0004 (מצאנו) \u0003ששבטו של לוי גדול\u0004 (חשוב) \u0003משל שמעון?\u0004 אם כל בני שבטכם עושים כן שמפקירים עצמם אחר בנות מואב, גם לי מותר. מששמעו דבריו \u0003אמרו: הניחו לו\u0004 להכנס, \u0003אף הוא\u0004 כמותנו ו\u0003לעשות צרכיו\u0004 (לתשמיש) \u0003נכנס.\u0004 ושמחו ואמרו: \u0003התירו פרושין\u0004 (חסידים ויראים, שפנחס מנוי עמהם) \u0003את הדבר.\u0004","\u0003אמר ר' יוחנן: ששה נסים נעשו לו לפנחס\u0004 בהריגתו של זמרי: \u0003אחד\u0004 — \u0003שהיה לו לזמרי לפרוש\u0004 מכזבי, ושוב אסור להרגו, \u0003ולא פירש. ואחד\u0004 — \u0003שהיה לו לדבר\u0004 ולצעוק ולבקש עזרה מבני שבטו, \u0003ולא דבר. ואחד\u0004 — \u0003שכוון\u0004 פנחס את הרומח בדיוק \u0003בזכרותו של איש ובנקבותה של אשה,\u0004 שיהא ניכר לכל על מה נהרגו. \u0003ואחד\u0004 — \u0003שלא נשמטו\u0004 שניהם \u0003מן הרומח. ואחד\u0004 — \u0003שבא מלאך והגביה את המשקוף\u0004 של אותה קובה שלא ישמטו, \u0003ואחד\u0004 — \u0003שבא מלאך והשחית בעם\u0004 והיו הכל מבוהלים ולא עצרו את פנחס.","\u0003בא\u0004 פנחס \u0003וחבטן לפני המקום, אמר לפניו: רבונו של עולם!\u0004 וכי \u0003על אלו יפלו עשרים וארבעה אלף מישראל? ש\u0004הלא \u0003נאמר \"ויהיו המתים במגפה ארבעה ועשרים אלף\"\u0004 (במדבר כה, ט). \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר\u0006\u0005]:\u0006 \u0003\"ויעמד פינחס ויפלל\u0004 ותעצר המגפה","\u0003\"\u0004(תהלים קו, ל). \u0003אמר ר' אלעזר:\u0004 לשון \u0003\"ויתפלל\" לא נאמר, אלא \"ויפלל\"\u0004 — \u0003מלמד כביכול שעשה\u0004 פנחס \u0003פלילות\u0004 (משפט) \u0003עם קונו. בקשו מלאכי השרת לדחפו\u0004 על שהוא אומר דברים קשים כלפי מעלה. \u0003אמר להן\u0004 הקדוש ברוך הוא: \u0003הניחו לו, קנאי בן קנאי הוא,\u0004 משבט לוי שקנא לכבוד דינה, \u0003משיב חימה בן משיב חימה הוא\u0004 מזרע אהרן שהשיב חמה במעשה קרח, יפה עשה.","\u0003התחילו שבטים מבזין אותו\u0004 את פנחס: \u0003ראיתם בן פוטי זה\u0004 (שאמו היתה מ\"בנות פוטיאל\"), ודרשו: \u0003שפיטם אבי אמו\u0004 (שלפי מסורת אחת הוא יתרו) \u0003עגלים לעבודה זרה,\u0004 ואיש זה העיז פנים \u0003והרג\u0004 שלא במשפט \u0003נשיא שבט מישראל!\u0004 ובתשובה לטענה זו \u0003בא הכתוב ויחסו \"פינחס בן אלעזר בן אהרן הכהן\"\u0004 (במדבר כה, יא), שדווקא בשל ייחוסו זה עשה מה שעשה.","\u0003אמר לו הקדוש ברוך הוא למשה: הקדם לו שלום\u0004 לפנחס, כדי לכבדו בפני הכל, \u0003שנאמר: \"לכן אמר הנני נתן לו את בריתי שלום\"\u0004 (שם יב), ונאמר: \"והיתה לו ולזרעו אחריו ברית כהונת עולם תחת אשר קינא לאלהיו ויכפר על בני ישראל\", \u0003וראויה כפרה זו\u0004 שכיפר במעשהו \u0003שתהא מכפרת והולכת לעולם.\u0004","באותו ענין עצמו דרשו עוד, \u0003אמר רב נחמן אמר רב:\u0004 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"זרזיר מתנים או תיש ומלך אלקום עמו\"\u0004 (משלי ל, לא) — \u0003ארבע מאות ועשרים וארבע בעילות\u0004 (כמנין \"זרזיר\") \u0003בעל אותו רשע\u0004 זמרי \u0003אותו היום, והמתין לו פנחס עד שתשש כחו\u0004 מרוב ביאות. \u0003והוא אינו יודע\u0004 שאינו צריך להמתין כל כך משום \u0003שמלך אלקום\u0004 (כינוי לקדוש ברוך הוא: מלך שאין לעמוד בפניו) \u0003עמו.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנינו\u0006\u0005]:\u0006 \u0003ששים\u0004 בעילות בעל, \u0003עד שנעשה\u0004 זמרי \u0003כביצה המוזרת,\u0004 שכל תוכנה נראה כמשקה דלוח ואחיד, \u0003והיא\u0004 (כזבי) \u0003היתה\u0004 מרוב הבעילות \u0003כערוגה מליאה מים. אמר רב כהנא\u0004 להדגיש בדרך הפרזה את גנותה וזנותה: \u0003ומושבה\u0004 (מקום מושבה) \u0003בית סאה,\u0004 כל כך רחבה היתה. \u0003תני רב יוסף: קבר\u0004 (פתח הרחם) \u0003שלה\u0004 — \u0003אמה\u0004 היה.","\u0003אמר רב ששת: לא \"כזבי\" שמה, אלא \"שוילנאי בת צור\" שמה, ולמה נקרא שמה \"כזבי\"\u0004 — \u0003שכזבה באביה,\u0004 שהרי אמר לה שלא תיבעל אלא לגדול שבהם והיא נבעלה לנשיא שבט. \u0003דבר אחר: \"כזבי\"\u0004 — \u0003שאמרה לאביה\u0004 \u0003כוס\u0004 \u0005[שחט\u0006\u0005]\u0006 \u0003בי עם זה\u0004 על ידי שתסיתם לזנות.","\u0003ו\u0004כיון שהיה שמה \"שוילנאי\" הרי זה מסביר \u0003היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006\u0005]\u0006 כשמדברים על זונה מפורסמת: \u0003בין קני לאורבני\u0004 \u0005[הקנים לערבות]\u0006 \u0003שוילנאי מאי בעיא\u0004 \u0005[מה רוצה\u0006\u0005],\u0006 ודאי לזנות באה. או פתגם אחר: \u0003בהדי קלפי דקני\u0004 \u0005[עם קליפות הקנים]\u0006 \u0003שוילנאי מאי בעיא\u0004 \u0005[מה רוצה]?\u0006 ודאי לזנות הלכה, \u0003גפתה\u0004 \u0005[זינתה]\u0006 את \u0003אמה\u0004 שהכל קוראים לה \"זונה בת זונה\". ולפי דרכנו למדנו שנעשה שם זה לתואר כולל לזונה.","\u0003אמר ר' יוחנן: חמשה שמות יש לו,\u0004 והם: \u0003\"זמרי\", ו\"בן סלוא\", ו\"שאול\", ו\"בן הכנענית\", ו\"שלומיאל בן צורי שדי\". \"זמרי\"\u0004 נקרא — \u0003על שנעשה כביצה המוזרת\u0004 מרוב בעילה. \u0003\"בן סלוא\"\u0004 — \u0003על שהסליא\u0004 (הזכיר) \u0003עונות של משפחתו. \"שאול\"\u0004 — \u0003על שהשאיל עצמו לדבר עבירה. \"בן הכנענית\"\u0004 — \u0003על שעשה מעשה כנען\u0004 המפורסמים בגנותם בנושא זה. \u0003ומה שמו\u0004 האמיתי — \u0003שלומיאל בן צורי שדי שמו,\u0004 שהוא היה נשיא שבט שמעון כמבואר בתורה (במדבר א, ב).","שנינו במשנה ש\u0003כהן ששימש בטומאה\u0004 — פרחי כהונה הורגים אותו. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אחא בר הונא מרב ששת: כהן ששימש בטומאה,\u0004 האם הוא \u0003חייב מיתה בידי שמים, או אין חייב מיתה בידי שמים?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 כבר \u0003תניתוה\u0004 \u0005[שניתם אותה],\u0006 כלומר, מהדברים השגורים בפי הכל יש פתרון לשאלה זו, שכן שנינו: \u0003כהן ששימש בטומאה אין אחיו הכהנים מביאין אותו לבית דין, אלא פירחי כהונה מוציאין אותו חוץ לעזרה ופוצעין את מוחו בגיזרין. ואי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006\u0005]\u0006 לומר כי \u0003מחייב\u0004 \u0005[חייב\u0006\u0005]\u0006 מיתה \u0003בידי שמים, לישבקיה דליקטול\u0004 \u0005[שיניחוהו שייהרג]\u0006 \u0003בידי שמים!\u0004 ואם כן, הרי מכאן ראיה שאינו חייב מיתה. דחה זאת רב אחא בר הונא: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה — ש\u0003אינו חייב\u0004 מיתה בידי שמים,","\u0003מי איכא מידי דרחמנא פטריה ואנן ניקום וניקטול ליה\u0004 \u0005[האם יש דבר שהתורה פטרה אותו\u0006 מעונש מוות כלשהו, \u0005ואנחנו נעמוד ונהרוג אותו\u0006\u0005]?\u0006 אמר לו רב ששת: \u0003ולא,\u0004 וכי לא מצינו דבר כגון זה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה \u0005]:\u0006 \u0003מי ש\u0004עבר עבירה ו\u0003לקה\u0004 על ידי בית דין \u0003ושנה\u0004 בעבירה — \u0003בית דין מכניסין אותו לכיפה,\u0004 והרי אף שם יכול אתה לומר: \u0003רחמנא פטריה ואנן קטלינן ליה\u0004 \u0005[התורה פטרה אותו ואנחנו הורגים אותו\u0006\u0005]!\u0006 ודוחים: \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 \u0003ר' ירמיה אמר ריש לקיש: במלקות של\u0004 עבירות שהעובר אותן חייב \u0003כריתות עסקינן\u0004 \u0005[עוסקים אנו\u0006\u0005],\u0006 \u0003דגברא בר קטלא\u0004 \u0005[שהאיש\u0006 העובר \u0005בן מוות]\u0006 \u0003הוא\u0004 לשמים.","אמר לו: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003גונב הקסוה\u0004 שנידון בידי אדם בלא עונש שמים, ואמרנו שקנאים פוגעים בו! ענה לו: \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 כבר \u0003רב יהודה: ב\u0004גונב \u0003כלי שרת עסקינן\u0004 \u0005[עוסקים אנו\u0006\u0005],\u0006 \u0003ורמיזא\u0004 \u0005[ונרמז\u0006 הדבר\u0005]\u0006 \u0003\"\u0004ו\u0003לא יבאו לראות כבלע את הקדש ומתו\"\u0004 (במדבר ד, כ).","הקשה לו: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003המקלל את הקוסם\u0004 שאינו חייב מן התורה, וקנאים פוגעים בו! ענה לו: \u0003הא תני\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003רב יוסף\u0004 שפירושו הוא שאומר: \u0003יכה קוסם את קוסמו, דמיחזי\u0004 \u0005[שנראה\u0006\u0005]\u0006 \u0003כמברך\u0004 (מקלל, בלשון נקיה) \u0003את השם,\u0004 וחייב מיתה על חילול השם.","הקשה לו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בועל ארמאית,\u0004 שלא נאמר בו עונש מיתה בתורה, וקנאים פוגעים בו! ענה לו: \u0003הא אקריוה\u0004 \u0005[הקריאו]\u0006 \u0003לרב כהנא בחלמיה\u0004 \u0005[בחלומו],\u0006 \u0003ואדכריה\u0004 \u0005[נזכר]\u0006 בשל כך \u0003רב לגמריה\u0004 \u0005[את תלמודו]\u0006 שהבא על הגויה נאמר בו עונש כרת.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 ממה ששנינו: כהן \u0003היוצק\u0004 שמן במנחה, \u0003והבולל\u0004 אותה, \u0003והפותת\u0004 את המנחה האפויה לפתים, כדרך שעושים במקדש, \u0003המולח, המניף\u0004 אותה כלפי המזבח, \u0003המגיש\u0004 אותה למזבח, \u0003והמסדר את השולחן\u0004 של לחם הפנים, ו\u0003המטיב\u0004 (מנקה ומסדר) \u0003את הנרות\u0004 של המנורה, \u0003והקומץ\u0004 את המנחה, \u0003והמקבל דמים\u0004 של אחד הקרבנות, אם עשה אחת מהעבודות הללו חוץ למקדש, אף על פי שיש איסורים חמורים מאוד בעושה עבודת הקודש מ\u0003חוץ\u0004 למקדש — \u0003פטור\u0004 מכרת.","\u0003ואין חייבין עליהן\u0004"],["\u0003לא משום זרות\u0004 שזר (שאינו כהן) שעשה אחת העבודות האלה במקדש — אינו חייב מיתה, \u0003ולא משום טומאה,\u0004 אם עשה אותן כהן טמא, \u0003ולא משום מחוסר בגדים,\u0004 אם הכהן לא לבש בגדי כהונה, \u0003ולא משום\u0004 שאינו \u0003רחוץ ידים ורגלים,\u0004 אם עבד הכהן בלא רחיצת ידים ורגלים. והטעם משום שעבודות אלה כולן אינן \"עבודה תמה\"־שלימה, שהיא עבודה גמורה הנעשית במקדש שכל אחת מן העבודות שנמנו עדיין זקוקה לעבודה אחרת להשלמתה, וכיון שכך אין עליהן שם עבודה גמורה להתחייב בהן.","ומלשון הברייתא נדייק: שנינו באלה שפטור עליהן, \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 אם היה \u0003מקטר\u0004 על המזבח, היה \u0003חייב!\u0004 ונברר \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]\u0006 של חייב זה? \u0003לאו\u0004 \u0005[האם לאו\u0006\u0005]\u0006 הכוונה שהוא חייב \u0003מיתה,\u0004 ואם כן הרי זו הוכחה שטמא ששימש — במיתה! ודוחים: \u0003לא,\u0004 הכוונה היא שחייב \u0003באזהרה,\u0004 שעבר על \"לא תעשה\".","ומקשים: \u0003אלא\u0004 לפי הסבר זה \u0003זר\u0004 אם היה מקטיר או עובד עבודה גמורה, שלא כאחת מאלה, האם גם כן תאמר כי הוא \u0003לאזהרה\u0004 בלבד ולא עוד? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"והזר הקרב יומת\"\u0004 (במדבר יח, ז)! ומשיבים: זו אינה קושיה, \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כמות שהיא וזו כמות שהיא\u0006\u0005],\u0006 שלגבי איסור זרות יש להבין את הפטור כפטור ממיתה, ולענין טומאה כפטור מאזהרה, וכל דבר לעצמו הוא נדון.","ועדיין מקשים: \u0003מכלל\u0004 הדברים ולפי הסבר זה שפטור, ומשמעו — פטור מכל, הרי ש\u0003יוצק ובולל\u0004 איסור \u0003\"לאו\"\u0004 \u0005[\"לא תעשה\"]\u0006 \u0003נמי לא\u0004 \u0005[גם כן אין\u0006 בו\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אזהרה ליוצק ובולל\u0004 בטומאה \u0003מניין\u0004 — \u0003תלמוד לומר: \"קדשים יהיו\u0004 לאלהיהם \u0003ולא יחללו\u0004 שם אלהיהם כי את אשי ה' לחם אלהיהם הם מקריבים\u0003\"\u0004 (ויקרא כא, ו)! ודוחים: משם אין ראיה, כי באמת אין \"לא תעשה\" על עבירה זו והאיסור הוא רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005],\u0006 \u0003וקרא\u0004 \u0005[והכתוב]\u0006 — \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד\u0006\u0005]\u0006 וזכרון הוא, אבל אינו מקור להלכה מן התורה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 עוד ממה ששנינו בתוספתא: \u0003ואלו הן ש\u0004עונשם \u0003במיתה\u0004 בידי שמים, וביניהם \u0003טמא ששימש,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006\u0005]\u0006 לדברי רב ששת, והוכחה שטמא ששימש חייב מיתה בידי שמים, ואין קנאים פוגעים אלא במי שנתחייב כבר בידי שמים.","כיון שהוזכרה ברייתא זו, מביאים אותה בשלימות, לדון ב\u0003גופא\u0004 \u0005[לגופו]\u0006 של אותו ענין: \u0003ואלו ש\u0004דנים אותם \u0003במיתה\u0004 בידי שמים: \u0003האוכל את הטבל\u0004 (תבואה שעדיין לא הופרשו ממנה תרומות ומעשרות); \u0003וכהן טמא שאכל תרומה טהורה; וזר שאכל את התרומה; וזר ששימש\u0004 במקדש; \u0003ו\u0004כהן \u0003טמא ששימש\u0004 במקדש; \u0003וטבול יום\u0004 שהוא כהן שנטמא; וטבל ועדיין לא שקעה השמש, שלא נגמרה טהרתו, \u0003ששימש\u0004 במקדש; \u0003ו\u0004כהן ששימש כשהוא \u0003מחוסר בגדים\u0004 (בגדי כהונה); \u0003ומחוסר כפרה,\u0004 כלומר, אחד מן הטמאים, כגון מצורע או זב הצריכים להביא את קרבנם לכפרתם לפני שהם נטהרים לגמרי, \u0003ו\u0004כהן \u0003שלא רחץ ידים ורגלים\u0004 לפני שהחל לשרת במקדש; \u0003ושתויי יין; ופרועי ראש\u0004 (ששערותיהם מגודלות יתר על השיעור הראוי).","\u0003אבל\u0004 כהן \u0003ערל,\u0004 או \u0003אונן\u0004 (אבל ביום הראשון של אבלו), \u0003ויושב,\u0004 כלומר, כהן שעשה עבודתו בישיבה ולא בעמידה, כראוי — \u0003אינן\u0004 חייבים \u0003במיתה,\u0004 ואינם \u0003אלא באזהרה\u0004 (\"לא תעשה\") בלבד. כהן \u0003בעל מום\u0004 שעבד עבודה, \u0003רבי אומר:\u0004 עונשו \u0003במיתה\u0004 בידי שמים, \u0003וחכמים אומרים:\u0004 אינו אלא \u0003באזהרה\u0004 בלבד.","\u0003הזיד\u0004 \u0003במעילה,\u0004 כלומר, שמעל ונהנה מן הקודש בזדון, שלא פורש דינו בתורה, שבה יש רק דין מועל בשגגה, \u0003רבי אומר:\u0004 עונשו \u0003במיתה, וחכמים אומרים:\u0004 אינו אלא \u0003באזהרה\u0004 בלבד. לאחר מנין כולל זה באים לפרט ולהוכיח את הפרטים.","שנינו שם ש\u0003האוכל את הטבל\u0004 חייב מיתה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 הלכה זו? ומשיבים: ש\u0003אמר שמואל משום\u0004 (בשם) \u0003ר' אליעזר: מניין לאוכל את הטבל שהוא במיתה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ולא יחללו את קדשי בני ישראל את אשר ירימו לה' \"\u0004(שם כב, טו), ולשון הכתוב בזמן עתיד \"אשר ירימו\" באה ללמד: \u0003בעתידים לתרום הכתוב מדבר,\u0004 אותם קדשים כתרומות ומעשרות שעדיין לא הופרשו ורק עתידים להתרם ולכן לפי שעה טבל הם,","\u0003ויליף\u0004 \u0005[ולמד\u0006\u0005]\u0006 את דינם בגזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מ\u0004מה שנאמר ב\u0003תרומה, מה להלן\u0004 בתרומה, נאמרה לשון \"חילול\" והאוכל תרומה חייב \u0003מיתה\u0004 — \u0003אף כאן\u0004 בטבל נאמרה לשון \"חילול\" והאוכל ממנו נידון \u0003במיתה.\u0004","ומקשים: \u0003ונילוף\u0004 \u0005[ושילמד\u0006\u0005]\u0006 בגזירה שווה אחרת לשון \u0003\"חילול\" \"חילול\" מ\u0004מה שנאמר ב\u0003נותר\u0004 (המותיר מן הקדשים) שגם שם יש לשון זו, ונאמר: \u0003מה להלן\u0004 בנותר עונשו \u0003בכרת, אף כאן\u0004 בטבל עונשו \u0003בכרת?!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003מ\u0004דין \u0003תרומה הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 כי יש צדדים רבים של דמיון ביניהם, \u0003שכן\u0004 טבל ומעשר קשורים ב\u0003תרומה,\u0004 מה שאין כן נותר, שכן שני הדברים אינם חלים ב\u0003חוצה לארץ,\u0004 שהרי הפרשת תרומת ומעשרות חובתה רק בארץ ישראל. וכן שניהם \u0003הותרה,\u0004 שיש דרך להתיר אכילת תרומה לטמא, באופן שיטבול הכהן, וכן להתיר טבל על ידי הפרשת מעשר, מה שאין כן בנותר. ונאמר ענין החילול בלשון \u0003רבים\u0004 (\"יחללוהו\") ולא ביחיד כבנותר. ושניהם חלים על \u0003פירות\u0004 (ולא על בשר כזבחים). ולעומת זאת אין בהם לא דין \u0003פיגול\u0004 ולא דין \u0003נותר.\u0004 הרי צדדים שווים מרובים.","ודוחים: \u0003אדרבה, מ\u0004דין \u0003נותר הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 \u0003שכן\u0004 יש בו צדדים משותפים אחרים: שניהם \u0003פסול\u0004 אוכלים, ששניהם דברי מאכל הפסולים מצד עצמם, מה שאין כן בתרומה שפסולה אינו בה אלא באדם האוכלה. ושניהם דבר ש\u0003אין לו היתר במקוה,\u0004 שלטומאת הכהן יש טהרה במקוה, אבל לפסול נותר וטבל, אין היתר במקוה! ומשיבים: \u0003הנך נפישן\u0004 \u0005[ההם\u0006 צדדי הדמיון לתרומה \u0005מרובים\u0006\u0005],\u0006 ועליהם יש לסמוך. \u0003רבינא אמר:\u0004 אין צורך בנימוק זה, אבל לשון \u0003\"חילול\"\u0004 האמורה בלשון \u0003רבים מ\u0004לשון \u0003\"חילול\"\u0004 האמורה בלשון \u0003רבים עדיף\u0004 ללמוד.","ועוד מבררים: \u0003וכהן טמא שאכל תרומה טהורה מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שדינו במיתה? — ש\u0003אמר שמואל: מניין לכהן טמא שאכל תרומה טהורה\u0004 שעונשו \u0003במיתה בידי שמים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בענין כהן האוכל בקדשים: \u0003\"ושמרו את משמרתי ולא ישאו עליו חטא\u0004 ומתו בו כי יחללוהו אני ה' מקדשם","\u0003\"\u0004(שם כג), ומכאן גם נדקדק: תרומה \u0003טהורה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייבים עליה, אבל תרומה \u0003טמאה\u0004 — \u0003לא.\u0004 וכעין זה \u0003אמר שמואל אמר ר' אליעזר: מניין לכהן טמא שאכל תרומה טמאה שאינו\u0004 נידון בשל כך \u0003במיתה?\u0004 — \u0003שנאמר: \"ומתו בו כי יחללהו\",\u0004"],["\u0003פרט לזו שמחוללת ועומדת\u0004 על ידי טומאתה.","\u0003ו\u0004ממשיכים בבירור דברי הברייתא. שנינו בה ש\u0003זר שאכל את התרומה\u0004 עונשו במיתה בידי שמים. \u0003אמר רב: זר שאכל את התרומה\u0004 — \u0003לוקה, אמרי ליה\u0004 \u0005[אמרו לו\u0006\u0005]\u0006 \u0003רב כהנא ורב אסי לרב: לימא מר\u0004 \u0005[ושיאמר אדוני\u0006\u0005]\u0006 שעונשו \u0003במיתה,\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"ושמרו את משמרתי ולא ישאו עליו חטא ומתו בו כי יחללוהו אני ה' מקדשם. \u0003וכל זר לא יאכל קדש\u0004 תושב כהן ושכיר לא יאכל קודש\" (ויקרא כב, ט–י), ונלמד מסמיכות הפסוקים כי גם דינו של זר שאכל קודש במיתה כדין הכהן הטמא שאכל קודש.","ענה להם רב: במה שנאמר באמצע הדברים \u0003\"אני ה' מקדשם\" הפסיק הענין\u0004 בין נושא לנושא ואין ללמוד מן הסמיכות. \u0003מיתיבי\u0004 \u0005[מקשים\u0006\u0005]\u0006 על רב ממה ששנינו בברייתא, \u0003ואלו הן שבמיתה\u0004 ובכללם גם \u0003זר האוכל את התרומה,\u0004 והרי מפורש שדינו של זר שאכל קודש במיתה! ודוחים: \u0003מתניתא\u0004 \u0005[מהברייתא]\u0006 ל\u0003רב קא רמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005]?!\u0006 \u0003רב\u0004 עצמו \u0003תנא\u0004 מן התנאים \u0003הוא ופליג\u0004 \u0005[ו\u0006הוא \u0005חולק\u0006\u0005]\u0006 על הברייתא.","\u0003ו\u0004עוד שנינו בברייתא כי \u0003זר ששימש\u0004 במקדש עונשו במיתה בידי שמים. והמקור להלכה זו הוא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ואתה ובניך אתך תשמרו את כהונתכם לכל דבר המזבח... \u0003והזר הקרב יומת\"\u0004 (במדבר יח, ז).","עוד שנינו בברייתא כי \u0003טמא ששימש\u0004 עונשו במיתה בידי שמים. ולשאלה, מנין לנו דבר זה מסבירים: \u0003כדבעא מיניה\u0004 \u0005[כמו ששאל ממנו\u0006\u0005]\u0006 \u0003רב חייא בר אבין מרב יוסף: מניין לטמא ששימש שהוא במיתה?\u0004 ענה לו \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 בכתובים המזהירים את הכהנים מן הטומאה: \u0003\"דבר אל אהרן ואל בניו וינזרו מקדשי בני ישראל ולא יחללו את שם קדשי\u0004 אשר הם מקדשים לי אני ה'","\u0003\"\u0004(ויקרא כב, ב), \u0003ויליף\u0004 \u0005[ולמד\u0006\u0005]\u0006 בגזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מתרומה, מה להלן\u0004 בתרומה אם אוכלה בטומאה דינו \u0003במיתה, אף כאן\u0004 — דינו \u0003במיתה.\u0004","ומקשים: \u0003ונילף\u0004 \u0005[ושנלמד\u0006\u0005]\u0006 \u0003\"חילול\" \"חילול\" מ\u0004דין \u0003נותר\u0004 שאף בו נאמרה לשון \"חילול\", ונאמר: \u0003מה להלן\u0004 בנותר חייב \u0003כרת, אף כאן\u0004 — \u0003כרת!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר \u0003כי\u0004 \u0003מ\u0004דין \u0003תרומה הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 \u0003שכן\u0004 שניהם מדברים בדבר שהוא פגם ב\u0003גוף\u0004 האדם ולא במאכל, ושניהם \u0003טמא,\u0004 כלומר, בפסולי טומאה, ולשניהם יש תקנה ב\u0003מקוה\u0004 שיטבול הטמא, ובשניהם נאמרה לשון החילול \u0003ב\u0004לשון \u0003רבים\u0004 שלא כבענין נותר.","ומקשים: \u0003אדרבה\u0004 (להיפך) \u0003מ\u0004דין \u0003נותר הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 \u0003שכן\u0004 שניהם בענייני קרבנות שהם \u0003קדש,\u0004 מה שאין כן בתרומה, ושניהם שייכים ל\u0003פנים\u0004 המקדש, ובשניהם יש דין \u0003פיגול\u0004 (פסילה הבאה על ידי מחשבה אסורה שרוצה לעשות אחת מעבודות הקודש בזמן בלתי ראוי), \u0003ו\u0004בשניהם יש דין \u0003נותר!\u0004 ומשיבים: אף שמספר צדדי השוויון שווה, אך מכל מקום לשון \u0003\"חילול\"\u0004 האמורה בלשון \u0003רבים מ\u0004לשון \u0003\"חילול\"\u0004 האמורה בלשון \u0003רבים עדיף\u0004 ללמוד. שראוי ללמוד ממקום שבו לשון הכתובים שווה יותר.","עוד שנינו בברייתא כי \u0003טבול יום ששימש\u0004 במקדש, ולא העריב שמשו עונשו במיתה בידי שמים. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 דין זה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' סימאי אומר:\u0004 \u0003רמז\u0004 בתורה \u0003לטבול יום שאם עבד\u0004 במקדש \u0003חילל\u0004 עבודתו, \u0003מניין?\u0004 — \u0003תלמוד לומר: \"קדשים יהיו לאלהיהם ולא יחללו\u0004 שם אלהיהם","\u0003\"\u0004(ויקרא כא, ו), \u0003אם אינו ענין לטמא ששימש\u0004 שדבר זה אינו צריך שילמדוהו מכאן, \u0003דנפקא לן\u0004 \u0005[ש\u0006הרי \u0005יצא לנו\u0006\u0005]\u0006 דין זה מן הכתוב שהבאנו כבר \u0003מ\"וינזרו\", תניהו ענין לטבול יום ששימש,\u0004 שאף שאין בו טומאה גמורה, מכל מקום עדיין טמא הוא.","\u0003ויליף\u0004 \u0005[ולמד\u0006\u0005]\u0006 בגזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מתרומה, מה להלן\u0004 בתרומה האוכל בטומאה דינו \u0003במיתה, אף כאן\u0004 — דינו \u0003במיתה.\u0004","עוד שנינו בברייתא בין אלה החייבים מיתה בידי שמים גם את ה\u0003מחוסר בגדים\u0004 ששימש במקדש. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שזהו ענשו? \u0003אמר ר' אבהו אמר ר' יוחנן, ומטו\u0004 \u0005[והגיעו]\u0006 \u0003בה,\u0004 כלומר, היו שהמשיכו את שלשלת מסירת הלכה זו עד \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעזר בר' שמעון:\u0004 נאמר \u0003\"וחגרת אתם אבנט\u0004 אהרן ובניו וחבשת להם מגבעות והיתה להם כהונה לחוקת עולם","\u0003\"\u0004(שמות כט, ט), ונלמד מכאן: \u0003בזמן שבגדיהם עליהם\u0004 — \u0003כהונתם עליהם,\u0004 אך אם \u0003אין בגדיהם עליהם\u0004 — \u0003אין כהונתם עליהם. ו\u0004כיון שכך \u0003הוו להו\u0004 \u0005[נעשו\u0006\u0005]\u0006 בלא בגדיהם כ\u0003זרים, ו\u0004כבר \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]:\u0006 \u0003זר ששימש\u0004 — עונשו \u0003מיתה.\u0004","עוד שנינו בברייתא בין אלה החייבים מיתה בידי שמים גם את \u0003מחוסר כפרה\u0004 ששימש במקדש. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שזהו עונשו? \u0003אמר רב הונא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין היולדת, שחייבת להביא קרבן כפרה \u0003\"וכפר עליה הכהן וטהרה\"\u0004 (ויקרא יב, ח), ומן הלשון \u0003\"טהרה\"\u0004 נלמד: \u0003מכלל\u0004 \u0005[מכאן]\u0006 \u0003שהיא\u0004 \u0003טמאה\u0004 במדה מסויימת עד שהיא מביאה קרבן. \u0003ו\u0004כבר \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003טמא ששימש\u0004 — דינו \u0003במיתה.\u0004","\u0003ו\u0004ממשיכים ומבררים את מה ששנינו בברייתא שזה \u0003שלא רחוץ ידים ורגלים\u0004 ועבד במקדש עונשו במיתה בידי שמים. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 דבר זה? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]\u0006 במפורש: \u0003\"בבאם אל אהל מועד ירחצו מים ולא ימותו\"\u0004 (שמות ל, כ).","\u0003ו\u0004עוד שנינו בברייתא ש\u0003שתויי יין\u0004 שעבדו במקדש עונשם מיתה בידי שמים. ולשאלה מנין לנו דבר זה, מסבירים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]\u0006 במפורש: \u0003\"יין ושכר אל תשת\u0004 אתה ובנך אתך בבואכם אל אהל מועד ולא תמותו","\u0003\"\u0004(ויקרא י, ט). \u0003ופרועי ראש\u0004 ששנינו בברייתא שאף הם אם עבדו במקדש עונשם מיתה בידי שמים, מנין שזהו דינם? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]\u0006 בכהנים: \u0003\"וראשם לא יגלחו ופרע לא ישלחו\"\u0004 (יחזקאל מד, כ), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו\u0006\u0005]:\u0006 \u0003\"ויין לא ישתו\u0004 כל כהן בבואם אל החצר הפנימית\u0003\"\u0004 (שם כא) — \u0003איתקש\u0004 \u0005[הושווה\u0006\u0005]\u0006 בכתוב מעמדו של \u0003פרוע ראש לשתויי יין, מה שתויי יין\u0004 יודעים מן התורה שהם \u0003במיתה, אף פרועי ראש\u0004 דינם \u0003במיתה.\u0004","עוד שנינו בברייתא: \u0003אבל\u0004 כהן \u0003ערל,\u0004 או \u0003אונן,\u0004 או \u0003יושב\u0004 בשעת עבודה — כל אלה אינם במיתה אלא \u0003באזהרה,\u0004 ב\"לא תעשה\", ועונשם מלקות. ושואלים: \u0003ערל מנלן\u0004 \u0005[מנין לנו]\u0006 שאסור לו לעבוד במקדש? \u0003אמר רב חסדא: דבר זה מתורת משה רבינו לא למדנו, עד שבא יחזקאל בן בוזי\u0004 הנביא \u0003ולמדנו,\u0004 שנאמר: \u0003\"כל בן נכר ערל לב\u0004"],["\u0003וערל בשר לא יבוא אל מקדשי\"\u0004 (יחזקאל מד, ט), הרי איסור \"לא תעשה\" מפורש בו.","ומוסיפים לשאול: \u0003אונן מנלן\u0004 \u0005[מנין לנו]\u0006 שאסור לו לעבוד במקדש? — \u0003דכתיב\u0004 \u0005[שנאמר\u0006\u0005]\u0006 בכהן הגדול שמתו אביו ואמו: \u0003\"ומן המקדש לא יצא ולא יחלל את מקדש אלהיו\"\u0004 (ויקרא כא, יב), \u0003הא\u0004 \u0005[הרי]\u0006 משמע מכאן כי \u0003אחר,\u0004 לא כהן גדול אלא כהן הדיוט, \u0003שלא יצא\u0004 והמשיך לעבוד עבודה במקדש — \u0003חילל\u0004 את העבודה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא לרבא: ונילף\u0004 \u0005[נלמד\u0006\u0005]\u0006 בגזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מ\u0004דין \u0003תרומה, מה להלן\u0004 בתרומה נאמרה לשון \"חילול\" והמחלל דינו \u0003במיתה, אף כאן\u0004 דינו \u0003במיתה!\u0004","","ומשיבים: \u0003מי כתיב ביה בגופיה\u0004 \u0005[האם\u0006 לשון \"חילול\" \u0005כתובה בו\u0006 באונן באותו ענין \u0005בגופו]?!\u0006 והלא רק \u0003מכללא קאתי\u0004 \u0005[מכלל\u0006 הדברים \u0005הוא בא\u0006\u0005],\u0006 שלמדנו מכלל האמור בכהן גדול דין אחר בהדיוט, \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003דבר הבא מן הכלל,\u0004 שהרי לא נאמר במפורש, \u0003ו\u0004אנחנו יודעים כי \u0003כל דבר הבא מן הכלל אין דנין אותו בגזרה שוה,\u0004 שאין למדים גזירה שווה אלא כשהדבר נאמר במפורש.","ועוד שואלים: \u0003יושב\u0004 בשעת עבודה \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שאסור? \u0003אמר רבא אמר רב נחמן, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי בו בחר ה' אלהיך מכל שבטיך לעמד לשרת\u0004 בשם ה'\u0003\"\u0004 (דברים יח, ה), משמע כי לשירות של \u0003עמידה בחרתיו ולא ל\u0004שירות ב\u0003ישיבה.\u0004","עוד שנינו בברייתא שכהן \u0003בעל מום\u0004 ששימש במקדש, \u0003רבי אומר\u0004 שעונשו \u0003במיתה, וחכמים אומרים\u0004 שאינו אלא \u0003באזהרה\u0004 בלבד. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אך אל הפרכת לא יבא\u0004 ואל המזבח לא יגש כי מום בו ולא יחלל את מקדשי\u0003\"\u0004 (ויקרא כא, כג), \u0003ויליף\u0004 \u0005[ולמד]\u0006 בגזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מ\u0004דין \u0003תרומה, מה להלן\u0004 בתרומה נאמרה לשון \"חילול\" ועונשו \u0003במיתה, אף\u0004 \"חילול\" האמור \u0003כאן\u0004 עונשו \u0003במיתה.\u0004","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד\u0006\u0005]\u0006 גזירה שווה מהמילים \u0003\"חילול\" \"חילול\" מ\u0004דין \u0003נותר,\u0004 שאף בו נאמרה לשון \"חילול\", ונאמר: \u0003מה להלן\u0004 בנותר עונשו \u0003בכרת, אף כאן\u0004 עונשו \u0003בכרת!\u0004","ודוחים: בכל זאת \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003מ\u0004דין \u0003תרומה הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 \u0003שכן\u0004 בשניהם יש צד דומה; \u0003פסול הגוף\u0004 של בעל המום, \u0003מפסול הגוף\u0004 של הטמא בתרומה. ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003מ\u0004דין \u0003נותר הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש בהם צדדי דמיון מרובים: שניהם \u0003קודש\u0004 ולא כתרומה שיש לה דין אחר, ושניהם חייבים ל\u0003פנים\u0004 המקדש, ובשניהם יש דין \u0003פיגול, ונותר!\u0004","\u0003אלא\u0004 חוזרים אנו מן השוואה לתרומה ואומרים כי לא מכאן, אלא \u0003מ\u0004דין \u0003טמא ששימש\u0004 בקודש \u0003גמר\u0004 \u0005[למד\u0006\u0005]\u0006 בגזירה שווה של המילים \"חילול\" \"חילול\", ויש להם צדדים שווים, שכן למדים \u0003פסול הגוף\u0004 שבבעל מום \u0003מפסול הגוף\u0004 של טמא, וכן \u0003קודש, פנים, פיגול, ונותר\u0004 שיש בבעל מום ששימש \u0003מקודש, פנים, פיגול, ונותר\u0004 שבטמא ששימש.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 מה טעמם? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ומתו בו כי יחללוהו\" (שם כב, ט) ובהדגשה \u0003\"בו\"\u0004 — \u0003ולא בבעל מום.\u0004","עוד נחלקו תנאים בברייתא בענין זה ש\u0003הזיד במעילה,\u0004 שלקח לצרכו מההקדש, ש\u0003רבי אומר\u0004 שדינו \u0003במיתה, וחכמים אומרים\u0004 שאינו אלא \u0003באזהרה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 של \u0003רבי? אמר ר' אבהו גמר\u0004 \u0005[למד\u0006\u0005]\u0006 בגזירה שווה מהמילים \u0003\"חטא\" \"חטא\" מ\u0004דין \u0003תרומה, מה להלן\u0004 בתרומה נאמרה בו לשון \"חטא\" ועונשו \u0003במיתה\u0004 — \u0003אף כאן\u0004 עונשו \u0003במיתה.\u0004","\u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים\u0006\u0005]:\u0006 \u0003אמר קרא\u0004 בדין תרומה \u0003\"בו\",\u0004 להדגיש: \u0003\"בו\"\u0004 יש עונש מוות \u0003ולא במעילה.\u0004","מעתה חוזרים לדון במחלוקת חכמים בדין \u0003זר ששימש במקדש. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר, נאמר כאן: \"\u0004ואתה ובניך אתך תשמרו את כהונתכם לכל דבר המזבח... \u0003והזר הקרב יומת\"\u0004 (במדבר יח, ז), \u0003ונאמר להלן: \"כל הקרב הקרב אל משכן ה' ימות\"\u0004 (שם יז, כח), \u0003מה להלן\u0004 שנאמר \"הזר הקרב יומת\" הכוונה \u0003בידי שמים, אף כאן\u0004 בזר ששימש הכוונה שיומת \u0003בידי שמים.\u0004 \u0003ר' עקיבא אומר, נאמר כאן: \"והזר הקרב יומת\", ונאמר להלן: \"והנביא ההוא או חלם החלום ההוא יומת\"\u0004 (דברים יג, ו), \u0003מה להלן\u0004 בנביא שהדיח לעבודה זרה מיתתו \u0003בסקילה, אף כאן\u0004 מיתתו \u0003בסקילה. ר' יוחנן בן נורי אומר: מה להלן\u0004 בנביא שהדיח לעבודה זרה מיתתו \u0003בחנק\u0004 — \u0003אף כאן\u0004 מיתתו \u0003בחנק.\u0004","","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו\u0006\u0005]\u0006 \u0003ר' ישמעאל ור' עקיבא?\u0004 ומשיבים: \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003דנין \"יומת\" מ\"יומת\", ואין דנין \"יומת\" מ\"ימות\". ו\u0004אילו \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 כי אף שיש הבדל מסויים בין המילים, מכל מקום \u0003דנין הדיוט מהדיוט,\u0004 שבשניהם מדובר בזר (הדיוט) המתקרב לקודש \u0003ואין דנין הדיוט מנביא. ור' עקיבא\u0004 משיב על כך: \u0003כיון ש\u0004נביא זה \u0003הדיח\u0004 לעבודה זרה — \u0003אין לך הדיוט גדול מזה.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו\u0006\u0005]\u0006 \u0003ר' עקיבא ור' יוחנן בן נורי?\u0004 ומשיבים: \u0003בפלוגתא\u0004 \u0005[במחלוקתם\u0006\u0005]\u0006 של \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 בענין נביא שהדיח, נחלקו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נביא שהדיח\u0004 לעבודה זרה — דינו \u0003בסקילה. ר' שמעון אומר: בחנק.\u0004 ומקשים: \u0003הא אנן תנן\u0004 \u0005[הרי אנו שנינו\u0006 במשנה\u0005]\u0006 במפורש בענין נביא שהדיח ש\u0003ר' עקיבא אומר\u0004 שדינו \u0003בחנק,\u0004 ואם כן כל מה שאמרנו בדימוי דין זר ששימש לנביא — אין בו ממש!","","ודוחים: \u0003תרי תנאי ואליבא\u0004 \u0005[\u0006מחלוקת \u0005שני תנאים ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' עקיבא; מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 האומרת שנביא שהדיח בחנק היא כשיטת \u0003ר' שמעון ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא\u0004 שר' שמעון היה תלמיד מובהק לו. ואילו \u0003ברייתא\u0004 זו ששנינו בה שלדעת ר' עקיבא זר ששימש דינו כנביא שהדיח ודינו בסקילה היא כדעת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 שחלקו על ר' שמעון, \u0003ו\u0004אף היא \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' עקיבא.\u0004",""],["\u0003אלו הן הנחנקין\u0004 כעונש על חטאיהם: \u0003המכה אביו\u0004 או את \u0003אמו, וגונב נפש מישראל, וזקן ממרא על פי\u0004 (את פי) \u0003בית דין, ונביא השקר, והמתנבא בשם עבודה זרה, והבא על אשת איש, וזוממי בת כהן,\u0004 כלומר, העדים המעידים בשקר על בת כהן שזנתה שאינם נדונים בשריפה כמותה, אלא בחנק \u0003ו\u0004כן \u0003בועלה\u0004 ידון בחנק כבא על אשת איש סתם.","ושואלים: \u0003מכה אביו ואמו מנלן\u0004 \u0005[מנין לנו]\u0006 שעונשו בחנק? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומכה אביו ואמו מות יומת\"\u0004 (שמות כא, טו) ולא נתפרש מה מיתתו, \u0003וכל מיתה האמורה בתורה סתם אינה אלא חנק.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 שפירושו שהבן נענש רק אם מכה את אביו \u0003עד דקטיל ליה מיקטל\u0004 \u0005[שהורג אותו]!\u0006 ודוחים: וכי \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כדבר הזה? הלא לדבריך אם \u0003קטל חד\u0004 \u0005[הרג אחד],\u0006 סתם אדם, דינו \u0003בסייף ו\u0004אם הרג את \u0003אביו\u0004 יהיה דינו \u0003בחנק\u0004 בלבד, והדבר אינו מסתבר!","ומקשים: \u0003הניחא\u0004 \u0003למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח\u0006 \u0005ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003חנק קל\u0004 מסייף ולכן קל וחומר הוא, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003חנק חמור\u0004 מסייף, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא,\u0004 יש להביא ראיה אחרת, \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"מכה איש ומת מות יומת\"\u0004 (שם יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"או באיבה הכהו בידו וימת\u0004 מות יומת המכה רוצח הוא\u0003\"\u0004 (במדבר לה, כא), \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כל היכא דאיכא\u0004 \u0005[מקום שיש,\u0006 שנאמרה\u0005]\u0006 לשון \u0003\"הכאה\" סתם\u0004 בלא התוצאה של אותה הכאה (\"ומת\", \"וימות\") — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מיתה הוא\u0004 אלא מכה כפשוטה.","ומסבירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והיה צריך לכתוב]\u0006 את הכתוב \u0003\"מכה איש\" ואיצטריך למכתב\u0004 \u0005[והיה צריך לכתוב]\u0006 \u0003\"כל מכה נפש\",\u0004 שאין אחד מהם מיותר. \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"מכה איש ומת\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא מכה \u0003איש דבר מצוה\u0004 \u0005[ש\u0006הוא \u0005בן\u0006 קיום \u0005מצוות],\u0006 שמקיים מצוות וחייב בהן — \u0003אין\u0004 \u0005[כן],\u0006 חייב מיתה עליו, אבל ההורג \u0003קטן\u0004 — \u0003לא.\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כל מכה נפש\".\u0004 \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003\"כל מכה נפש\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003אפילו נפלים\u0004 בכלל זה, שהרי נפש כלשהי להם, ו\u0003אפילו בן שמונה\u0004 ילד שנולד לאחר הריון של שמונה חדשים בלבד שנחשב כמת, לפי שלא יוכל לחיות הרבה, שאפילו הם בכלל נפש, על כן \u0003צריכי\u0004 \u0005[הוצרך]\u0006 לומר \"מכה איש\" שמשמעו איש גדול, ואם כן צריכין אנו לשני הכתובים.","ומקשים: אם זה הוא המקור שיהא חייב על הכאת אביו, אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא עביד ביה\u0004 \u0005[עשה בו ]\u0006 \u0003חבורה\u0004, \u0003אלמה תנן\u0004 \u0005[\u0006ו\u0005מדוע שנינו\u0006 במשנה\u0005]\u0006 ש\u0003המכה אביו\u0004 או את \u0003אמו\u0004 \u0003אינו חייב עד שיעשה בהן חבורה!\u0004","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מכה אדם\" ו\"מכה בהמה\"\u0004 (\"ומכה בהמה ישלמנה ומכה אדם יומת\" (ויקרא כד, כא) באותו כתוב, ללמדנו בהשוואה זו \u0003מה מכה בהמה\u0004 אינו חייב \u0003עד דעביד\u0004 \u0005[שיעשה]\u0006 \u0003בה\u0004 \u0003חבורה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 \u0003\"נפש\"\u0004 כאמור \"ומכה נפש בהמה ישלמנה\" (שם יח), כלומר, שאינו חייב אלא על מכה שיש בה מקצת הוצאת נפש (והדם הוא הנפש. \u0005ראה דברים יב, כג\u0006), וחבורה יש בה הוצאת נפש כזו, אף \u0003מכה אדם\u0004 אינו חייב \u0003עד דעביד\u0004 \u0005[שיעשה]\u0006 \u0003חבורה\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב ירמיה\u0004 על הוכחה זו: \u0003אלא מעתה\u0004 אם \u0003הכחישה באבנים\u0004 (שם עליה משא כבד של אבנים) עד שניזוקה הבהמה או מתה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא מיחייב\u0004 \u0005[יתחייב]\u0006 עליה כיון שלא עשה בה חבורה?! והלא ברור לנו שחייב אדם לשלם על נזקים שגרם לרכוש חבירו בכל אופן! \u0003אלא\u0004 כך יש לומר: \u0003אם\u0004 \"מכה נפש\" \u0003אינו ענין לנפש בהמה, דהא אי נמי\u0004 \u0005[שהרי אם גם כן]\u0006 \u0003הכחישה באבנים חייב, תניהו ענין לנפש אדם, שמכה אדם\u0004, והכוונה למכה אביו, שהרי רק על הכאה זו חייבים מיתה — אינו חייב אלא בעשיית חבורה, שהיא הוצאת נפש.","ומקשים: אם כן שהדבר נלמד במדת \"אם אינו ענין\" מ\"נפש בהמה\", \u0003אלא הקישא\u0004 \u0005[ההיקש]\u0006 שבפסוק בין מכה אדם ומכה בהמה \u0003למה לי,\u0004 לשם מה היא? ומשיבים: \u0003לכדתניא דבי\u0004 \u0005[לפי ששנינו בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 שפורטו כמה טעמים שלמדים מכאן שכל מי שמואשם (אף כי לא חוייב) בהריגת נפש אדם — פטור מכל עונשי ממון על נזקים שהזיק אגב כך.","ושואלים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח למי שיש לו,\u0006 שמקבל\u0005]\u0006 את שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה, אלא למאן דלית ליה\u0004 \u0005[למי שאין לו,\u0006 שאינו מקבל\u0005]\u0006 את שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה, היקישא\u0004 \u0005[היקש]\u0006 \u0003למה לי?\u0004","ומסבירים: לשיטה זו למדים מן ההיקש, \u0003מה מכה בהמה לרפואה פטור\u0004 שהרי התכוון לרפאה — \u0003אף מכה אדם לרפואה פטור,\u0004 ואין מחייבים אותו כלל אם גרם למוות, משום שכוונתו היתה לצורך רפואה.","\u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003בן מהו\u0004 הדין לענין \u0003שיקיז דם לאביו?\u0004 האם יש בכך משום עושה חבורה באביו, או לא? \u0003רב מתנא אמר:\u0004 נאמר \u0003\"ואהבת לרעך כמוך\"\u0004 (שם יט, יח), ללמד כשם שאתה רוצה שירפאוך בשעת הצורך, אף לחברך צריך אתה לדאוג לרפאותו, ולא הוזהרו ישראל מלעשות לחבריהם אלא דבר שאינם רוצים לעשות לעצמם, וממילא המרפא את אביו מותר לכתחילה. \u0003רב דימי בר חיננא אמר:\u0004 לומדים זאת מן ההשוואה של \u0003\"מכה אדם\" ו\"מכה בהמה\"\u0004 הכתובים באותו פסוק; \u0003מה מכה בהמה לרפואה פטור\u0004 — \u0003אף מכה אדם לרפואה פטור.\u0004","מסופר כי \u0003רב לא שביק לבריה למישקל ליה סילוא\u0004 \u0005[התיר לבנו להוציא ממנו קוץ]\u0006 שמא יעשה בו חבורה בלא כוונה. \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא לא שביק לבריה למיפתח ליה כוותא\u0004 \u0005[הניח לבנו שיפתח לו פתח\u0006 בתוך בועה של מוגלה\u0005],\u0006 \u0003דילמא חביל\u0004 \u0005[שמא\u0006 אגב כך \u0005יחבול\u0006 בו\u0005],\u0006 ויעשה חבורה כל שהיא, \u0003והוה ליה\u0004 \u0005[ותהיה זו]\u0006 \u0003שגגת איסור.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם חושש הוא לכך, \u0003אחר נמי\u0004 \u0005[גם כן]\u0006 שאינו בנו אל יטפל בו, שהרי אסור לכל אדם מישראל להכות ולחבול בחבירו! ומשיבים: עדיין יש הבדל, שכן \u0003אחר\u0004 אם יגרום חבלה בשגגה תהא זו \u0003שיגגת לאו,\u0004 שהאיסור להכות חבירו הוא \"לא תעשה\" בלבד, ואילו \u0003בנו\u0004 שעושה זאת הרי זו \u0003שגגת חנק.\u0004","ומקשים: \u0003והדתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מחט של יד\u0004 (מחט לתפירה) מותרת בטלטול בשבת משום שמותר \u0003ליטול בה את הקוץ\u0004 בשבת. ויש לשאול: מדוע התירו להוציא קוץ בשבת, \u0003ליחוש דילמא חביל\u0004 \u0005[\u0006ו\u0005שיחשוש שמא\u0006 תוך כדי הוצאת הקוץ בשבת יגרום \u0005חבלה],\u0006 \u0003והויא לה\u0004 \u0005[ותהיה זו]\u0006 \u0003שגגת סקילה,\u0004 שגגה של עבירה שעונשה סקילה, שהרי עשיית חבורה איסור מן התורה הוא בשבת!","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 בשבת גם אם יחבול בו בשגגה הלא \u0003מקלקל הוא\u0004 ואילו בשבת חייבים רק על מלאכה שיש בה תיקון.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שה\u0003מקלקל\u0004 בשבת \u0003פטור\u0004 בכל מקרה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שאף המקלקל \u0003חייב\u0004 במקרים מסויימים אם יש לו הנאה בדבר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והלא יצטרכו לאסור הוצאת קוץ!","ומשיבים: \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי\u0006 הוא החכם ש\u0005שמעת אותו אומר]\u0006 כי ה\u0003מקלקל בחבורה חייב\u0004 אם יש בכך צד מסויים של תיקון? — הלא \u0003ר' שמעון היא,\u0004"],["\u0003ור' שמעון האמר\u0004 \u0005[הרי\u0006 הוא עצמו \u0005אמר]\u0006 כי \u0003כל מלאכה שאינה צריכה לגופה\u0004 — \u0003פטור עליה,\u0004 כלומר, העושה מלאכה שאיננו צריך לגופה של מלאכה זו אלא נזקק רק לתוצאת לוואי הנובעת ממנה — פטור אם עשאה בשבת. ואף כאן, כיון שאינו צריך לגופה של חבלה זו — ממילא פטור עליה.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב ששת: בן מהו שיעשה שליח\u0004 בית דין \u0003לאביו להכותו\u0004 אם התחייב אביו מלקות, \u0003ולקללו\u0004 אם התחייב קללה או נידוי?","\u0003אמר להו\u0004 \u0005[להם]\u0006 בשאלה: \u0003ואחר מי\u0004 \u0005[האם]\u0006 \u0003התירו?\u0004 כלומר, הלא בדרך כלל אסור להכות ולקלל אדם מישראל, וכיצד עושה זאת שליח בית דין? \u0003אלא\u0004 בהכרח עושים זאת משום ש\u0003כבוד שמים עדיף,\u0004 ולשם כבוד המקום רשאי הוא לפגוע בכבודו של אדם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בבן \u0003כבוד שמים עדיף\u0004 מכבוד אביו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003ומה מי שמצוה להכותו,\u0004 כלומר, אדם שנתחייב מלקות ומצווה שליח בית הדין להכותו, בכל זאת \u0003מצוה\u0004 כללית היא \u0003שלא להכותו\u0004 במקרה אחר אפילו מכה אחת, \u0003מי שאינו מצוה להכותו, אינו דין שמצוה שלא להכותו\u0004 כלל?","דברים אלה הסתומים במקצת יש להם לכאורה ביאור אחד, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 במקום שאמר שמצווה ושאינו מצוה, בשניהם מדובר \u0003במקום מצוה,\u0004 שלפי הדין חייב הוא מלקות, אלא \u0003הא\u0004 \u0005[זה]\u0006 שמצווה שלא להכותו הכוונה היא \u0003בבנו\u0004 שאסור לו להכות את אביו אפילו במקום שיש מצוה להלקות, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שמצווה להכותו הכוונה היא \u0003באחר\u0004 במקום מצוה של מלקות ארבעים!","את הקושיה דוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בנו ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003אחר,\u0004 ולא חילקה הברייתא באלה. \u0003ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 שיש הבדל בין הדינים: \u0003כאן\u0004 שאמרו שמצוה להכותו, מדובר \u0003במקום מצוה,\u0004 שהוא שליח בית דין המצווה על כך, \u0003כאן\u0004 שאמרו שאסור להכותו, הריהו \u0003שלא במקום מצוה.\u0004","\u0003והכי קתני\u0004 \u0005[וכך שנה],\u0006 כך יש להבין את הברייתא: \u0003ומה במקום מצוה, שמצוה\u0004 השליח \u0003להכותו\u0004 — בכל זאת \u0003מצוה שלא להכותו\u0004 אפילו מכה אחת יותר מן הצווי, כאמור: \"פן יוסיף להכותו\" (דברים כה, ג), \u0003שלא במקום מצוה,\u0004 כלומר, באדם שאינו חייב מלקות, \u0003שאינו מצוה\u0004 כלל השליח \u0003להכותו\u0004 — \u0003אינו דין שמצוה שלא להכותו?\u0004 ולמדנו איפוא מכתוב זה איסור כללי שלא להכות אדם מישראל בכל מקרה ולא רק לענין מלקות ארבעים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003היוצא ליהרג,\u0004 שנתחייב באחת ממיתות בית דין, \u0003ובא בנו והכהו\u0004 או \u0003קיללו\u0004 — \u0003חייב\u0004 מיתה משום מכה אביו או משום מקלל אביו. \u0003בא אחר והכהו וקיללו\u0004 — \u0003פטור. והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בהלכה זו, ומתקשים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003בנו, ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003אחר,\u0004 שהאחר פטור ובנו חייב? \u0003ואמר רב חסדא:\u0004 מדובר כאן במקרה מסויים, \u0003במסרבין\u0004 (דוחקים ומפצירים) \u0003בו לצאת\u0004 להיהרג \u0003ואינו יוצא,\u0004 וצריך להוציאו ולדחפו בעל כרחו למקום הריגתו. ולפי דרכנו למדנו שאפילו במקרה כזה שבנו נעשה כשליח בית דין, בכל זאת אסור להכותו!","ודוחים: \u0003רב ששת מוקי לה\u0004 \u0005[מעמיד אותה,\u0006 את ההלכה הזו\u0005]\u0006 \u0003ב\u0004מקרה \u0003שאין מסרבין בו לצאת\u0004 אלא היה הולך מעצמו, והיו מכים אותו מפני הכעס, ואותו אדם מכה אותו מרצונו ולא בשליחות בית דין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אחר נמי\u0004 \u0005[גם כן]\u0006 יהיה חייב, שהרי אסור להכות ולקלל אדם מישראל! ומשיבים: אם \u0003אחר\u0004 עושה זאת הריהו פטור משום שהנידון \u0003גברא קטילא\u0004 \u0005[\u0006כ\u0005אדם הרוג]\u0006 \u0003הוא\u0004 נחשב, שכיון שנגמר דינו למיתה הרי זה כאילו מת כבר, ואין נענשים על מכתו וביושו.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ששת\u0004 עצמו: אם \u0003ביישו\u0004 את חבירו כשהיה החבר \u0003ישן,\u0004 ולא ידע שביישוהו, \u0003ומת\u0004 החבר בתוך כך — בכל זאת \u0003חייב\u0004 לשלם עבור הבושת ליורשים, ומשמע שאף אדם העומד למות אסור לביישו, והמביישו חייב! ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003בשהכהו הכאה\u0004 קלה \u0003שאין בה שוה פרוטה,\u0004 ואם כן אין מה לשלם ליורשים.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אמי אמר ר' יוחנן:\u0004 אם \u0003הכהו\u0004 את חבירו \u0003הכאה שאין בה שוה פרוטה,\u0004 כיון שאינו משלם קנס במקרה כזה — \u0003לוקה,\u0004 על שעבר על איסור התורה \"לא יוסיף... להכותו\"! ומדוע יהא זה פטור מכל וכל? ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"פטור\" דקאמר\u0004 \u0005[שאמר]\u0006 באותה ברייתא? אין כוונתו שהוא פטור לגמרי, אלא שהוא \u0003פטור מממון,\u0004 אבל אכן חייב מלקות.","ומקשים: אם כך, שאתה מפרש שהוא פטור לענין ממון, \u0003מכלל\u0004 הדברים אתה למד כי \u0003בנו\u0004 שנאמר בו \u0003חייב\u0004 יהא חייב לשלם \u0003ממון?\u0004 והלא אמרנו שאינו כן! \u0003אלא\u0004 בהכרח יש לפרש לענין הבן חייב ופטור \u0003בדינו, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בדינו,\u0004 באחר העושה כן לא לענין ממון מדובר אלא על עצם העבירה!","\u0003אלא\u0004 יש לדחות הסבר זה ולתרץ כך: \u0003אחר היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שהוא \u0003פטור\u0004 מעונש, לפי ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז), ו\"בעמך\" משמעו: \u0003בעושה מעשה עמך,\u0004 שנוהג מנהג ישראל כשרים, אבל עבריין אין איסור לקללו.","ומקשים: \u0003התינח\u0004 \u0005[זה נוח]\u0006 לענין \u0003קללה\u0004 שמצאת שיש הבדל בין רשע לצדיק, \u0003הכאה מנלן\u0004 \u0005[מנין לנו]\u0006 שהמכה אדם רשע פטור? ומשיבים: \u0003דמקשינן\u0004 \u0005[שאנו משווים]\u0006 בכתובים \u0003הכאה לקללה,\u0004 שהרי דין מכה אביו ומקלל אביו כתובים קרוב זה לזה (שם כא טו, שם יז).","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שהאיסור אינו חל על רשעים, אם כן \u0003בנו נמי\u0004 \u0005[גם כן]\u0006 יהא פטור על הכאת וקללת אב רשע, שהרי אינו בכלל האיסור! ומשיבים: \u0003כ\u0004פי ש\u0003אמר\u0004 \u0003רב פינחס\u0004 לענין אחר שמדובר שם \u0003בשעשה תשובה,\u0004 וכיון שעשה תשובה הריהו מעתה \"עושה מעשה עמך\" אף שעדיין חייב מיתת בית דין על העבירה שעבר, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בשעשה תשובה.\u0004","ומקשים: אם מדובר כאן בשעשה תשובה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אחר נמי\u0004 \u0005[גם כן]\u0006 יהיה חייב על הכאתו ובזיונו, שהרי הוא \"עושה מעשה עמך\"! \u0003אמר רב מרי:\u0004 צריך לדייק מן הכתוב גם כך: נשיא \u0003\"בעמך\"\u0004 — \u0003במקוים שבעמך\u0004 כשאר העם החיים ופועלים, אבל אדם העומד למות אינו נקרא \"בעמך\" ופטור על קללתו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003בנו נמי\u0004 \u0005[גם כן]\u0006 יהא פטור, אם אין חייבים על קללתו של אדם שאינו מקויים וחי,"],["\u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 \u0003לאחר מיתה\u0004 שהבן חייב בקללת אביו גם לאחר מות אביו, לכן לגבי הבן אין הבדל אם האב חי או מת.","למרות הקושיות הרבות לא נמצאה ראיה גמורה לסתור את דברי רב ששת, ולכן שואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה,\u0006 על הלכה זו\u0005],\u0006 מה המסקנה? \u0003אמר רבה בר רב הונא, וכן תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: לכל אין הבן נעשה שליח לאביו להכותו ולקללו, חוץ מ\u0004כאשר אביו \u0003מסית, שהרי אמרה תורה: \"ולא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט), אבל בעבירות אחרות אסור לבן לעשות זאת וייעשה אחר שליח לדבר.","\u0003המכה אביו ואמו אינו חייב\u0004 מיתה \u0003עד שיעשה בהן חבורה. זה חומר\u0004 (חומרה) שיש \u0003במקלל\u0004 אביו \u0003מבמכה, שהמקלל\u0004 אביו ואמו \u0003לאחר מיתה\u0004 — \u0003חייב, והמכה\u0004 אותם \u0003לאחר מיתה\u0004 — \u0003פטור,\u0004 שהרי אינו עושה חבורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"אביו ואמו קלל\u0004 דמיו בו\u0003\"\u0004 (ויקרא כ, ט), וכוונת הדברים היא: אפילו \u0003לאחר מיתה. שיכול\u0004 הייתי לומר: \u0003הואיל וחייב במכה וחייב במקלל, מה מכה אינו חייב אלא מחיים\u0004 של אביו ואמו — \u0003אף המקלל אינו חייב אלא מחיים.\u0004","\u0003ועוד,\u0004 לכאורה \u0003קל וחומר\u0004 הוא: \u0003ומה מכה שעשה בו\u0004 את זה שהוא בבחינת \u0003\"שלא בעמך\" כ\u0004זה שהוא \u0003ב\u0004בחינת \u0003\"עמך\",\u0004 שאסור להכות גם אדם רשע, בכל זאת \u0003לא חייב בו לאחר מיתה, מקלל שלא עשה בו\u0004 את זה שהוא \u0003\"שלא בעמך\" כ\"בעמך\",\u0004 שהרי האיסור לקלל הוא רק על מי שהוא \"בעמך\" ואינו רשע, \u0003אינו דין שלא חייב בו לאחר מיתה?\u0004","\u0003תלמוד לומר: \"אביו ואמו קלל\"\u0004 — מכל מקום, אפילו \u0003לאחר מיתה.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' יונתן,\u0004 שעל פי שיטתו \u0003מייתר ליה קרא\u0004 \u0005[מיותר לו פסוק\u0006 זה\u0005]\u0006 \u0003\"אביו ואמו\",\u0004 ולכן לומד הוא מן החזרה. \u0003אלא ל\u0004שיטת \u0003ר' יאשיה\u0004 החולק, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \"כי \u0003איש איש\u0004 אשר יקלל את אביו ואמו\" (ויקרא כ, ט): \u0003מה תלמוד לומר \"איש איש\",\u0004 מה טעמה של הכפלה זו? — \u0003לרבות\u0004 לא רק איש שמשמעו גבר אלא גם \u0003בת, טומטום ואנדרוגינוס. \"אשר יקלל את אביו ואת אמו\"\u0004 (יקרא כ, ט), \u0003אין לי אלא\u0004 שקלל את \u0003אביו ואמו\u0004 יחד, ואולם כאשר קילל את \u0003אביו שלא\u0004 קילל את \u0003אמו,\u0004 או שקילל \u0003את\u0004 \u0003אמו שלא\u0004 קילל את \u0003אביו, מניין\u0004 שחייב? — \u0003תלמוד לומר\u0004 פעם שניה: \u0003\"אביו ואמו קלל\"\u0004 — ללמד שעל כל אחד מהם יידון לעצמו, כאילו נאמר \u0003אביו קלל,\u0004 או \u0003אמו קלל,\u0004 אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר:\u0004 בכתוב זה וכל כיוצא בזה שמוזכרים שנים יחד \u0003משמע שניהן כאחד, ומשמע\u0004 כל \u0003אחד ואחד בפני עצמו, עד שיפרט לך הכתוב\u0004 במפורש \u0003\"יחדיו\",\u0004 שאז הכוונה היא לשניהם יחד ולא לכל אחד לעצמו.","ואם כן לשיטת ר' יאשיה \"אביו ואמו קילל\" אינו מיותר שהרי למד ממנו לקללת כל אחד מהם לחוד, ולשיטתו \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 שחייב לאחר מיתה? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 הוא לומד זאת\u0005]\u0006 \u0003מ\u0004פסוק נוסף באותו ענין: \u0003\"ומקלל אביו ואמו מות יומת\"\u0004 (שמות כא, יז).","ומקשים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יונתן\u0005]\u0006 מה עושה הוא בכתוב יתר זה? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[צריך לו]\u0006 כדי \u0003לרבות בת, טומטום ואנדרוגינוס\u0004 לאיסור קללה.","ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו,\u0006 שילמד הלכה זו\u0005]\u0006 מן ההכפלה \u0003\"איש איש\"!\u0004 ומשיבים: לדעתו \u0003דברה תורה כלשון בני אדם\u0004 ואין ללמוד מכאן הלכה כלשהי, אלא כפל מילים זה מסגנון לשון המקרא הוא.","לגופה של המשנה שואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 גם כך: \u0003חומר במכה מבמקלל, שהמכה עשה בו\u0004 את זה שהוא בבחינת \u0003\"שלא בעמך\" כ\u0004זה שהוא \u0003ב\u0004בחינת \u0003\"עמך\", מה שאין כן במקלל.\u0004 ומשיבים: התנא במשנתנו אינו פוסק כך כי \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מקשינן\u0004 \u0005[משוים אנו]\u0006 \u0003הכאה לקללה,\u0004 ואף על הכאה אינו חייב לגבי כל אדם.","ומציעים: \u0003לימא הני תנאי כהני תנאי\u0004 \u0005[האם לומר\u0006 ש\u0005תנאים אלה\u0006 סוברים \u0005כתנאים אלה]?\u0006 \u0003דתני חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003כותי\u0004 (שומרוני) \u0003אתה מצווה על הכאתו,\u0004 כלומר, אסור לך להכותו, \u0003ואי\u0004 (אין) \u0003אתה מצווה על קללתו\u0004 שהרי ודאי אינו נוהג בדיני ישראל, ורשע הוא. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אי אתה מצווה לא על קללתו ולא על הכאתו.\u0004","\u0003סברוה\u0004 \u0005[סברו],\u0006 הניחו מתחילה חכמים שדנו בנושא כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בשתי הברייתות מוסכם כי \u0003כותים גירי אמת הן\u0004 מתחילתם, והריהם מאז כיהודים לכל דבר, אלא שהם יהודים פורקי עול. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה הם חולקים]:\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 בבריייתא השניה \u0005סבור]\u0006 כי \u0003מקשינן\u0004 \u0005[משווים אנו]\u0006 \u0003הכאה לקללה,\u0004 ולכן כיון שרשעים הם מותר גם להכותם וגם לקללם, \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 בבריייתא הראשונה \u0005סבור]\u0006 כי \u0003לא מקשינן\u0004 \u0005[אין אנו משווים]\u0006 \u0003הכאה לקללה,\u0004 ורק על קללת אדם רשע פטורים, ולכן פטורים על קללת כותי!","את ההסבר הזה דוחים: \u0003לא, דכולי עלמא לא מקשינן\u0004 \u0005[לדעת הכל אין אנו משווים]\u0006 \u0003הכאה לקללה, והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006ענין \u0005זה נחלקו],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה\u0006 בבריייתא הראשונה \u0005סבור]\u0006 כי \u0003כותים גירי אמת הן\u0004 ונוהגים בהם כאילו היו ישראלים רשעים, ולכן אף שמותר לקללם בשל היותם רשעים, מכל מקום אסור להכותם. \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 בברייתא השניה \u0005סבור]\u0006 כי \u0003כותים גירי אריות הן\u0004 ומתחילה לא נתגיירו אלא מאונס ומפחד האריות (מלכים ב' פרק יז), ולא היתה גרותם אמיתית, משום כך אין דינם כלל כיהודים אלא כגויים הם, ולכך מותר הן לקללם והן להכותם.","על סברה זו מקשים: \u0003אי הכי, היינו דקתני עלה\u0004 \u0005[אם כך, זהו ששנינו עליה]\u0006 על הלכה זו ברייתא האומרת שאין מצווים לא על הכאתו ולא על קללתו \u0003ושורו כישראל,\u0004 שלענין שורו שנגח שור של איש ישראל דנים אותו בדיני ישראל לענין תם ומועד, הרי שוודאי אפילו לתנא זה הכותי כיהודי הוא! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בהיקישא פליגי\u0004 \u0005[ב\u0006ענין ה\u0005היקש,\u0006 ההשוואה, הם \u0005חלוקים]\u0006 אם הכאה דינה כקללה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003הגונב נפש מישראל\u0004 שנמנה בראשית הפרק עם חייבי מיתת חנק — \u0003אינו חייב עד שיכניסנו,\u0004 את הנגנב, \u0003לרשותו. ר' יהודה אומר: עד שיכניסנו לרשותו וישתמש בו, שנאמר:\u0004 \"כי ימצא איש גונב נפש מאחיו מבני ישראל \u0003והתעמר בו ומכרו\u0004 ומת הגנב ההוא\" (דברים כד, ז), והוא מפרש \"והתעמר\" שיעשה בו עבודה. \u0003הגונב את בנו\u0004 של עצמו ומוכרו, \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה מחייב, וחכמים פוטרין. גנב\u0004 את \u0003מי ש\u0004הוא \u0003חציו עבד וחציו בן חורין\u0004 (כגון שהיה שייך לשני שותפים ואחד מהם שחררו), \u0003ר' יהודה מחייב, וחכמים פוטרין.\u0004","על דברי המשנה תוהים: \u0003ו\u0004כי ה\u0003תנא קמא לא בעי\u0004 \u0005[הראשון,\u0006 חכמים, \u0005אינו צריך]\u0006 \u0003עימור\u0004 שישתמש בו, כדי לחייבו?! והרי נאמר הדבר בתורה במפורש! \u0003אמר ר' אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא:\u0004 לגבי המקרה של \u0003עימור פחות משוה פרוטה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 האם עבדות כזו קרויה \"עימור\", או לא. שחכמים סבורים שאין לדבר קצבה, ור' יהודה אומר שצריך להשתמש בו בעבודה השווה פרוטה לפחות, שיש לה משמעות חוקית.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: גנבו ומכרו\u0004 כשהיה \u0003ישן, מהו?\u0004 אם \u0003מכר אשה לעוברה,\u0004 שגנב אשה הרה ונתכוון למכור רק את העובר \u0003מהו?\u0004 האם \u0003יש דרך עימור בכך, או אין דרך עימור בכך?\u0004 כי שמא באופן זה אין איסור עימור.","על ספיקות ר' ירמיה תוהים: \u0003ותיפוק ליה\u0004 \u0005[ושיצא לו]\u0006 פתרון השאלה \u0003דליכא\u0004 \u0005[ש\u0006הרי \u0005אין כאן]\u0006 \u0003עימור כלל,\u0004 שכן הוא עצמו לא עשה באלה כל מלאכה, שכן איזו מלאכה אפשר לעשות בישן או בעובר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה כזה: באיש \u0003ישן\u0004 — \u0003דזגא עליה\u0004 \u0005[שנשען עליו],\u0006 ו\u0003אשה\u0004 מעוברת — \u0003דאוקמא באפי זיקא\u0004 \u0005[שהעמידה בפני הרוח]\u0006 כדי שלא תנשוב בו, ואם כן עשה הוא עצמו שימוש באלה. והשאלה היא: אם \u0003דרך עימור בכך,\u0004 שאפשר לומר שדברים אלה קרויים עימור, \u0003או אין דרך עימור בכך?\u0004 ושואלים: אכן, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 בשאלה זו? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה, ללא פתרון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 ממה שנאמר: \u0003\"כי ימצא איש גנב נפש מאחיו\"\u0004 (שם כד, ז), \u0003אין לי\u0004 ללמוד \u0003אלא איש שגנב,\u0004 ואולם \u0003אשה מניין\u0004 שחייבת על גניבת אדם? — \u0003תלמוד לומר: \"וגנב איש\u0004 ומכרו ונמצא בידו מות יומת","\u0003\"\u0004(שמות כא, טז), שכיון שלא פירש מי הגונב — אף אשה בכלל זה. \u0003אין לי\u0004 דין זה \u0003אלא\u0004 ב\u0003איש שגנב בין אשה ובין איש\u0004 (שהרי נאמר בו \"גונב נפש\") \u0003ו\u0004כן \u0003אשה שגנבה איש,\u0004 ואולם \u0003אשה שגנבה אשה מניין\u0004 שחייבת? — \u0003תלמוד לומר: \"ומת הגנב ההוא\"\u0004 (דברים כד, ז) — \u0003מכל מקום,\u0004 יהא אשר יהא הגנב והנגנב.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו נושא: \u0003\"כי ימצא איש גנב נפש מאחיו\"\u0004 — \u0003אחד הגונב את האיש, ואחד הגונב את האשה, ואחד גר, ואחד עבד משוחרר וקטן\u0004 — \u0003חייב,\u0004 שכל אלה בכלל \"נפש\" הם. \u0003גנבו ולא מכרו,\u0004 או \u0003מכרו ועדיין ישנו ברשותו\u0004 — \u0003פטור. מכרו לאביו\u0004 של הנגנב \u0003או לאחיו, או לאחד מן הקרובים\u0004 — \u0003חייב. הגונב את העבדים\u0004 — \u0003פטור.\u0004"]]};
